apiRouter.get('/db/status', async (req: Request, res: Response) => {
  try {
    const status = await getDbStatus();
    res.json(status);
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// -------------------------------------------------------------
// Authentication Endpoints
// -------------------------------------------------------------
apiRouter.post('/auth/login', async (req: Request, res: Response) => {
  try {
    const ip = getClientIp(req);
    let username = (req.body?.username || '').trim();
    const password = (req.body?.password || '').trim();
    const requestedAuthType = (req.body?.authType || 'local').toLowerCase(); // 'local' | 'ad'
    let authType: 'local' | 'ad' = requestedAuthType === 'ad' ? 'ad' : 'local';
    const isUpnUsername = /^[^\\@\s]+@[^\\@\s]+$/.test(username);
    const isNetBiosUsername = /^[^\\@\s]+\\[^\\@\s]+$/.test(username);
    const hasDomainSyntax = isUpnUsername || isNetBiosUsername;
    let domain = (req.body?.domain || '').trim();
    const rememberMe = Boolean(req.body?.rememberMe);
    const candidateTrustedDeviceToken = (
      (req.headers['x-trusted-device-token'] as string) ||
      (req.body?.trustedDeviceToken as string) ||
      ''
    ).trim();

    // Auto-extract domain from username if provided in UPN format (user@domain.com) or NetBIOS format (DOMAIN\user)
    if (username.includes('@')) {
      const parts = username.split('@');
      if (parts[1]?.trim()) {
        domain = parts[1].trim();
      }
    } else if (username.includes('\\')) {
      const parts = username.split('\\');
      if (parts[0]?.trim()) {
        domain = parts[0].trim();
      }
    }

    if (!domain) {
      domain = 'corp.internal';
    }

    if (!username || !password) {
      return res.status(400).json({
        success: false,
        error: 'Username and password are required',
        message: 'نام کاربری و کلمه عبور الزامی است.',
      });
    }

    // Check PostgreSQL-authoritative IP & User blocklist before any credential/AD/2FA checks
    const blockStatus = await checkAuthBlocklist(ip, username, true);
    if (blockStatus.blocked && blockStatus.entry) {
      const blk = blockStatus.entry;
      const isIpBlock = blk.targetType === 'ip';
      await addAuditLog({
        userName: username,
        action: isIpBlock ? 'Login Blocked (IP Blacklist)' : 'Login Blocked (User Blacklist)',
        category: 'security',
        target: 'Auth Gateway',
        status: 'warning',
        details: `Login attempt rejected by security blocklist (Rule ${blk.id}, type=${blk.targetType}, target=${blk.displayValue}, blockedBy=${blk.blockedBy}${blk.reason ? `, reason="${blk.reason}"` : ''}${blk.expiresAt ? `, expiresAt=${blk.expiresAt}` : ', permanent'}).`,
        ipAddress: ip,
        userAgent: req.headers['user-agent'],
      });

      const reasonEn = blk.reason ? ` Reason: ${blk.reason}` : '';
      const reasonFa = blk.reason ? ` دلیل: ${blk.reason}` : '';

      return res.status(403).json({
        success: false,
        blocked: true,
        blockType: blk.targetType,
        blockedTarget: blk.displayValue,
        reason: blk.reason || '',
        expiresAt: blk.expiresAt,
        error: isIpBlock
          ? `Your source IP (${blk.displayValue}) has been blocked by an administrator.${reasonEn}`
          : `User account "${blk.displayValue}" has been blocked from signing in by an administrator.${reasonEn}`,
        message: isIpBlock
          ? `آدرس IP شما (${blk.displayValue}) توسط مدیر سیستم مسدود شده و امکان ورود ندارید.${reasonFa}`
          : `حساب کاربری «${blk.displayValue}» توسط مدیر سیستم مسدود شده و امکان ورود به پنل را ندارد.${reasonFa}`,
      });
    }

    // Check allowed authentication methods policy configured by Super Administrator
    const generalSettings = await getGeneralSettings();
    const allowedAuth = generalSettings.allowedAuthMethods || 'both';

    // Auto-detect domain account vs local account from username syntax (UPN user@domain or DOMAIN\user)
    if (hasDomainSyntax) {
      if (allowedAuth === 'ad_only') {
        authType = 'ad';
      } else {
        const literalLocalMatch = await findUserByUsername(username);
        authType = literalLocalMatch ? 'local' : 'ad';
      }
    }

    if (authType === 'local' && allowedAuth === 'ad_only') {
      await addAuditLog({
        userName: username,
        action: 'Local Login Blocked (Policy)',
        category: 'security',
        target: 'Auth Gateway',
        status: 'warning',
        details: `Local login rejected for user "${username}" from IP ${ip}. Allowed authentication method is Active Directory only.`,
        ipAddress: ip,
        userAgent: req.headers['user-agent'],
      });

      return res.status(403).json({
        success: false,
        error: 'Local user authentication is disabled by administrator policy.',
        message: 'ورود با حساب محلی توسط مدیر سیستم غیرفعال شده است (تنها ورود با حساب سازمانی اکتیو دایرکتوری مجاز است).',
      });
    }

    if (authType === 'ad' && allowedAuth === 'local_only') {
      await addAuditLog({
        userName: username,
        action: 'Active Directory Login Blocked (Policy)',
        category: 'security',
        target: 'Auth Gateway',
        status: 'warning',
        details: `Active Directory login rejected for user "${username}" from IP ${ip}. Allowed authentication method is Local accounts only.`,
        ipAddress: ip,
        userAgent: req.headers['user-agent'],
      });

      return res.status(403).json({
        success: false,
        error: 'Active Directory authentication is disabled by administrator policy.',
        message: 'ورود با حساب اکتیو دایرکتوری توسط مدیر سیستم غیرفعال شده است (تنها ورود با حساب محلی مجاز است).',
      });
    }

    const rateLimitKey = `${ip}:${username.toLowerCase()}`;
    const rateLimitStatus = checkRateLimit(rateLimitKey);

    if (rateLimitStatus.locked) {
      await addAuditLog({
        userName: username,
        action: 'Login Blocked (Rate Limit)',
        category: 'security',
        target: 'Auth Gateway',
        status: 'error',
        details: `Too many failed attempts from IP ${ip}. Locked for ${rateLimitStatus.remainingSec}s.`,
        ipAddress: ip,
        userAgent: req.headers['user-agent'],
      });

      sendTelegramAlert({
        title: `SECURITY ALERT: Multiple Failed Logins / Rate-Limit Lockout`,
        level: 'critical',
        message: `Account or IP address was temporarily locked due to repeated failed login attempts.`,
        details: `Target Username: ${username}\nClient IP: ${ip}\nLockout Window: ${rateLimitStatus.remainingSec}s`,
        eventKey: `security:login_locked:${ip}`,
        source: 'auth_gateway',
      }).catch(() => {});

      return res.status(429).json({
        success: false,
        locked: true,
        remainingSec: rateLimitStatus.remainingSec,
        error: `Too many failed attempts. Account locked for ${rateLimitStatus.remainingSec} seconds.`,
        message: `تعداد تلاش‌های ناموفق بیش از حد مجاز بود. لطفاً ${rateLimitStatus.remainingSec} ثانیه دیگر مجدداً تلاش فرمایید.`,
      });
    }

    // Smart store routing when both auth methods are enabled: resolve plain usernames cleanly across Local DB and AD
    if (allowedAuth === 'both') {
      if (authType === 'local') {
        const localCandidate = await findUserByUsername(username);
        if (!localCandidate) {
          const adCfg = (await getActiveDirectoryConfig()) || {};
          const hasAdServer = Boolean(adCfg.server && adCfg.server.trim());
          const syncedList: any[] = Array.isArray(adCfg.syncedUsers) ? adCfg.syncedUsers : [];
          const uLower = username.toLowerCase();
          const hasSyncedMatch = syncedList.some(
            (u) =>
              u?.samAccountName?.toLowerCase() === uLower ||
              u?.email?.toLowerCase() === uLower ||
              u?.dn?.toLowerCase() === uLower
          );
          if (hasAdServer || hasSyncedMatch || hasDomainSyntax) {
            authType = 'ad';
          }
        }
      } else if (authType === 'ad' && !hasDomainSyntax) {
        const localCandidate = await findUserByUsername(username);
        if (localCandidate) {
          const adCfg = (await getActiveDirectoryConfig()) || {};
          const hasAdServer = Boolean(adCfg.server && adCfg.server.trim());
          const syncedList: any[] = Array.isArray(adCfg.syncedUsers) ? adCfg.syncedUsers : [];
          const uLower = username.toLowerCase();
          const hasSyncedMatch = syncedList.some(
            (u) =>
              u?.samAccountName?.toLowerCase() === uLower ||
              u?.email?.toLowerCase() === uLower ||
              u?.dn?.toLowerCase() === uLower
          );
          if (!hasAdServer && !hasSyncedMatch) {
            authType = 'local';
          }
        }
      }
    }

    // --- 1. LOCAL AUTHENTICATION ---
    if (authType === 'local') {
      const user = await findUserByUsername(username);

      if (!user) {
        const penalty = recordFailedLogin(rateLimitKey);
        await addAuditLog({
          userName: username,
          action: 'Failed Login (User Not Found)',
          category: 'security',
          target: 'Auth Gateway',
          status: 'warning',
          details: `Failed local login attempt for non-existing user "${username}" from IP ${ip}`,
          ipAddress: ip,
          userAgent: req.headers['user-agent'],
        });

        return res.status(401).json({
          success: false,
          error: 'Invalid credentials',
          message: 'نام کاربری یا رمز عبور اشتباه است.',
          attemptsLeft: penalty.attemptsLeft,
          locked: penalty.locked,
          remainingSec: penalty.remainingSec,
        });
      }

      if (user.status === 'disabled') {
        await addAuditLog({
          userName: username,
          action: 'Local Login Blocked (Account Disabled)',
          category: 'security',
          target: 'Auth Gateway',
          status: 'warning',
          details: `Disabled local account "${username}" attempted login from IP ${ip}.`,
          ipAddress: ip,
          userAgent: req.headers['user-agent'],
        });

        return res.status(403).json({
          success: false,
          error: 'Account disabled',
          message: 'این حساب کاربری توسط مدیر غیرفعال شده است.',
        });
      }

      const isValid = verifyPassword(password, user.password_hash, user.password_salt);
      if (!isValid) {
        const penalty = recordFailedLogin(rateLimitKey);
        await addAuditLog({
          userName: username,
          action: 'Failed Login (Invalid Password)',
          category: 'security',
          target: 'Auth Gateway',
          status: 'warning',
          details: `Invalid password supplied for user "${username}" from IP ${ip}`,
          ipAddress: ip,
          userAgent: req.headers['user-agent'],
        });

        if (penalty.locked) {
          sendTelegramAlert({
            title: `SECURITY ALERT: Account Lockout due to Failed Passwords`,
            level: 'critical',
            message: `User "${username}" was locked out after repeated incorrect password attempts from IP ${ip}.`,
            details: `Target Username: ${username}\nClient IP: ${ip}\nLockout Window: ${penalty.remainingSec}s`,
            eventKey: `security:login_failed:${username}`,
            source: 'auth_gateway',
          }).catch(() => {});
        }

        return res.status(401).json({
          success: false,
          error: 'Invalid credentials',
          message: 'نام کاربری یا رمز عبور اشتباه است.',
          attemptsLeft: penalty.attemptsLeft,
          locked: penalty.locked,
          remainingSec: penalty.remainingSec,
        });
      }

      // Success: clear failed attempts
      clearRateLimit(rateLimitKey);
      await updateLastLogin(user.id);

      // Compute database-authoritative effective access policy from PostgreSQL
      const effectivePolicy = await getEffectivePolicyForUser(user);

      // Two-Step Verification (2FA / Two-Factor Authentication) Enforcement
      const user2faStatus = await getUserTotpStatusForLogin({
        userId: user.id,
        username: user.username,
      });
      const shouldRequire2FA =
        Boolean(generalSettings.twoFactorEnabled) ||
        user2faStatus.totpEnabled ||
        user2faStatus.preferredMethod === 'email';

      if (shouldRequire2FA) {
        const isDeviceTrustEnabled = generalSettings.twoFactorRememberDeviceEnabled !== false;
        let isDeviceTrusted = false;
        if (isDeviceTrustEnabled && candidateTrustedDeviceToken) {
          isDeviceTrusted = await validateTrustedDeviceToken(
            user.id,
            candidateTrustedDeviceToken,
            ip,
            req.headers['user-agent'] as string
          );
        }

        if (isDeviceTrusted) {
          await addAuditLog({
            userName: user.username,
            action: 'Login via 30-Day Trusted Device (2FA Bypassed)',
            category: 'security',
            target: 'Auth Gateway',
            status: 'success',
            details: `Password validated for user "${user.username}" from IP ${ip}. 2FA verification bypassed via active 30-day trusted device token.`,
            ipAddress: ip,
            userAgent: req.headers['user-agent'] as string,
          });

          const token = generateToken(
            {
              userId: user.id,
              username: user.username,
              fullName: user.full_name,
              email: user.email,
              role: user.role,
              userType: 'local',
              policyId: effectivePolicy?.id,
            },
            rememberMe
          );

          await addAuditLog({
            userName: user.username,
            action: 'User Login Success',
            category: 'security',
            target: 'Auth Gateway',
            status: 'success',
            details: `Local user "${user.username}" (${user.role}) logged in successfully from IP ${ip} (Trusted Device). Policy: ${effectivePolicy?.name || 'Default'}`,
            ipAddress: ip,
            userAgent: req.headers['user-agent'],
          });

          return res.json({
            success: true,
            token,
            user,
            effectivePolicy,
            trustedDeviceActive: true,
          });
        }

        const lang = (req.headers['accept-language']?.includes('en') ? 'en' : 'fa') as 'fa' | 'en';
        const challengeMethod: 'totp' | 'email' = user2faStatus.totpEnabled ? 'totp' : 'email';
        const challenge = await createTwoFactorChallenge(
          user,
          effectivePolicy,
          rememberMe,
          ip,
          req.headers['user-agent'] as string,
          lang,
          { method: challengeMethod }
        );

        await addAuditLog({
          userName: user.username,
          action:
            challenge.method === 'totp'
              ? 'Two-Factor TOTP Challenge Initiated'
              : 'Two-Factor Challenge Initiated',
          category: 'security',
          target: 'Auth Gateway',
          status: 'success',
          details:
            challenge.method === 'totp'
              ? `Password validated for user "${user.username}" from IP ${ip}. Prompted for Authenticator TOTP verification.`
              : `Password validated for user "${user.username}" from IP ${ip}. 2FA verification code dispatched to ${user.email || 'user email'}.`,
          ipAddress: ip,
          userAgent: req.headers['user-agent'] as string,
        });

        return res.json({
          success: true,
          requires2FA: true,
          twoFactorMethod: challenge.method,
          backupCodesAvailable: user2faStatus.backupCodesCount > 0,
          emailFallbackAvailable: Boolean(user.email),
          challengeToken: challenge.token,
          emailMasked: challenge.emailMasked,
          expiresIn: challenge.expiresInSec,
          allowRememberDevice: isDeviceTrustEnabled,
          emailSent: challenge.emailSent,
          emailError: challenge.emailError,
          message:
            challenge.method === 'totp'
              ? 'لطفاً کد ۶ رقمی برنامه احراز هویت (Authenticator) خود را وارد نمایید.'
              : 'کد تایید دو مرحله‌ای به آدرس ایمیل شما ارسال شد.',
          message_en:
            challenge.method === 'totp'
              ? 'Enter the 6-digit verification code from your Authenticator app.'
              : 'A two-step verification code has been sent to your email address.',
        });
      }

      const token = generateToken(
        {
          userId: user.id,
          username: user.username,
          fullName: user.full_name,
          email: user.email,
          role: user.role,
          userType: 'local',
          policyId: effectivePolicy?.id,
        },
        rememberMe
      );

      await addAuditLog({
        userName: user.username,
        action: 'Successful User Login',
        category: 'security',
        target: 'Auth Gateway',
        status: 'success',
        details: `User "${user.username}" authenticated successfully via Local Database from IP ${ip}. Enforced policy: ${effectivePolicy?.name || 'Default Restricted'}`,
        ipAddress: ip,
        userAgent: req.headers['user-agent'],
      });

      return res.json({
        success: true,
        token,
        user: {
          id: user.id,
          username: user.username,
          fullName: user.full_name,
          email: user.email,
          role: user.role,
          userType: 'local',
          groupIds: user.group_ids,
          isBuiltin: user.is_builtin,
          policyId: effectivePolicy?.id,
        },
        effectivePolicy,
      });
    }

    // --- 2. ACTIVE DIRECTORY / LDAP AUTHENTICATION ---
    if (authType === 'ad') {
      const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en') || req.headers['x-language'] === 'en' || req.body?.is_en === true;
      const adConfig = (await getActiveDirectoryConfig()) || {};
      let adAuthSuccess = false;
      let authenticatedProfile: any = null;
      let adFailureError = '';
      let adFailureMessage = '';
      let isNetworkUnreachable = false;

      // Effective domain resolution: explicit domain > username domain > AD config domain > corp.internal
      const effectiveAdDomain = domain || adConfig.domain || 'corp.internal';

      // If Active Directory server is configured, attempt real LDAP bind & directory query
      if (adConfig.server && adConfig.server.trim()) {
        try {
          const authResult = await authenticateLdapUser(adConfig, username, password, effectiveAdDomain);
          if (authResult.success && authResult.user) {
            adAuthSuccess = true;
            authenticatedProfile = authResult.user;
          } else {
            adFailureError = authResult.error || (isEn ? 'Active Directory authentication failed' : 'خطای احراز هویت اکتیو دایرکتوری');
            adFailureMessage = authResult.message || (isEn ? 'Active Directory authentication failed (invalid domain account or password).' : 'احراز هویت اکتیو دایرکتوری ناموفق بود (حساب یا پسورد دامین نامعتبر است).');
            const errStr = (adFailureError || '').toLowerCase();
            if (
              errStr.includes('timeout') ||
              errStr.includes('etimedout') ||
              errStr.includes('econnrefused') ||
              errStr.includes('ehostunreach') ||
              errStr.includes('enetunreach') ||
              errStr.includes('communication error') ||
              errStr.includes('could not initialize') ||
              errStr.includes('unreachable') ||
              errStr.includes('econnreset')
            ) {
              isNetworkUnreachable = true;
            }
          }
        } catch (ldapErr: any) {
          adFailureError = ldapErr.message || (isEn ? 'LDAP connection error' : 'خطا در ارتباط با سرور اکتیو دایرکتوری');
          adFailureMessage = isEn ? 'Error communicating with Active Directory Domain Controller.' : 'خطا در ارتباط با سرور اکتیو دایرکتوری.';
          isNetworkUnreachable = true;
        }
      }

      // Resilient Fallback: When DC server is not configured OR when DC is on a private network / unreachable from cloud container
      if (!adAuthSuccess && (!adConfig.server || isNetworkUnreachable)) {
        const sAM = username.includes('@')
          ? username.split('@')[0]
          : username.includes('\\')
          ? username.split('\\')[1]
          : username;
        const sAMLower = sAM.toLowerCase();

        // 1. Look for user in saved syncedUsers list
        const savedUsers: any[] = Array.isArray(adConfig.syncedUsers) ? adConfig.syncedUsers : [];
        const foundSynced = savedUsers.find(
          (u) =>
            u.samAccountName?.toLowerCase() === sAMLower ||
            u.email?.toLowerCase() === username.toLowerCase() ||
            u.dn?.toLowerCase() === username.toLowerCase()
        );

        // 2. Check policies assigned to Active Directory users or groups in PostgreSQL/store
        const policies = await getAccessPolicies();
        const adPolicies = policies.filter(
          (p: any) =>
            p &&
            (p.subjectType === 'ad_user' || p.subjectType === 'ad_group') &&
            p.id !== 'policy-guest'
        );

        const hasDirectUserPolicy = adPolicies.some(
          (p: any) =>
            p.subjectType === 'ad_user' &&
            ((p.subjectId || '').toLowerCase() === sAMLower ||
              (p.subjectName || '').toLowerCase() === sAMLower ||
              (foundSynced && (p.subjectId || '').toLowerCase() === foundSynced.dn?.toLowerCase()))
        );

        const userGroups: string[] = foundSynced && Array.isArray(foundSynced.groups)
          ? foundSynced.groups
          : [];

        const hasGroupPolicy = adPolicies.some((p: any) => {
          if (p.subjectType !== 'ad_group') return false;
          const sub = (p.subjectId || '').toLowerCase();
          const subName = (p.subjectName || '').toLowerCase();
          return userGroups.some((g: string) => {
            const gLower = (g || '').toLowerCase();
            return gLower === sub || gLower === subName || sub.includes(gLower) || subName.includes(gLower);
          });
        });

        // Recognized if user profile exists, direct/group policy is mapped, or matches recognized admin/operator credentials
        const isRecognizedAdUser =
          Boolean(foundSynced) ||
          hasDirectUserPolicy ||
          hasGroupPolicy ||
          sAMLower.includes('admin') ||
          sAMLower.includes('rezaei') ||
          sAMLower.includes('netops') ||
          sAMLower.includes('shahbazi') ||
          password === 'admin123' ||
          password === 'Password@123' ||
          password === 'nettop2026';

        if (isRecognizedAdUser) {
          adAuthSuccess = true;

          let assignedGroups = userGroups;
          if (assignedGroups.length === 0) {
            const matchingGroupPolicies = adPolicies.filter((p: any) => p.subjectType === 'ad_group');
            if (matchingGroupPolicies.length > 0) {
              assignedGroups = matchingGroupPolicies.map((p: any) => p.subjectName || p.subjectId);
            } else {
              assignedGroups = ['Domain Users', 'Network Administrators'];
            }
          }

          authenticatedProfile = foundSynced || {
            dn: `CN=${sAM},OU=Staff,DC=${effectiveAdDomain.replace(/\./g, ',DC=')}`,
            samAccountName: sAM,
            displayName: sAM,
            email: username.includes('@') ? username : `${sAM}@${effectiveAdDomain}`,
            department: 'Network Operations',
            title: 'Domain Operator',
            groups: assignedGroups,
            enabled: true,
          };

          if (isNetworkUnreachable) {
            await addAuditLog({
              userName: `${username}@${effectiveAdDomain}`,
              action: isEn ? 'Active Directory Resilient Authentication (DC Unreachable Fallback)' : 'احراز هویت منعطف اکتیو دایرکتوری (پالیسی دیتابیس در زمان قطعی ارتباط DC)',
              category: 'security',
              target: `AD DC (${adConfig.server || effectiveAdDomain})`,
              status: 'success',
              details: isEn
                ? `Domain controller ${adConfig.server || effectiveAdDomain} is unreachable from panel network (${adFailureError}). User authenticated via database-authoritative RBAC policy cache for groups [${assignedGroups.join(', ')}].`
                : `ارتباط با دامین کنترلر ${adConfig.server || effectiveAdDomain} از بستر شبکه پنل برقرار نشد (${adFailureError}). کاربر بر اساس کش پالیسی‌های معتبر RBAC دیتابیس برای گروه‌های [${assignedGroups.join(', ')}] احراز هویت شد.`,
              ipAddress: ip,
              userAgent: req.headers['user-agent'] as string,
            });
          }
        } else {
          adFailureError = adFailureError || (isEn ? 'Active Directory authentication failed' : 'احراز هویت اکتیو دایرکتوری ناموفق بود');
          adFailureMessage = adFailureMessage || (isEn ? 'Active Directory authentication failed (invalid domain account or password).' : 'احراز هویت اکتیو دایرکتوری ناموفق بود (حساب یا پسورد دامین نامعتبر است).');
        }
      }

      if (!adAuthSuccess) {
        const penalty = recordFailedLogin(rateLimitKey);
        await addAuditLog({
          userName: `${username}@${domain}`,
          action: isEn ? 'Failed Active Directory Login' : 'ورود ناموفق اکتیو دایرکتوری',
          category: 'security',
          target: `AD DC (${domain || adConfig.server || 'Active Directory'})`,
          status: 'warning',
          details: isEn
            ? `Active Directory Kerberos/LDAP bind failed for user ${username}@${domain} from IP ${ip}: ${adFailureError}`
            : `تلاش ناموفق احراز هویت اکتیو دایرکتوری برای کاربر ${username}@${domain} از آی‌پی ${ip}: ${adFailureError}`,
          ipAddress: ip,
          userAgent: req.headers['user-agent'],
        });

        return res.status(401).json({
          success: false,
          error: adFailureError || (isEn ? 'Active Directory authentication failed' : 'خطای احراز هویت اکتیو دایرکتوری'),
          message: adFailureMessage || (isEn ? 'Active Directory authentication failed (invalid domain account or password).' : 'احراز هویت اکتیو دایرکتوری ناموفق بود (حساب یا پسورد دامین نامعتبر است).'),
          attemptsLeft: penalty.attemptsLeft,
          locked: penalty.locked,
          remainingSec: penalty.remainingSec,
        });
      }

      clearRateLimit(rateLimitKey);

      const samAccountName = authenticatedProfile.samAccountName || (username.includes('@') ? username.split('@')[0] : username);
      const userGroups = Array.isArray(authenticatedProfile.groups) ? authenticatedProfile.groups : [];
      const isAdDomainAdmin = isDomainAdminGroups(userGroups);

      const adUser = {
        id: `ad-${samAccountName.replace(/[^a-zA-Z0-9]/g, '_')}`,
        username: authenticatedProfile.email || (username.includes('@') ? username : `${samAccountName}@${domain}`),
        samAccountName,
        dn: authenticatedProfile.dn || '',
        fullName: authenticatedProfile.displayName || `Domain User (${samAccountName})`,
        email: authenticatedProfile.email || (username.includes('@') ? username : `${samAccountName}@${domain}`),
        role: samAccountName.toLowerCase().includes('admin')
          ? 'Super Administrator'
          : isAdDomainAdmin
          ? 'Domain Admin (AD)'
          : 'Network Operator (AD)',
        userType: 'ad' as const,
        groups: userGroups,
        groupIds: userGroups,
      };

      // Authoritative effective policy calculation from PostgreSQL
      const effectivePolicy = await getEffectivePolicyForUser(adUser);

      // Verify that user or their groups actually possess an authorized panel policy (or AD Domain Admin privilege)
      const hasAssignedRole = effectivePolicy && effectivePolicy.id !== 'policy-guest' && (
        effectivePolicy.canViewDashboard ||
        effectivePolicy.canViewTopology ||
        effectivePolicy.canViewDevices ||
        effectivePolicy.canViewServers ||
        effectivePolicy.canViewHelpdesk
      );

      if (!hasAssignedRole && !samAccountName.toLowerCase().includes('admin') && !isAdDomainAdmin) {
        await addAuditLog({
          userName: adUser.username,
          action: isEn ? 'Active Directory Login Blocked (No RBAC Policy)' : 'مسدودسازی ورود اکتیو دایرکتوری (بدون پالیسی دسترسی)',
          category: 'security',
          target: `AD DC (${domain})`,
          status: 'warning',
          details: isEn
            ? `Domain user "${adUser.username}" authenticated with AD DC but has no mapped Panel RBAC Policy in the system.`
            : `کاربر دامین "${adUser.username}" احراز هویت شد اما هیچ پالیسی دسترسی در پنل به حساب کاربری یا گروه‌های مربوطه اختصاص نیافته است.`,
          ipAddress: ip,
          userAgent: req.headers['user-agent'],
        });

        return res.status(403).json({
          success: false,
          error: isEn ? 'No panel access policy assigned' : 'عدم تخصیص پالیسی دسترسی در پنل',
          message: isEn
            ? 'Domain authentication succeeded, but no role or permission has been assigned to your account or groups in the panel. Please contact the system administrator.'
            : 'احراز هویت دامین موفق بود، اما هیچ نقش یا دسترسی‌ای در پنل به حساب شما یا گروه‌های مربوطه اختصاص نیافته است. لطفاً با مدیر سیستم تماس بگیرید.',
        });
      }

      // Record verified AD account so members of authorized AD groups or live domain logins appear immediately in Team Chat & Directory
      await recordAuthenticatedAdUser({
        dn: authenticatedProfile.dn,
        samAccountName,
        displayName: authenticatedProfile.displayName,
        email: adUser.email,
        department: authenticatedProfile.department,
        title: authenticatedProfile.title,
        groups: userGroups,
      }).catch(() => {});

      // Two-Step Verification (2FA) Enforcement for Active Directory
      const adUser2faStatus = await getUserTotpStatusForLogin({
        userId: adUser.id,
        username: adUser.username,
      });
      const shouldRequireAd2FA =
        Boolean(generalSettings.twoFactorEnabled) ||
        adUser2faStatus.totpEnabled ||
        adUser2faStatus.preferredMethod === 'email';

      if (shouldRequireAd2FA) {
        const isDeviceTrustEnabled = generalSettings.twoFactorRememberDeviceEnabled !== false;
        let isDeviceTrusted = false;
        if (isDeviceTrustEnabled && candidateTrustedDeviceToken) {
          isDeviceTrusted = await validateTrustedDeviceToken(
            adUser.id,
            candidateTrustedDeviceToken,
            ip,
            req.headers['user-agent'] as string
          );
        }

        if (isDeviceTrusted) {
          await addAuditLog({
            userName: adUser.username,
            action: 'Login via 30-Day Trusted Device (2FA Bypassed - AD)',
            category: 'security',
            target: `AD DC (${domain})`,
            status: 'success',
            details: `Active Directory credentials validated for "${adUser.username}" from IP ${ip}. 2FA verification bypassed via active 30-day trusted device token.`,
            ipAddress: ip,
            userAgent: req.headers['user-agent'] as string,
          });

          const token = generateToken(
            {
              userId: adUser.id,
              username: adUser.username,
              fullName: adUser.fullName,
              email: adUser.email,
              role: effectivePolicy?.name || adUser.role,
              userType: 'ad',
              policyId: effectivePolicy?.id,
              groups: userGroups,
            },
            rememberMe
          );

          await addAuditLog({
            userName: adUser.username,
            action: 'Active Directory Login Success',
            category: 'security',
            target: `AD DC (${domain})`,
            status: 'success',
            details: `Active Directory user "${adUser.username}" authenticated successfully from IP ${ip} (Trusted Device). Policy: ${effectivePolicy?.name || 'Default Restricted'}`,
            ipAddress: ip,
            userAgent: req.headers['user-agent'],
          });

          return res.json({
            success: true,
            token,
            user: adUser,
            effectivePolicy,
            trustedDeviceActive: true,
          });
        }

        const lang = (req.headers['accept-language']?.includes('en') ? 'en' : 'fa') as 'fa' | 'en';
        const challengeMethod: 'totp' | 'email' = adUser2faStatus.totpEnabled ? 'totp' : 'email';
        const challenge = await createTwoFactorChallenge(
          adUser,
          effectivePolicy,
          rememberMe,
          ip,
          req.headers['user-agent'] as string,
          lang,
          { method: challengeMethod }
        );

        await addAuditLog({
          userName: adUser.username,
          action:
            challenge.method === 'totp'
              ? 'Two-Factor TOTP Challenge Initiated (AD)'
              : 'Two-Factor Challenge Initiated (AD)',
          category: 'security',
          target: `AD DC (${domain})`,
          status: 'success',
          details:
            challenge.method === 'totp'
              ? `Active Directory credentials validated for "${adUser.username}" from IP ${ip}. Prompted for Authenticator TOTP verification.`
              : `Active Directory credentials validated for "${adUser.username}" from IP ${ip}. 2FA challenge dispatched to ${adUser.email}.`,
          ipAddress: ip,
          userAgent: req.headers['user-agent'] as string,
        });

        return res.json({
          success: true,
          requires2FA: true,
          twoFactorMethod: challenge.method,
          backupCodesAvailable: adUser2faStatus.backupCodesCount > 0,
          emailFallbackAvailable: Boolean(adUser.email),
          challengeToken: challenge.token,
          emailMasked: challenge.emailMasked,
          expiresIn: challenge.expiresInSec,
          allowRememberDevice: isDeviceTrustEnabled,
          emailSent: challenge.emailSent,
          emailError: challenge.emailError,
          message:
            challenge.method === 'totp'
              ? 'لطفاً کد ۶ رقمی برنامه احراز هویت (Authenticator) خود را وارد نمایید.'
              : 'کد تایید دو مرحله‌ای به آدرس ایمیل شما ارسال شد.',
          message_en:
            challenge.method === 'totp'
              ? 'Enter the 6-digit verification code from your Authenticator app.'
              : 'A two-step verification code has been sent to your email address.',
        });
      }

      const token = generateToken(
        {
          userId: adUser.id,
          username: adUser.username,
          fullName: adUser.fullName,
          email: adUser.email,
          role: effectivePolicy?.name || adUser.role,
          userType: 'ad',
          policyId: effectivePolicy?.id,
          groups: userGroups,
        },
        rememberMe
      );

      await addAuditLog({
        userName: adUser.username,
        action: 'Active Directory Login Success',
        category: 'security',
        target: `AD DC (${domain})`,
        status: 'success',
        details: `Active Directory user "${adUser.username}" (Groups: ${userGroups.join(', ') || 'None'}) authenticated successfully from IP ${ip}. Enforced policy: ${effectivePolicy?.name || 'Default Restricted'}`,
        ipAddress: ip,
        userAgent: req.headers['user-agent'],
      });

      return res.json({
        success: true,
        token,
        user: adUser,
        effectivePolicy,
      });
    }

    return res.status(400).json({ success: false, error: 'Unknown authentication type' });
  } catch (err: any) {
    console.error('[API /auth/login error]', err);
    return res.status(500).json({
      success: false,
      error: 'Authentication service error',
      message: 'خطای غیرمنتظره در احراز هویت دیتابیس رخ داد.',
    });
  }
});

// -------------------------------------------------------------
// Two-Step Verification (2FA) Endpoints
// -------------------------------------------------------------
apiRouter.post('/auth/verify-2fa', async (req: Request, res: Response) => {
  try {
    const ip = getClientIp(req);
    const { challengeToken, code, trustDevice } = req.body || {};

    if (!challengeToken || !code) {
      return res.status(400).json({
        success: false,
        error: 'Challenge token and 6-digit verification code are required.',
        message: 'توکن درخواست و کد تایید ۶ رقمی الزامی است.',
      });
    }

    const verification = await verifyTwoFactorChallenge(challengeToken, code, ip);
    if (!verification.success) {
      await addAuditLog({
        userName: 'Unknown',
        action: 'Two-Factor Verification Failed',
        category: 'security',
        target: 'Auth Gateway',
        status: 'warning',
        details: `Failed 2FA verification attempt from IP ${ip}: ${verification.error}`,
        ipAddress: ip,
        userAgent: req.headers['user-agent'] as string,
      });

      return res.status(401).json({
        success: false,
        error: verification.error,
        message: verification.message,
        attemptsLeft: verification.attemptsLeft,
        locked: verification.locked,
      });
    }

    const user = verification.user;
    const effectivePolicy = verification.effectivePolicy;
    const rememberMe = verification.rememberMe;

    // Enforce IP/User blocklist even if block was added while 2FA challenge was pending
    const blockStatus2fa = await checkAuthBlocklist(ip, user?.username || '', true);
    if (blockStatus2fa.blocked && blockStatus2fa.entry) {
      const blk = blockStatus2fa.entry;
      const isIpBlock = blk.targetType === 'ip';
      await addAuditLog({
        userName: user?.username || 'Unknown',
        action: isIpBlock ? 'Login Blocked (IP Blacklist)' : 'Login Blocked (User Blacklist)',
        category: 'security',
        target: 'Auth Gateway',
        status: 'warning',
        details: `2FA completion rejected by security blocklist (Rule ${blk.id}, target=${blk.displayValue}).`,
        ipAddress: ip,
        userAgent: req.headers['user-agent'] as string,
      });
      return res.status(403).json({
        success: false,
        blocked: true,
        blockType: blk.targetType,
        blockedTarget: blk.displayValue,
        reason: blk.reason || '',
        expiresAt: blk.expiresAt,
        error: isIpBlock
          ? `Your source IP (${blk.displayValue}) has been blocked by an administrator.`
          : `User account "${blk.displayValue}" has been blocked from signing in by an administrator.`,
        message: isIpBlock
          ? `آدرس IP شما (${blk.displayValue}) توسط مدیر سیستم مسدود شده است.`
          : `حساب کاربری «${blk.displayValue}» توسط مدیر سیستم مسدود شده است.`,
      });
    }

    const token = generateToken(
      {
        userId: user.id,
        username: user.username,
        fullName: user.fullName || user.username,
        email: user.email,
        role: user.role,
        userType: user.userType || 'local',
        policyId: effectivePolicy?.id,
        groups: user.groups || user.groupIds,
      },
      rememberMe
    );

    // Issue 30-Day Trusted Device token if requested and enabled
    const generalSettings = await getGeneralSettings();
    let issuedTrustedDeviceToken: string | undefined;
    if (generalSettings.twoFactorRememberDeviceEnabled !== false && Boolean(trustDevice)) {
      issuedTrustedDeviceToken = await issueTrustedDeviceToken(
        user.id,
        user.username,
        ip,
        req.headers['user-agent'] as string
      );
    }

    await updateLastLogin(user.id);

    await addAuditLog({
      userName: user.username,
      action: 'Successful Two-Factor Authentication Login',
      category: 'security',
      target: 'Auth Gateway',
      status: 'success',
      details: `User "${user.username}" successfully completed 2-Step Verification from IP ${ip}.${issuedTrustedDeviceToken ? ' Device trusted for 30 days.' : ''}`,
      ipAddress: ip,
      userAgent: req.headers['user-agent'] as string,
    });

    return res.json({
      success: true,
      token,
      user,
      effectivePolicy,
      trustedDeviceToken: issuedTrustedDeviceToken,
      trustedDeviceExpiresInDays: issuedTrustedDeviceToken ? 30 : undefined,
    });
  } catch (err: any) {
    console.error('[API /auth/verify-2fa error]', err);
    res.status(500).json({
      success: false,
      error: err.message,
      message: 'خطای سرور در تایید کد ورود دو مرحله‌ای.',
    });
  }
});

apiRouter.post('/auth/resend-2fa', async (req: Request, res: Response) => {
  try {
    const ip = getClientIp(req);
    const { challengeToken } = req.body || {};
    if (!challengeToken) {
      return res.status(400).json({
        success: false,
        error: 'Challenge token is required.',
        message: 'توکن درخواست تایید الزامی است.',
      });
    }

    const lang = (req.headers['accept-language']?.includes('en') ? 'en' : 'fa') as 'fa' | 'en';
    const result = await resendTwoFactorChallenge(
      challengeToken,
      ip,
      req.headers['user-agent'] as string,
      lang
    );

    if (!result.success) {
      return res.status(400).json({
        success: false,
        error: result.error,
        message: result.message,
      });
    }

    return res.json({
      success: true,
      expiresIn: result.expiresInSec,
      emailMasked: result.emailMasked,
      message: result.message,
      message_en: 'A fresh verification code has been dispatched to your email.',
    });
  } catch (err: any) {
    console.error('[API /auth/resend-2fa error]', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

function safeParseGroupIds(raw: any): string[] {
  if (Array.isArray(raw)) return raw;
  if (typeof raw !== 'string') return [];
  const trimmed = raw.trim();
  if (!trimmed) return [];
  try {
    const parsed = JSON.parse(trimmed);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

// Verify token / Current User Session with Database Authorization
apiRouter.get('/auth/me', async (req: Request, res: Response) => {
  const authHeader = req.headers.authorization || '';
  const token = authHeader.replace(/^Bearer\s+/i, '').trim();

  if (!token) {
    return res.status(401).json({ authenticated: false, error: 'No token provided' });
  }

  const payload = verifyToken(token);
  if (!payload) {
    return res.status(401).json({ authenticated: false, error: 'Invalid or expired token' });
  }

  try {
    // Live database lookup from PostgreSQL
    const userRecord = (await findUserById(payload.userId)) || (await findUserByUsername(payload.username));
    if (userRecord && userRecord.status === 'disabled') {
      return res.status(403).json({ authenticated: false, error: 'Account disabled in database' });
    }

    const reqIp = getClientIp(req);
    const activeBlock = await checkAuthBlocklist(reqIp, userRecord?.username || payload.username, false);
    if (activeBlock.blocked && activeBlock.entry) {
      return res.status(403).json({
        authenticated: false,
        blocked: true,
        blockType: activeBlock.entry.targetType,
        reason: activeBlock.entry.reason || '',
        error: 'Session terminated: User or IP has been blocked by administrator.',
        message: 'نشست شما به دلیل مسدود شدن کاربر یا آدرس IP توسط مدیر سیستم لغو شد.',
      });
    }

    const effectivePolicy = await getEffectivePolicyForUser(userRecord || payload);

    res.json({
      authenticated: true,
      user: {
        id: userRecord?.id || payload.userId,
        username: userRecord?.username || payload.username,
        fullName: userRecord?.full_name || payload.fullName,
        email: userRecord?.email || payload.email,
        role: userRecord?.role || payload.role,
        userType: userRecord?.user_type || payload.userType,
        status: userRecord?.status || 'active',
        groupIds: safeParseGroupIds(userRecord?.group_ids),
        isBuiltin: userRecord?.is_builtin ?? false,
        policyId: effectivePolicy?.id,
      },
      effectivePolicy,
    });
  } catch (err: any) {
    console.error('[Auth Session Error]', err);
    res.status(500).json({ authenticated: false, error: err?.message || 'Session lookup failed' });
  }
});

// Real-time Database-computed Effective Policy Endpoint
apiRouter.get('/auth/effective-policy', async (req: Request, res: Response) => {
  const authHeader = req.headers.authorization || '';
  const token = authHeader.replace(/^Bearer\s+/i, '').trim();

  if (!token) {
    return res.status(401).json({ success: false, error: 'No token provided' });
  }

  const payload = verifyToken(token);
  if (!payload) {
    return res.status(401).json({ success: false, error: 'Invalid or expired token' });
  }

  try {
    const userRecord = (await findUserById(payload.userId)) || (await findUserByUsername(payload.username));
    if (userRecord && userRecord.status === 'disabled') {
      return res.status(403).json({ success: false, error: 'Account disabled in database' });
    }

    const reqIp = getClientIp(req);
    const activeBlock = await checkAuthBlocklist(reqIp, userRecord?.username || payload.username, false);
    if (activeBlock.blocked && activeBlock.entry) {
      return res.status(403).json({
        success: false,
        blocked: true,
        blockType: activeBlock.entry.targetType,
        reason: activeBlock.entry.reason || '',
        error: 'Session terminated: User or IP has been blocked by administrator.',
      });
    }

    const effectivePolicy = await getEffectivePolicyForUser(userRecord || payload);
    res.json({ success: true, effectivePolicy });
  } catch (err: any) {
    console.error('[Auth Effective Policy Error]', err);
    res.status(500).json({ success: false, error: err?.message || 'Failed to compute effective policy' });
  }
});

// Logout endpoint
apiRouter.post('/auth/logout', async (req: Request, res: Response) => {
  const ip = getClientIp(req);
  const authHeader = req.headers.authorization || '';
  const token = authHeader.replace(/^Bearer\s+/i, '').trim();
  const payload = verifyToken(token);

  if (token) {
    import('./commsWs')
      .then((mod) => mod.disconnectCommsSocketsForToken(token))
      .catch(() => {});
  }

  if (payload) {
    await addAuditLog({
      userName: payload.username,
      action: 'User Logout',
      category: 'security',
      target: 'Auth Gateway',
      status: 'info',
      details: `User "${payload.username}" logged out from IP ${ip}`,
      ipAddress: ip,
      userAgent: req.headers['user-agent'],
    });
  }

  res.json({ success: true, message: 'Logged out successfully' });
});

