apiRouter.post('/settings/email/test', async (req: Request, res: Response) => {
  try {
    const storedConfig = await getEmailConfig();
    const incomingConfig = req.body?.config || {};
    const to = (req.body?.to || req.body?.recipient || '').trim();
    const subject = req.body?.subject;
    const notes = req.body?.notes;

    if (!to) {
      return res.status(400).json({
        success: false,
        error: 'Destination recipient email address is required for testing.',
        error_fa: 'آدرس ایمیل مقصد برای ارسال تست الزامی است.',
      });
    }

    // Merge incoming config overrides with stored config
    const allowSelfSigned = incomingConfig.allow_self_signed !== undefined
      ? Boolean(incomingConfig.allow_self_signed)
      : (incomingConfig.reject_unauthorized !== undefined
          ? !incomingConfig.reject_unauthorized
          : (storedConfig.allow_self_signed !== undefined ? storedConfig.allow_self_signed : !storedConfig.reject_unauthorized));

    const mergedConfig: EmailConfig = {
      ...storedConfig,
      ...incomingConfig,
      allow_self_signed: allowSelfSigned,
      reject_unauthorized: !allowSelfSigned,
      auth_method: incomingConfig.auth_method || storedConfig.auth_method || 'auto',
      smtp_pass: (incomingConfig.smtp_pass && incomingConfig.smtp_pass !== '••••••••' && incomingConfig.smtp_pass.trim().length > 0)
        ? incomingConfig.smtp_pass.trim()
        : storedConfig.smtp_pass,
    };

    const result = await sendTestEmail({
      config: mergedConfig,
      to,
      subject,
      notes,
    });

    res.json(result);
  } catch (err: any) {
    res.status(500).json({
      success: false,
      error: err.message || 'SMTP test execution failed',
      latencyMs: 0,
    });
  }
});

