// -------------------------------------------------------------
// Database-Authoritative RBAC Device Scoping Endpoints
// -------------------------------------------------------------
function getRawTopologyData(): any {
  try {
    const netPath = path.join(process.cwd(), 'backend', 'network_data.json');
    if (fs.existsSync(netPath)) {
      const data = JSON.parse(fs.readFileSync(netPath, 'utf-8'));
      const rawDevices = data.devices || [];
      const nodes = rawDevices.map((d: any) => ({
        ...d,
        role: d.role || 'Network Device',
        model: d.model || 'Cisco',
        platform: d.platform || 'cisco_ios_xe',
        is_online: d.is_online !== undefined ? d.is_online : true,
        latency_ms: d.latency_ms || 1.0,
        total_ports: d.total_ports || (d.ports ? d.ports.length : 24),
      }));
      return {
        nodes,
        links: data.topology_links || [],
        buildings: Array.from(new Set(rawDevices.map((d: any) => d.building).filter(Boolean))),
        floors: Array.from(new Set(rawDevices.map((d: any) => `${d.building} - ${d.floor}`).filter((f: string) => !f.startsWith('undefined')))),
        summary: {
          total_nodes: nodes.length,
          total_links: (data.topology_links || []).length,
          core_switches: nodes.filter((d: any) => d.type === 'switch' && (d.role || '').includes('Core')).length,
          access_switches: nodes.filter((d: any) => d.type === 'switch' && (d.role || '').includes('Access')).length,
          routers: nodes.filter((d: any) => d.type === 'router').length,
          access_points: nodes.filter((d: any) => d.type === 'access_point').length,
        }
      };
    }
  } catch (err) {
    console.error('[Topology Load Error in routes.ts]', err);
  }
  return { nodes: [], links: [], buildings: [], floors: [], summary: { total_nodes: 0, total_links: 0 } };
}

async function resolveRequestContextPolicy(req: Request): Promise<{
  user: any | null;
  effectivePolicy: any | null;
  isSuperAdmin: boolean;
  allowedDeviceIds: string[] | null;
  allowedServerIds: string[] | null;
}> {
  const authHeader = req.headers.authorization || '';
  const token = authHeader.replace(/^Bearer\s+/i, '').trim();

  if (!token) {
    return { user: null, effectivePolicy: null, isSuperAdmin: false, allowedDeviceIds: null, allowedServerIds: null };
  }

  const payload = verifyToken(token);
  if (!payload) {
    return { user: null, effectivePolicy: null, isSuperAdmin: false, allowedDeviceIds: null, allowedServerIds: null };
  }

  const userRecord = (await findUserById(payload.userId)) || (await findUserByUsername(payload.username));
  if (userRecord && userRecord.status === 'disabled') {
    return { user: null, effectivePolicy: null, isSuperAdmin: false, allowedDeviceIds: [], allowedServerIds: [] };
  }

  let effectivePolicy = await getEffectivePolicyForUser(userRecord || payload);
  const cleanUsername = (userRecord?.username || payload.username || '').toLowerCase();
  const cleanRole = (userRecord?.role || payload.role || '').toLowerCase();
  const isSuperAdmin = cleanUsername === 'admin' || cleanRole.includes('super admin') || cleanRole.includes('administrator');

  // Check role simulation header (only authorized for Super Admins)
  const simulatedHeader = (req.headers['x-simulated-role'] as string) || '';
  if (isSuperAdmin && simulatedHeader && simulatedHeader !== 'actual-user') {
    const policies = await getAccessPolicies();
    const simP = policies.find((p: any) => p.id === simulatedHeader);
    if (simP) {
      let simAllowedDevs: string[] | null = null;
      let simAllowedSrvs: string[] | null = null;

      if (simP.id === 'policy-super-admin') {
        simAllowedDevs = null;
        simAllowedSrvs = null;
      } else {
        // Device scope
        if (simP.targetScope === 'all') {
          simAllowedDevs = null;
        } else if (simP.targetScope === 'groups') {
          const allDeviceGroups = await getDeviceGroups();
          const targetGroupSet = new Set((simP.targetGroupIds || []).map((id: string) => (id || '').trim().toLowerCase()));
          const devSet = new Set<string>();
          for (const g of allDeviceGroups) {
            const gid = (g.id || '').trim().toLowerCase();
            const gname = (g.name || '').trim().toLowerCase();
            if (targetGroupSet.has(gid) || targetGroupSet.has(gname)) {
              const dIds: string[] = Array.isArray(g.deviceIds) ? g.deviceIds : (Array.isArray(g.device_ids) ? g.device_ids : []);
              dIds.forEach((d) => devSet.add(d));
            }
          }
          simAllowedDevs = Array.from(devSet);
        } else if (simP.targetScope === 'specific') {
          simAllowedDevs = Array.isArray(simP.targetDeviceIds) ? simP.targetDeviceIds : [];
        } else {
          simAllowedDevs = [];
        }

        // Server fleet scope: check explicit targetServerScope and targetServerIds
        if (
          simP.targetServerScope === 'specific' ||
          (Array.isArray(simP.targetServerIds) && simP.targetServerIds.length > 0 && simP.targetServerScope !== 'all')
        ) {
          simAllowedSrvs = Array.isArray(simP.targetServerIds) ? simP.targetServerIds : [];
        } else if (simP.targetServerScope === 'all') {
          simAllowedSrvs = null;
        } else if (simP.targetScope === 'all') {
          simAllowedSrvs = null;
        } else if (simP.targetScope === 'groups') {
          const allDeviceGroups = await getDeviceGroups();
          const targetGroupSet = new Set((simP.targetGroupIds || []).map((id: string) => (id || '').trim().toLowerCase()));
          const srvSet = new Set<string>();
          for (const g of allDeviceGroups) {
            const gid = (g.id || '').trim().toLowerCase();
            const gname = (g.name || '').trim().toLowerCase();
            if (targetGroupSet.has(gid) || targetGroupSet.has(gname)) {
              const sIds: string[] = Array.isArray(g.serverIds) ? g.serverIds : (Array.isArray(g.server_ids) ? g.server_ids : []);
              sIds.forEach((s) => srvSet.add(s));
            }
          }
          simAllowedSrvs = Array.from(srvSet);
        } else if (simP.targetScope === 'specific') {
          simAllowedSrvs = Array.isArray(simP.targetServerIds) ? simP.targetServerIds : [];
        } else {
          simAllowedSrvs = [];
        }
      }

      effectivePolicy = {
        ...simP,
        allowedDeviceIds: simAllowedDevs,
        allowedServerIds: simAllowedSrvs,
      };
      return {
        user: userRecord || payload,
        effectivePolicy,
        isSuperAdmin: false,
        allowedDeviceIds: effectivePolicy.allowedDeviceIds,
        allowedServerIds: effectivePolicy.allowedServerIds,
      };
    }
  }

  return {
    user: userRecord || payload,
    effectivePolicy,
    isSuperAdmin,
    allowedDeviceIds: isSuperAdmin ? null : (effectivePolicy?.allowedDeviceIds ?? null),
    allowedServerIds: isSuperAdmin ? null : (effectivePolicy?.allowedServerIds ?? null),
  };
}

/**
 * Infers the granular network equipment action key from the incoming Express Request.
 */
function inferDeviceActionKey(req: Request, deviceId: string): string | null {
  const method = (req.method || 'GET').toUpperCase();
  const rawUrl = req.originalUrl || req.url || '';
  const urlPath = rawUrl.split('?')[0].replace(/\/+$/, '');

  // 1. Save to NVRAM (write_memory)
  if (urlPath.endsWith('/write-memory') || urlPath.endsWith('/save-running')) {
    return 'write_memory';
  }

  // 2. Inspect Ports & Interfaces (inspect_ports)
  if (
    urlPath.includes('/ports') ||
    urlPath.includes('/vlans') ||
    urlPath.endsWith('/interfaces')
  ) {
    return 'inspect_ports';
  }

  // 3. Delete Device (delete_device)
  if (method === 'DELETE' && (urlPath.endsWith(`/devices/${deviceId}`) || urlPath.endsWith(`/${deviceId}`))) {
    return 'delete_device';
  }

  // 4. Edit Device Properties (edit_properties)
  if ((method === 'PUT' || method === 'PATCH') && (urlPath.endsWith(`/devices/${deviceId}`) || urlPath.endsWith(`/${deviceId}`))) {
    return 'edit_properties';
  }

  // 5. Operations: Ping Keepalive (ping_keepalive)
  if (urlPath.endsWith('/operations')) {
    const op = (req.body?.operation || req.body?.action || '').toLowerCase();
    if (op === 'ping' || op === 'keepalive' || !op) {
      return 'ping_keepalive';
    }
  }

  // 6. Terminal & Interactive CLI (terminal)
  if (urlPath.includes('/terminal') || urlPath.includes('/cli')) {
    return 'terminal';
  }

  // 7. Config Templates (apply_template)
  if (urlPath.includes('/template') || urlPath.includes('/apply-config')) {
    return 'apply_template';
  }

  // 8. Web Consoles / Web Configs (web_configs)
  if (urlPath.includes('/web-console') || urlPath.includes('/web-config')) {
    return 'web_configs';
  }

  return null;
}

/**
 * Authoritative security guard for network equipment endpoints.
 * Resolves token-authenticated user policy, verifies if the device is in user's PostgreSQL scope,
 * and validates whether the requested equipment action (NetworkDeviceActionKey) is permitted.
 */
async function assertDeviceScopeAccess(
  req: Request,
  deviceId: string,
  requiredAction?: string,
  options?: { skipApprovalConsume?: boolean }
): Promise<{
  allowed: boolean;
  device: any | null;
  error?: string;
  errorFa?: string;
  status?: number;
  code?: string;
  gatePayload?: any;
  approvedTicketId?: string;
}> {
  const cleanId = (deviceId || '').trim();
  if (!cleanId) {
    return { allowed: false, device: null, error: 'Device ID is required', errorFa: 'شناسه تجهیز الزامی است', status: 400 };
  }

  const device = await getDeviceById(cleanId);
  if (!device) {
    return { allowed: false, device: null, error: 'Device not found', errorFa: 'تجهیز شبکه یافت نشد', status: 404 };
  }

  const context = await resolveRequestContextPolicy(req);
  const { effectivePolicy, isSuperAdmin, allowedDeviceIds } = context;

  // If user is super admin, full unconstrained access is granted
  if (isSuperAdmin) {
    return { allowed: true, device };
  }

  // If no effective policy is resolved (unauthenticated / standalone mode)
  if (!effectivePolicy) {
    return { allowed: true, device };
  }

  // 1. Check explicit policy permission to view network devices
  if (effectivePolicy.canViewDevices === false) {
    return {
      allowed: false,
      device,
      error: 'Access denied: Your account policy prohibits access to Network Equipment Inventory.',
      errorFa: 'عدم دسترسی: حساب شما فاقد مجوز دسترسی به موجودی تجهیزات شبکه است.',
      status: 403,
    };
  }

  // 2. Check device ID in allowedDeviceIds calculated from PostgreSQL device groups
  if (allowedDeviceIds !== null) {
    const allowedSet = new Set(allowedDeviceIds.map((id) => (id || '').trim().toLowerCase()));
    const did = (device.id || '').trim().toLowerCase();
    const dname = (device.name || '').trim().toLowerCase();
    const dip = (device.ip || '').trim().toLowerCase();

    if (!allowedSet.has(did) && !allowedSet.has(dname) && !allowedSet.has(dip)) {
      return {
        allowed: false,
        device,
        error: 'Access denied: You do not have permission to view or manage this network device based on your assigned Device Groups in PostgreSQL.',
        errorFa: 'عدم دسترسی: این تجهیز خارج از محدوده گروه‌های مجاز شما در پایگاه‌داده است.',
        status: 403,
      };
    }
  }

  // 3. Granular Device Action Check (Tri-State: allow / require_approval / deny)
  const action = requiredAction || inferDeviceActionKey(req, cleanId);
  if (action) {
    const decision = evaluateDeviceActionDecision(effectivePolicy, device.id, action);
    if (decision === 'deny') {
      return {
        allowed: false,
        device,
        code: 'RBAC_DENIED',
        error: `Access denied: You do not have permission to execute '${action}' on this device under your RBAC policy.`,
        errorFa: `عدم دسترسی: شما طبق پالیسی امنیتی خود مجوز انجام عملیات «${action}» روی این تجهیز را ندارید.`,
        status: 403,
      };
    }

    if (decision === 'require_approval' && isMutatingDeviceRequest(req, action)) {
      // Allow read baseline inspect_ports middleware to defer to granular port action if caller is executing a port mutation
      const isBaselinePortCheckBeforeMutation =
        Boolean(options?.skipApprovalConsume) &&
        action === 'inspect_ports' &&
        (req.method || 'GET').toUpperCase() !== 'GET';

      if (!isBaselinePortCheckBeforeMutation) {
        const actor = buildApprovalActor(req, context);
        const meta = resolveActionMeta(action);
        const rawActionParams: Record<string, any> | null =
          req.body && typeof req.body === 'object' ? { ...req.body } : {};
        const signedExec = buildSignedHttpExecutionPayload({
          method: req.method || 'POST',
          originalUrl: req.originalUrl || req.url || '',
          body: req.body,
          entityType: 'device',
          entityId: device.id,
          actionKey: action,
          requesterUsername: actor.username,
        });
        if (signedExec && rawActionParams) {
          rawActionParams._httpExecution = signedExec;
        }
        const gateRes = await evaluateApprovalGateForRequest({
          actor,
          effectivePolicy,
          entityType: 'device',
          entityId: device.id,
          entityName: device.name || device.ip || device.id,
          actionKey: action,
          requestedAction: `${meta.labelEn} (${device.name || device.ip || device.id})`,
          commandPreview: buildSafeCommandPreview(req, { device, action }),
          actionParams:
            rawActionParams && Object.keys(rawActionParams).length > 0 ? rawActionParams : null,
          providedApprovalId: extractProvidedApprovalId(req),
        });

        if (!gateRes.allowed) {
          (req as any).__pendingApprovalGatePayload = gateRes.gatePayload;
          return {
            allowed: false,
            device,
            code: 'APPROVAL_REQUIRED',
            gatePayload: gateRes.gatePayload,
            error: gateRes.gatePayload.error,
            errorFa: gateRes.gatePayload.errorFa,
            status: 403,
          };
        }

        delete (req as any).__pendingApprovalGatePayload;
        if (!options?.skipApprovalConsume) {
          (req as any).__approvedTicketCtx = {
            actor,
            ticketId: gateRes.approvedTicket.id,
            grantId: gateRes.activeGrant?.id || null,
            actionKey: action,
            executionNote: `Executed device action '${action}' on ${device.name || device.id} via JIT approval ${gateRes.approvedTicket.id}`,
          };
        }
        return {
          allowed: true,
          device,
          approvedTicketId: gateRes.approvedTicket.id,
        };
      }
    }
  }

  delete (req as any).__pendingApprovalGatePayload;
  return { allowed: true, device };
}

apiRouter.get('/devices', async (req: Request, res: Response) => {
  try {
    const { user, effectivePolicy, isSuperAdmin, allowedDeviceIds } = await resolveRequestContextPolicy(req);
    if (!user) {
      return res.status(401).json({ error: 'Unauthorized: Authentication required to access devices' });
    }
    let allDevices = await getAllDevices();

    if (!isSuperAdmin && effectivePolicy && allowedDeviceIds !== null) {
      const allowedSet = new Set(allowedDeviceIds);
      allDevices = allDevices.filter((d: any) => allowedSet.has(d.id));
    }

    const cleanDevices = allDevices.map((dev: any) => {
      const d = { ...dev };
      if (!d.platform) d.platform = 'cisco_ios_xe';
      if (!d.connection_mode) d.connection_mode = 'simulator';
      const conn = { ...(d.connection || {}) };
      delete conn.password;
      delete conn.private_key;
      d.connection = conn;
      d.ssh_password_set = Boolean(dev.ssh_password_set || dev.ssh_vault_item_id || (dev.ssh_password && String(dev.ssh_password).trim().length > 0));
      d.enable_password_set = Boolean(dev.enable_password_set || dev.enable_vault_item_id || (dev.enable_password && String(dev.enable_password).trim().length > 0));
      delete d.ssh_password;
      delete d.enable_password;
      d.snmp_community_set = Boolean(d.snmp_community || d.snmp_community_vault_item_id);
      d.snmp_v3_auth_password_set = Boolean(d.snmp_v3_auth_password || d.snmp_v3_auth_vault_item_id);
      d.snmp_v3_priv_password_set = Boolean(d.snmp_v3_priv_password || d.snmp_v3_priv_vault_item_id);
      delete d.snmp_community;
      delete d.snmp_v3_auth_password;
      delete d.snmp_v3_priv_password;
      return d;
    });

    return res.json({
      devices: cleanDevices,
      total: cleanDevices.length,
      online_count: cleanDevices.filter((d: any) => d.is_online).length,
      offline_count: cleanDevices.filter((d: any) => !d.is_online).length,
      allowedDeviceIds: isSuperAdmin ? null : allowedDeviceIds,
      targetScope: isSuperAdmin ? 'all' : (effectivePolicy?.targetScope || 'groups'),
    });
  } catch (err: any) {
    return res.status(500).json({ error: err.message || 'Failed to fetch devices' });
  }
});

// POST /devices/export - Export single or batch network equipment with strict RBAC enforcement
apiRouter.post('/devices/export', async (req: Request, res: Response) => {
  try {
    const { effectivePolicy, isSuperAdmin, allowedDeviceIds, user } = await resolveRequestContextPolicy(req);
    const { deviceIds, format = 'json', includePorts = true, includeNotes = true, includePlacement = true } = req.body;

    let allDevices = await getAllDevices();
    if (!isSuperAdmin && effectivePolicy && allowedDeviceIds !== null) {
      const allowedSet = new Set(allowedDeviceIds);
      allDevices = allDevices.filter((d: any) => allowedSet.has(d.id));
    }

    let targetDevices = allDevices;
    if (Array.isArray(deviceIds) && deviceIds.length > 0) {
      const requestedSet = new Set(deviceIds);
      targetDevices = allDevices.filter((d: any) => requestedSet.has(d.id));
    }

    if (targetDevices.length === 0) {
      return res.status(404).json({
        success: false,
        error: 'No matching devices found to export.',
        errorFa: 'هیچ تجهیزی برای استخراج یافت نشد.',
      });
    }

    // Granular Tri-State RBAC Check: deny blocks; require_approval enforces JIT approval ticket
    const context = await resolveRequestContextPolicy(req);
    const unauthorized = targetDevices.filter(
      (d: any) => !isSuperAdmin && evaluateDeviceActionDecision(effectivePolicy, d.id, 'export_devices') === 'deny'
    );

    if (unauthorized.length > 0) {
      return res.status(403).json({
        success: false,
        error: `Access denied: You do not have RBAC permission to export ${unauthorized.length} of the requested devices.`,
        errorFa: `عدم دسترسی: شما طبق پالیسی امنیتی خود مجوز استخراج (Export) تعداد ${unauthorized.length} از تجهیزات درخواستی را ندارید.`,
        unauthorizedIds: unauthorized.map((d: any) => d.id),
      });
    }

    const approvalGatedDevices = isSuperAdmin
      ? []
      : targetDevices.filter(
          (d: any) => evaluateDeviceActionDecision(effectivePolicy, d.id, 'export_devices') === 'require_approval'
        );

    let exportApprovedTicket: { actor: ApprovalActor; ticketId: string } | null = null;
    if (approvalGatedDevices.length > 0 && effectivePolicy) {
      const actor = buildApprovalActor(req, context);
      const primaryDev = approvalGatedDevices[0];
      const gateRes = await evaluateApprovalGateForRequest({
        actor,
        effectivePolicy,
        entityType: 'device',
        entityId: approvalGatedDevices.length === 1 ? primaryDev.id : 'bulk',
        entityName:
          approvalGatedDevices.length === 1
            ? primaryDev.name || primaryDev.ip || primaryDev.id
            : `${approvalGatedDevices.length} Network Devices`,
        actionKey: 'export_devices',
        requestedAction: `Export ${targetDevices.length} Network Device(s)`,
        commandPreview: buildSafeCommandPreview(req, { action: 'export_devices', extraSummary: `format=${format}, count=${targetDevices.length}` }),
        actionParams: { deviceIds: targetDevices.map((d: any) => d.id), format },
        providedApprovalId: extractProvidedApprovalId(req),
      });
      if (!gateRes.allowed) {
        res.setHeader('X-Approval-Required', 'true');
        return res.status(403).json({ success: false, ...gateRes.gatePayload });
      }
      exportApprovedTicket = { actor, ticketId: gateRes.approvedTicket.id };
      (req as any).__approvedTicketCtx = {
        actor,
        ticketId: gateRes.approvedTicket.id,
        executionNote: `Executed export_devices for ${targetDevices.length} device(s) via ${gateRes.approvedTicket.id}`,
      };
    }

    // Sanitize credentials: Zero plaintext secrets leak
    const exportData = targetDevices.map((dev: any) => {
      const d = { ...dev };
      if (d.connection) {
        const c = { ...d.connection };
        delete c.password;
        delete c.private_key;
        d.connection = c;
      }
      delete d.ssh_password;
      delete d.enable_password;
      if (!includePorts) delete d.ports;
      if (!includePlacement) {
        delete d.building;
        delete d.floor;
        delete d.unit;
        delete d.rack;
      }
      return d;
    });

    // Generate CSV if requested
    if (format === 'csv') {
      const csvHeader = [
        'ID',
        'Name',
        'Type',
        'Model',
        'IP Address',
        'MAC Address',
        'Role',
        'Status',
        'Total Ports',
        'Building',
        'Floor',
        'Unit',
        'Rack',
        'Has Unsaved Changes',
      ].join(',');

      const csvRows = exportData.map((d: any) => [
        `"${d.id || ''}"`,
        `"${(d.name || '').replace(/"/g, '""')}"`,
        `"${d.type || ''}"`,
        `"${(d.model || '').replace(/"/g, '""')}"`,
        `"${d.ip || ''}"`,
        `"${d.mac || ''}"`,
        `"${(d.role || '').replace(/"/g, '""')}"`,
        `"${d.is_online ? 'Online' : 'Offline'}"`,
        `"${d.total_ports || 24}"`,
        `"${(d.building || '').replace(/"/g, '""')}"`,
        `"${(d.floor || '').replace(/"/g, '""')}"`,
        `"${(d.unit || '').replace(/"/g, '""')}"`,
        `"${(d.rack || '').replace(/"/g, '""')}"`,
        `"${d.has_unsaved_changes ? 'Yes' : 'No'}"`,
      ].join(','));

      const csvContent = '\uFEFF' + [csvHeader, ...csvRows].join('\n');
      if (exportApprovedTicket) {
        await consumeApprovedTicketForExecution(
          exportApprovedTicket.actor,
          exportApprovedTicket.ticketId,
          `Exported CSV of ${exportData.length} device(s)`
        );
      }
      res.setHeader('Content-Type', 'text/csv; charset=utf-8');
      res.setHeader('Content-Disposition', `attachment; filename="devices_export_${Date.now()}.csv"`);
      return res.send(csvContent);
    }

    return res.json({
      success: true,
      metadata: {
        exportedAt: new Date().toISOString(),
        totalCount: exportData.length,
        exportedBy: user?.username || 'admin',
        format: 'json',
      },
      devices: exportData,
    });
  } catch (err: any) {
    return res.status(500).json({ error: err.message || 'Failed to export devices' });
  }
});

// Helper function to parse CSV string into network equipment candidate objects
function parseDevicesFromCsv(csvText: string): any[] {
  const clean = csvText.replace(/^\uFEFF/, '').trim();
  if (!clean) return [];
  const lines = clean.split(/\r?\n/).filter((l) => l.trim().length > 0);
  if (lines.length < 2) return [];

  const parseLine = (line: string): string[] => {
    const result: string[] = [];
    let cur = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        if (inQuotes && line[i + 1] === '"') {
          cur += '"';
          i++;
        } else {
          inQuotes = !inQuotes;
        }
      } else if (char === ',' && !inQuotes) {
        result.push(cur.trim());
        cur = '';
      } else {
        cur += char;
      }
    }
    result.push(cur.trim());
    return result;
  };

  const headers = parseLine(lines[0]).map((h) => h.toLowerCase().replace(/[^a-z0-9]/g, ''));
  const rows: any[] = [];

  for (let i = 1; i < lines.length; i++) {
    const values = parseLine(lines[i]);
    const obj: Record<string, any> = {};
    headers.forEach((header, idx) => {
      obj[header] = values[idx] ?? '';
    });

    const ip = (obj.ip || obj.ipaddress || obj.host || obj.sshhost || '').trim();
    const name = (obj.name || obj.devicename || obj.hostname || obj.id || `Imported Device ${i}`).trim();
    if (!ip && !obj.name && !obj.id) continue;

    const rawType = (obj.type || obj.devicetype || '').toLowerCase();
    const type = rawType.includes('rout')
      ? 'router'
      : rawType.includes('fire')
      ? 'firewall'
      : rawType.includes('ap') || rawType.includes('wire')
      ? 'access_point'
      : rawType.includes('serv')
      ? 'server'
      : 'switch';

    const rawPlatform = (obj.platform || '').toLowerCase();
    const platform = rawPlatform.includes('miko') || rawPlatform.includes('routeros')
      ? 'mikrotik_routeros'
      : rawPlatform.includes('nx')
      ? 'cisco_nxos'
      : rawPlatform.includes('juniper')
      ? 'juniper_junos'
      : rawPlatform.includes('huawei')
      ? 'huawei_vrp'
      : rawPlatform.includes('arista')
      ? 'arista_eos'
      : 'cisco_ios_xe';

    rows.push({
      id: obj.id || obj.deviceid || `dev-${Date.now()}-${i}`,
      name,
      ip: ip || '127.0.0.1',
      type,
      model: obj.model || obj.hardwaremodel || (type === 'switch' ? 'Catalyst 2960-X' : 'ISR 4331'),
      platform,
      role: obj.role || obj.devicerole || 'Access Switch',
      mac_address: obj.mac || obj.macaddress || '',
      total_ports: Number(obj.totalports || obj.ports || obj.portcount) || 24,
      building: obj.building || '',
      floor: obj.floor || '',
      unit: obj.unit || '',
      rack: obj.rack || '',
      section: obj.section || '',
      ssh_host: obj.sshhost || ip || '127.0.0.1',
      ssh_port: Number(obj.sshport || obj.port) || 22,
      ssh_username: obj.sshusername || obj.username || 'admin',
      is_online: obj.status?.toLowerCase().includes('off') ? false : true,
    });
  }

  return rows;
}

// POST /devices/import - Import single or batch network equipment with strict RBAC enforcement
apiRouter.post(['/devices/import', '/network-equipment/import'], async (req: Request, res: Response) => {
  try {
    const { effectivePolicy, isSuperAdmin, user } = await resolveRequestContextPolicy(req);

    // Strict Tri-State RBAC Enforcement: check if user is authorized to import network equipment
    if (!isSuperAdmin && effectivePolicy) {
      if (effectivePolicy.canManageDevices === false && effectivePolicy.canImportDevices === false) {
        return res.status(403).json({
          success: false,
          error: 'Access denied: Your account policy prohibits importing network equipment.',
          errorFa: 'عدم دسترسی: پالیسی حساب کاربری شما اجازه ورود و بارگذاری تجهیزات شبکه را نمی‌دهد.',
        });
      }

      const importDecision =
        effectivePolicy.canImportDevices === false
          ? 'deny'
          : evaluateDeviceActionDecision(effectivePolicy, '__global_import__', 'import_devices');

      if (importDecision === 'deny' && effectivePolicy.canImportDevices !== true) {
        return res.status(403).json({
          success: false,
          error: 'Access denied: You do not have RBAC permission to import network equipment into inventory.',
          errorFa: 'عدم دسترسی: شما طبق پالیسی امنیتی خود مجوز ورود و بارگذاری (Import) تجهیزات شبکه را ندارید.',
        });
      }

      if (importDecision === 'require_approval') {
        const actor = buildApprovalActor(req, { user, effectivePolicy, isSuperAdmin });
        const gateRes = await evaluateApprovalGateForRequest({
          actor,
          effectivePolicy,
          entityType: 'device',
          entityId: 'bulk',
          entityName: 'Network Equipment Import Package',
          actionKey: 'import_devices',
          requestedAction: 'Import Network Equipment into Inventory',
          commandPreview: buildSafeCommandPreview(req, { action: 'import_devices' }),
          providedApprovalId: extractProvidedApprovalId(req),
        });
        if (!gateRes.allowed) {
          res.setHeader('X-Approval-Required', 'true');
          return res.status(403).json({ success: false, ...gateRes.gatePayload });
        }
        (req as any).__approvedTicketCtx = {
          actor,
          ticketId: gateRes.approvedTicket.id,
          executionNote: `Executed import_devices via JIT approval ${gateRes.approvedTicket.id}`,
        };
      }
    }

    const { conflictMode = 'skip', devices: rawDevices, csvData } = req.body;

    let candidateDevices: any[] = [];

    if (typeof csvData === 'string' && csvData.trim()) {
      candidateDevices = parseDevicesFromCsv(csvData);
    } else if (Array.isArray(rawDevices)) {
      candidateDevices = rawDevices;
    } else if (Array.isArray(req.body)) {
      candidateDevices = req.body;
    } else if (req.body && typeof req.body === 'object' && (req.body.ip || req.body.name || req.body.id)) {
      candidateDevices = [req.body];
    }

    if (candidateDevices.length === 0) {
      return res.status(400).json({
        success: false,
        error: 'No valid network equipment records found in payload to import.',
        errorFa: 'هیچ رکورد تجهیز شبکه معتبری برای ورود در داده‌های ارسالی یافت نشد.',
      });
    }

    // Load existing devices to detect conflicts
    const allExisting = await getAllDevices();
    const existingById = new Map<string, any>();
    const existingByIp = new Map<string, any>();

    allExisting.forEach((d: any) => {
      if (d.id) existingById.set(String(d.id).toLowerCase(), d);
      if (d.ip) existingByIp.set(String(d.ip).toLowerCase(), d);
    });

    const createdList: any[] = [];
    const updatedList: any[] = [];
    const skippedList: any[] = [];

    for (let idx = 0; idx < candidateDevices.length; idx++) {
      const item = candidateDevices[idx];
      const id = (item.id || item.device_id || `dev-${Date.now()}-${idx + 1}`).trim();
      const ip = (item.ip || item.ip_address || item['IP Address'] || '127.0.0.1').trim();
      const name = (item.name || item.hostname || item['Name'] || item['Device Name'] || id).trim();

      const existingRecord = existingById.get(id.toLowerCase()) || (ip !== '127.0.0.1' ? existingByIp.get(ip.toLowerCase()) : null);

      if (existingRecord) {
        if (conflictMode === 'skip') {
          skippedList.push({
            id,
            name,
            ip,
            reason: 'Already exists (ID or IP match)',
            reasonFa: 'از قبل در انبار موجود است (تطابق ID یا IP)',
          });
          continue;
        } else {
          // Overwrite mode: merge and update
          const merged = {
            ...existingRecord,
            ...item,
            id: existingRecord.id, // preserve authoritative ID
            name,
            ip,
            updated_at: new Date().toISOString(),
          };
          const saved = await createDevice(merged);
          updatedList.push(saved);
          continue;
        }
      }

      // Format clean device object
      const cleanDevice = {
        id,
        name,
        ip,
        type: item.type || 'switch',
        model: item.model || 'Catalyst 2960-X',
        platform: item.platform || 'cisco_ios_xe',
        role: item.role || 'Access Switch',
        connection_mode: item.connection_mode || 'simulator',
        ssh_host: item.ssh_host || ip,
        ssh_port: Number(item.ssh_port) || 22,
        ssh_username: item.ssh_username || 'admin',
        is_online: item.is_online !== undefined ? Boolean(item.is_online) : true,
        mac_address: item.mac_address || item.mac || '',
        total_ports: Number(item.total_ports || item.ports?.length) || 24,
        ports: Array.isArray(item.ports) ? item.ports : [],
        building: item.building || '',
        floor: item.floor || '',
        unit: item.unit || '',
        rack: item.rack || '',
        section: item.section || '',
        location: item.location || '',
        created_at: new Date().toISOString(),
      };

      const saved = await createDevice(cleanDevice);
      createdList.push(saved);
      existingById.set(id.toLowerCase(), saved);
      if (ip && ip !== '127.0.0.1') existingByIp.set(ip.toLowerCase(), saved);
    }

    try {
      await addAuditLog({
        userName: user?.username || 'admin',
        action: 'Import Network Equipment',
        category: 'inventory',
        target: 'Device Inventory',
        status: 'success',
        details: `Imported ${createdList.length} devices, updated ${updatedList.length}, skipped ${skippedList.length} (conflict mode: ${conflictMode})`,
        ipAddress: req.ip || '127.0.0.1',
        userAgent: req.headers['user-agent'],
      });
    } catch (auditErr) {
      console.warn('[Audit log error on import_devices]', auditErr);
    }

    return res.json({
      success: true,
      importedCount: createdList.length,
      updatedCount: updatedList.length,
      skippedCount: skippedList.length,
      devices: [...createdList, ...updatedList],
      skipped: skippedList,
      message: `Successfully processed ${candidateDevices.length} items: ${createdList.length} imported, ${updatedList.length} updated, ${skippedList.length} skipped.`,
      message_en: `Successfully processed ${candidateDevices.length} items: ${createdList.length} imported, ${updatedList.length} updated, ${skippedList.length} skipped.`,
      message_fa: `فرآیند ورود ${candidateDevices.length} تجهیز با موفقیت پایان یافت: ${createdList.length} افزوده شد، ${updatedList.length} به‌روزرسانی شد، ${skippedList.length} نادیده گرفته شد.`,
    });
  } catch (err: any) {
    console.error('[Error in /devices/import]', err);
    return res.status(500).json({
      success: false,
      error: err.message || 'Internal server error while importing network devices.',
      errorFa: 'خطای داخلی سرور در حین ثبت و بارگذاری تجهیزات شبکه.',
    });
  }
});

// POST /devices - Register new network equipment
apiRouter.post('/devices', async (req: Request, res: Response) => {
  try {
    const { effectivePolicy, isSuperAdmin, user } = await resolveRequestContextPolicy(req);
    const canAdd = isSuperAdmin || (effectivePolicy ? (
      effectivePolicy.canAddDevice !== undefined ? Boolean(effectivePolicy.canAddDevice) :
      effectivePolicy.defaultDevicePermissions?.add_device !== undefined ? Boolean(effectivePolicy.defaultDevicePermissions.add_device) :
      (effectivePolicy.canManageDevices !== false)
    ) : true);

    if (!canAdd) {
      return res.status(403).json({
        success: false,
        error: 'Access denied: You do not have permission to register or introduce new network devices under your RBAC policy.',
        errorFa: 'عدم دسترسی: شما طبق پالیسی امنیتی خود مجوز معرفی و افزودن تجهیز جدید (Introduce New Device) را ندارید.',
      });
    }

    // RBAC Security Check: Veto initial configuration template if user lacks canApplyTemplates authority
    const initialTemplateId = req.body?.initial_template_id || req.body?.templateId || req.body?.selectedTemplateId || req.body?.template_id;
    if (initialTemplateId) {
      const canApply = isSuperAdmin || (effectivePolicy ? effectivePolicy.canApplyTemplates !== false && Boolean(effectivePolicy.canApplyTemplates) : true);
      if (!canApply) {
        try {
          await addAuditLog({
            userName: user?.username || 'anonymous',
            action: 'Register Device with Template (Rejected - RBAC Veto)',
            category: 'security',
            target: `Device: ${req.body?.name || req.body?.ip || 'New Device'}`,
            status: 'warning',
            details: `Initial template deployment vetoed: user policy prohibits applying templates (canApplyTemplates=false). Template: ${initialTemplateId}`,
            ipAddress: getClientIp(req),
            userAgent: req.headers['user-agent'] as string,
          });
        } catch (auditErr) {
          console.warn('[Audit log error on rejected initial template register]', auditErr);
        }

        return res.status(403).json({
          success: false,
          error: 'Access denied: You do not have permission to apply configuration templates (canApplyTemplates required in active RBAC policy). Initial template deployment has been vetoed.',
          errorFa: 'عدم دسترسی: شما فاقد مجوز اعمال قالب‌های پیکربندی (canApplyTemplates) در پالیسی RBAC فعال خود هستید. اعمال قالب اولیه وتو گردید.',
        });
      }
    }

    const newDevice = await createDevice(req.body);

    // If user's active policy has specific targetScope, auto-grant access to this newly introduced device
    if (effectivePolicy && effectivePolicy.targetScope === 'specific' && effectivePolicy.id && newDevice?.id) {
      try {
        const policies = await getAccessPolicies();
        let updated = false;
        const newPolicies = policies.map((pol: any) => {
          if (pol.id === effectivePolicy.id) {
            const currentTargetIds: string[] = Array.isArray(pol.targetDeviceIds) ? pol.targetDeviceIds : [];
            if (!currentTargetIds.includes(newDevice.id)) {
              updated = true;
              return {
                ...pol,
                targetDeviceIds: [...currentTargetIds, newDevice.id],
              };
            }
          }
          return pol;
        });
        if (updated) {
          await saveAccessPolicies(newPolicies);
        }
      } catch (polErr) {
        console.warn('[Auto-add created device to user policy targetDeviceIds error]', polErr);
      }
    }

    return res.status(201).json({
      success: true,
      device: newDevice,
      message: 'Device successfully registered in database',
      message_en: 'Device successfully registered in database',
      message_fa: 'تجهیز با موفقیت در دیتابیس ثبت شد',
    });
  } catch (err: any) {
    return res.status(500).json({ success: false, error: err.message });
  }
});

apiRouter.get('/devices/:id', async (req: Request, res: Response) => {
  try {
    const check = await assertDeviceScopeAccess(req, req.params.id);
    if (!check.allowed) {
      return res.status(check.status || 403).json({
        success: false,
        error: check.error,
        errorFa: check.errorFa,
      });
    }

    const d = { ...check.device };
    d.ssh_password_set = Boolean(check.device.ssh_password_set || check.device.ssh_vault_item_id || (check.device.ssh_password && String(check.device.ssh_password).trim().length > 0));
    d.enable_password_set = Boolean(check.device.enable_password_set || check.device.enable_vault_item_id || (check.device.enable_password && String(check.device.enable_password).trim().length > 0));
    delete d.ssh_password;
    delete d.enable_password;
    d.snmp_community_set = Boolean(d.snmp_community || d.snmp_community_vault_item_id);
    d.snmp_v3_auth_password_set = Boolean(d.snmp_v3_auth_password || d.snmp_v3_auth_vault_item_id);
    d.snmp_v3_priv_password_set = Boolean(d.snmp_v3_priv_password || d.snmp_v3_priv_vault_item_id);
    delete d.snmp_community;
    delete d.snmp_v3_auth_password;
    delete d.snmp_v3_priv_password;
    return res.json({ device: d });
  } catch (err: any) {
    return res.status(500).json({ error: err.message });
  }
});

