// POST /devices/bulk-delete - Delete multiple devices
apiRouter.post('/devices/bulk-delete', async (req: Request, res: Response) => {
  try {
    const deviceIds: string[] = Array.isArray(req.body?.deviceIds) ? req.body.deviceIds : [];
    if (!deviceIds.length) {
      return res.status(400).json({ success: false, error: 'deviceIds array is required' });
    }

    for (const devId of deviceIds) {
      const check = await assertDeviceScopeAccess(req, devId, 'delete_device');
      if (!check.allowed) {
        return res.status(check.status || 403).json({
          success: false,
          error: `Access denied for device ${devId}: ${check.error}`,
          errorFa: `عدم دسترسی برای تجهیز ${devId}: ${check.errorFa}`,
        });
      }
    }

    let deletedCount = 0;
    for (const id of deviceIds) {
      const ok = await deleteDevice(id);
      if (ok) deletedCount++;
    }

    return res.json({
      success: true,
      deletedCount,
      message: `Successfully deleted ${deletedCount} device(s)`,
      message_en: `Successfully deleted ${deletedCount} device(s)`,
      message_fa: `${deletedCount} تجهیز با موفقیت حذف شد`,
    });
  } catch (err: any) {
    return res.status(500).json({ success: false, error: err.message });
  }
});

// POST /devices/:id/write-memory - Save running config to NVRAM via resolved SSH backend (Port modal)
apiRouter.post('/devices/:id/write-memory', async (req: Request, res: Response) => {
  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en');
  const devId = req.params.id;
  try {
    const check = await assertDeviceScopeAccess(req, devId, 'write_memory');
    if (!check.allowed) {
      return res.status(check.status || 403).json({ success: false, error: check.error, errorFa: check.errorFa });
    }

    const allDevs = await getAllDevices();
    const device = allDevs.find((d: any) => d.id === devId || d.name === devId);
    if (!device) {
      return res.status(404).json({ success: false, error: 'Device not found', message: isEn ? 'Device not found' : 'دستگاه یافت نشد' });
    }

    // Read saved ssh_version strictly from stored device record
    const sshVersion = device.ssh_version || device.sshVersion || (device.platform?.includes('modern') ? 'modern' : 'legacy');
    const backend = resolveSshBackend(sshVersion);
    console.log(`[WriteMemory Resolver] Saving configuration for device ${devId} using ${backend.version.toUpperCase()} backend (${backend.pythonBin})`);

    let cliOutput = '';
    if (deviceSessionPool.hasActiveSession(devId)) {
      console.log(`[WriteMemory] Saving config on active persistent SSH session for ${devId}`);
      const isMikroTik = String(device.platform || '').toLowerCase().includes('mikrotik');
      const writeCmd = isMikroTik ? '/system backup save name=autobackup\n' : 'write memory\n';
      const poolResult = await deviceSessionPool.executeCommandOnSession(devId, writeCmd, 25000);
      if (!poolResult.success) {
        return res.status(400).json({
          success: false,
          error: poolResult.error || 'Failed to save configuration via persistent session',
          message: poolResult.error || 'Failed to save configuration via persistent session',
          cli_command: writeCmd.trim(),
          output: poolResult.output || '',
        });
      }
      cliOutput = poolResult.output || '';
    } else if (device.ip || device.ssh_host) {
      const result = await executeSshBridgeAction('port-action', {
        device,
        action: 'save_config',
        operation: 'save_config',
      }, backend.version, 25000);

      if (!result || result.success === false) {
        return res.status(400).json({
          success: false,
          error: result?.error || 'Failed to save configuration to NVRAM via SSH',
          message: result?.message || result?.error || 'Failed to save configuration to NVRAM via SSH',
          cli_command: result?.cli_command || 'write memory',
          output: result?.output || '',
          ssh_version: backend.version,
          paramiko_version: backend.paramikoExpected,
        });
      }
      cliOutput = result.output || '';
    }

    const updated = await updateDevice(devId, {
      has_unsaved_changes: false,
      last_write_memory_time: new Date().toISOString(),
    });

    if (req.headers['x-client-audit-logged'] !== 'true') {
      try {
        const opUser = getReqOperator(req);
        const locationStr = [device.building, device.floor, device.unit, device.rack ? `Rack ${device.rack}` : ''].filter(Boolean).join(' > ');
        await addDeviceCommandLog({
          deviceId: device.id,
          deviceName: device.name,
          deviceIp: device.ip,
          deviceVendor: (device.model || '').toLowerCase().includes('mikrotik') ? 'mikrotik' : 'cisco',
          deviceModel: device.model,
          deviceLocation: locationStr || undefined,
          channel: 'port_configuration',
          command: 'write memory',
          riskLevel: 'medium',
          status: 'success',
          outputSummary: `Saved running-config to NVRAM on ${device.name}`,
          notes: `NVRAM write memory executed`,
          actor: {
            username: opUser.username,
            role: opUser.role,
            ipAddress: opUser.ip,
          },
        });
      } catch (auditErr) {
        console.warn('[Audit] Could not save write memory command log:', auditErr);
      }
    }

    return res.json({
      success: true,
      device: updated,
      cli_output: cliOutput,
      message: isEn
        ? 'Running configuration successfully saved to startup configuration (NVRAM)'
        : 'تنظیمات جاری با موفقیت در حافظه پایدار (NVRAM) ذخیره شد',
      message_en: 'Running configuration successfully saved to startup configuration (NVRAM)',
      message_fa: 'تنظیمات جاری با موفقیت در حافظه پایدار (NVRAM) ذخیره شد',
      ssh_version: backend.version,
      paramiko_version: backend.paramikoExpected,
      isReal: true,
    });
  } catch (err: any) {
    return res.status(500).json({ success: false, error: err.message, message: err.message });
  }
});

// -------------------------------------------------------------
// GET & POST /devices/:id/cisco-resources
// Live Cisco System Resources & Telemetry (SNMP & SSH Hybrid Engine)
// -------------------------------------------------------------
const handleCiscoResourcesRequest = async (req: Request, res: Response) => {
  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en');
  const devId = req.params.id;

  try {
    const check = await assertDeviceScopeAccess(req, devId, 'read');
    if (!check.allowed) {
      return res.status(check.status || 403).json({
        success: false,
        error: check.error,
        errorFa: check.errorFa,
      });
    }

    const allDevs = await getAllDevices();
    const device = allDevs.find((d: any) => d.id === devId || d.name === devId);
    if (!device) {
      return res.status(404).json({
        success: false,
        error: 'Device not found',
        message: isEn ? 'Device not found' : 'دستگاه یافت نشد',
      });
    }

    const requestedProtocol = String(req.query.protocol || req.body?.protocol || 'auto').toLowerCase();
    const ports = Array.isArray(device.ports) ? device.ports : [];

    let snmpResult: any = null;
    let snmpAttempted = false;

    // SNMP Evaluation:
    // When protocol is 'snmp', or 'auto' (with snmp_enabled !== false and host IP present)
    if (requestedProtocol === 'snmp' || (requestedProtocol === 'auto' && device.snmp_enabled !== false)) {
      snmpAttempted = true;
      try {
        console.log(`[Cisco Resources] Polling live SNMP telemetry for device ${devId} (${device.ip || device.ssh_host})`);
        snmpResult = await fetchCiscoSnmpSystemResources(device, ports);
      } catch (snmpErr: any) {
        console.warn(`[Cisco Resources SNMP Error] ${snmpErr.message}`);
        snmpResult = {
          success: false,
          is_live: false,
          connected: false,
          telemetry_source: 'snmp',
          device_id: device.id,
          error: snmpErr.message || 'SNMP query exception',
          errorFa: `خطا در اجرای استعلام SNMP: ${snmpErr.message || 'خطای نامشخص'}`,
          warning: snmpErr.message,
        };
      }
    }

    if (snmpResult && snmpResult.success && snmpResult.is_live) {
      const snmpCpu = Number(snmpResult.cpu_utilization ?? snmpResult.cpu_percent ?? 0);
      if (snmpCpu >= 85) {
        sendTelegramAlert({
          level: 'warning',
          eventKey: `device:${device.id}:cpu`,
          title: `Cisco Device CPU High (${device.name})`,
          title_fa: `مصرف بالای پردازنده سوییچ/روتر سیسکو (${device.name})`,
          message: `Device "${device.name}" (${device.ip || 'N/A'}) reported elevated CPU load: ${snmpCpu}%.`,
          message_fa: `سوییچ/روتر سیسکو «${device.name}» (${device.ip || 'نامشخص'}) مصرف پردازنده بالایی گزارش کرد: ${snmpCpu}٪.`,
          device_name: device.name,
          target_host: device.ip || device.ssh_host,
          details: { cpu: `${snmpCpu}%`, source: 'snmp' },
        }).catch(() => {});
      }
      return res.json(snmpResult);
    }

    // If requestedProtocol was strictly 'snmp' and failed, return authentic SNMP error without fake simulation
    if (requestedProtocol === 'snmp') {
      return res.json(snmpResult || {
        success: false,
        is_live: false,
        connected: false,
        telemetry_source: 'snmp',
        device_id: device.id,
        error: 'SNMP query failed or device offline',
        errorFa: 'عدم دریافت پاسخ از طریق پروتکل SNMP (تجهیز آفلاین یا پورت UDP مسدود است)',
        warning: 'SNMP query failed',
      });
    }

    // SSH Fallback or Primary Execution
    const sshHost = (device.ip || device.ssh_host || '').trim();
    if (!sshHost) {
      return res.json(snmpResult || {
        success: false,
        is_live: false,
        connected: false,
        device_id: device.id,
        error: isEn ? 'No IP address or SSH host configured' : 'آدرس IP یا هاست SSH تجهیز تعریف نشده است',
        warning: isEn ? 'Device connection details missing' : 'مشخصات اتصال تجهیز یافت نشد',
      });
    }

    let sshResult: any = null;
    try {
      const sshVersion = device.ssh_version || device.sshVersion || (device.platform?.includes('modern') ? 'modern' : 'legacy');
      const backend = resolveSshBackend(sshVersion);
      console.log(`[Cisco Resources SSH Resolver] Querying hardware telemetry for device ${devId} via ${backend.version.toUpperCase()} backend`);
      sshResult = await executeSshBridgeAction('port-action', {
        device,
        action: 'cisco-resources',
        operation: 'cisco-resources',
      }, backend.version, 25000);
    } catch (sshErr: any) {
      console.warn(`[Cisco Resources SSH Error] ${sshErr.message}`);
      sshResult = {
        success: false,
        is_live: false,
        connected: false,
        error: sshErr.message,
      };
    }

    if (sshResult && sshResult.success && sshResult.is_live) {
      sshResult.telemetry_source = 'ssh';
      const sshCpu = Number(sshResult.cpu_percent ?? sshResult.cpu_utilization ?? 0);
      if (sshCpu >= 85) {
        sendTelegramAlert({
          level: 'warning',
          eventKey: `device:${device.id}:cpu`,
          title: `Cisco Device CPU High (${device.name})`,
          title_fa: `مصرف بالای پردازنده سوییچ/روتر سیسکو (${device.name})`,
          message: `Device "${device.name}" (${device.ip || 'N/A'}) reported elevated CPU load: ${sshCpu}%.`,
          message_fa: `دستگاه سیسکو «${device.name}» (${device.ip || 'نامشخص'}) مصرف پردازنده بالایی گزارش کرد: ${sshCpu}٪.`,
          device_name: device.name,
          target_host: device.ip || device.ssh_host,
          details: { cpu: `${sshCpu}%`, source: 'ssh' },
        }).catch(() => {});
      }
      return res.json(sshResult);
    }

    // Both methods failed: return genuine, non-fabricated error transparency
    const finalError = sshResult?.error || snmpResult?.error || 'Could not establish connection to device';
    const finalErrorFa = snmpResult?.errorFa || (isEn ? finalError : 'ارتباط با تجهیز از طریق SNMP یا SSH میسر نشد (بررسی وضعیت شبکه و دسترسی تجهیز)');

    sendTelegramAlert({
      level: 'critical',
      eventKey: `device:${device.id}:down`,
      title: `Cisco Telemetry Failed (${device.name})`,
      title_fa: `خطای پایش تلمتری سیسکو (${device.name})`,
      message: `Unable to poll hardware resources from "${device.name}" (${device.ip || 'N/A'}) via SNMP/SSH: ${finalError}`,
      message_fa: `پایش منابع سخت‌افزاری «${device.name}» (${device.ip || 'نامشخص'}) از طریق SNMP و SSH با خطا مواجه شد: ${finalErrorFa}`,
      device_name: device.name,
      target_host: device.ip || device.ssh_host,
      details: { error: finalError },
    }).catch(() => {});

    return res.json({
      success: false,
      is_live: false,
      connected: false,
      telemetry_source: snmpAttempted ? 'snmp' : 'ssh',
      device_id: device.id,
      error: finalError,
      errorFa: finalErrorFa,
      warning: finalError,
      snmp_attempted: snmpAttempted,
      ssh_attempted: true,
      timestamp: new Date().toISOString(),
    });
  } catch (err: any) {
    console.error(`[Cisco Resources Exception]`, err);
    return res.status(500).json({
      success: false,
      is_live: false,
      connected: false,
      error: err.message,
      message: err.message,
    });
  }
};

apiRouter.get('/devices/:id/cisco-resources', handleCiscoResourcesRequest);
apiRouter.post('/devices/:id/cisco-resources', handleCiscoResourcesRequest);
apiRouter.get('/devices/:id/system-resources', handleCiscoResourcesRequest);
apiRouter.post('/devices/:id/system-resources', handleCiscoResourcesRequest);

