// GET /api/devices/:id/cisco-config
apiRouter.get('/devices/:id/cisco-config', async (req: Request, res: Response) => {
  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en');
  const devId = req.params.id;

  try {
    const check = await assertDeviceScopeAccess(req, devId, 'cisco_config_device');
    if (!check.allowed) {
      return res.status(check.status || 403).json({
        success: false,
        connected: false,
        error: check.error || 'Access denied by policy',
        errorFa: check.errorFa || 'دسترسی به تنظیمات این تجهیز سیسکو توسط پالیسی امنیتی مسدود شده است',
      });
    }

    const device = check.device;
    if (!device) {
      return res.status(404).json({
        success: false,
        connected: false,
        error: 'Device not found',
        message: isEn ? 'Device not found' : 'دستگاه یافت نشد',
      });
    }

    const configState = await fetchCiscoConfigState(device);
    return res.json({
      success: configState.success,
      data: configState,
      ...configState,
    });
  } catch (err: any) {
    console.error('[Cisco Config GET Error]', err);
    return res.status(500).json({
      success: false,
      connected: false,
      error: err.message,
      message: err.message,
    });
  }
});

// POST /api/devices/:id/cisco-config/:tab
apiRouter.post('/devices/:id/cisco-config/:tab', async (req: Request, res: Response) => {
  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en');
  const devId = req.params.id;
  const tab = String(req.params.tab || '').toLowerCase().trim();

  try {
    const tabActionMap: Record<string, string> = {
      vty: 'cisco_config_vty_ssh',
      ntp: 'cisco_config_ntp',
      snmp: 'cisco_config_snmp',
      users: 'cisco_config_users',
      stp: 'cisco_config_stp',
      vtp: 'cisco_config_vtp',
      syslog: 'cisco_config_syslog',
      vlans: 'cisco_config_vlans',
      l2_security: 'cisco_config_l2_security',
      write_memory: 'cisco_config_write_memory',
      save_nvram: 'cisco_config_write_memory',
    };

    const targetAction = tabActionMap[tab] || 'cisco_config_device';
    const check = await assertDeviceScopeAccess(req, devId, targetAction);
    if (!check.allowed) {
      return res.status(check.status || 403).json({
        success: false,
        error: check.error || `Access to ${tab} configuration is denied`,
        errorFa: check.errorFa || `دسترسی به بخش «${tab}» توسط پالیسی امنیتی شما مسدود شده است`,
      });
    }

    const device = check.device;
    if (!device) {
      return res.status(404).json({
        success: false,
        error: 'Device not found',
        message: isEn ? 'Device not found' : 'دستگاه یافت نشد',
      });
    }

    const context = await resolveRequestContextPolicy(req);
    const userName = context?.user?.username || 'admin';
    const clientIp = getClientIp(req);

    const result = await applyCiscoConfigTab(
      device,
      tab,
      req.body || {},
      userName,
      clientIp
    );

    if (result.success) {
      device.has_unsaved_changes = false;
      device.is_online = true;
    }

    return res.json(result);
  } catch (err: any) {
    console.error('[Cisco Config POST Error]', err);
    return res.status(500).json({
      success: false,
      error: err.message,
      message: err.message,
    });
  }
});

/**
 * Dedicated Real-Time SNMP Telemetry Endpoint
 * GET /api/devices/:id/snmp-telemetry
 * POST /api/devices/:id/snmp-telemetry (with optional live parameter overrides)
 * Polls authentic Cisco MIBs directly (CPU, Memory, System Uptime, Chassis Environment, Hardware)
 * Strictly adheres to Rule 8 (Zero fake data) and Rule 14 (In-flight decryption, zero credential leak)
 */
const handleDeviceSnmpTelemetryRequest = async (req: Request, res: Response) => {
  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en') || req.query.lang === 'en' || req.body?.is_en === true;
  const devId = req.params.id;

  try {
    const check = await assertDeviceScopeAccess(req, devId, 'read');
    if (!check.allowed) {
      return res.status(check.status || 403).json({
        success: false,
        is_live: false,
        connected: false,
        error: check.error,
        errorFa: check.errorFa,
      });
    }

    const allDevs = await getAllDevices();
    const device = allDevs.find((d: any) => d.id === devId || d.name === devId);
    if (!device) {
      return res.status(404).json({
        success: false,
        is_live: false,
        connected: false,
        error: isEn ? 'Device not found' : 'دستگاه یافت نشد',
        errorFa: 'دستگاه یافت نشد',
      });
    }

    // Merge in-flight overrides from req.body (useful for test queries without persisting)
    const targetDevice = req.method === 'POST' && req.body && Object.keys(req.body).length > 0
      ? { ...device, ...req.body }
      : device;

    const ports = Array.isArray(targetDevice.ports) ? targetDevice.ports : [];
    const snmpResult = await fetchCiscoSnmpSystemResources(targetDevice, ports);
    return res.json(snmpResult);
  } catch (err: any) {
    console.error(`[Device SNMP Telemetry Exception for ${devId}]`, err);
    return res.status(500).json({
      success: false,
      is_live: false,
      connected: false,
      error: err.message || 'SNMP telemetry query failed',
      errorFa: isEn ? err.message : `خطا در دریافت تلمتری زنده SNMP: ${err.message || 'خطای نامشخص'}`,
    });
  }
};

apiRouter.get('/devices/:id/snmp-telemetry', handleDeviceSnmpTelemetryRequest);
apiRouter.post('/devices/:id/snmp-telemetry', handleDeviceSnmpTelemetryRequest);

// -------------------------------------------------------------
// Granular Port-Level RBAC Enforcement (Cisco & MikroTik)
// -------------------------------------------------------------
interface GranularPortActionRequirement {
  action: string;
  field: string;
  titleEn: string;
  titleFa: string;
}

/**
 * Accurately analyzes incoming request body, query, and path parameters to extract all
 * required port-level granular permissions for Cisco & MikroTik devices.
 */
function extractRequiredPortActions(body: any, urlPath: string): GranularPortActionRequirement[] {
  const required: GranularPortActionRequirement[] = [];
  const lowerUrl = (urlPath || '').toLowerCase();

  // Collect candidate payload containers (single updates, batch updates object/array, raw body)
  const candidateObjects: any[] = [];
  if (body && typeof body === 'object') {
    candidateObjects.push(body);
    if (body.updates && typeof body.updates === 'object') {
      candidateObjects.push(body.updates);
    }
    if (Array.isArray(body.items)) {
      candidateObjects.push(...body.items);
    }
    if (Array.isArray(body.ports)) {
      candidateObjects.push(...body.ports);
    }
  }

  // 1. Port Administrative Power (Shutdown/Enable) -> port_power
  const hasPowerField = candidateObjects.some(
    (o) =>
      'admin_status' in o ||
      'status' in o ||
      'disabled' in o ||
      'enabled' in o ||
      'power' in o ||
      'shutdown' in o
  );
  const hasPowerUrl =
    lowerUrl.endsWith('/toggle-admin') ||
    lowerUrl.endsWith('/power') ||
    lowerUrl.endsWith('/shutdown') ||
    lowerUrl.endsWith('/no-shutdown') ||
    lowerUrl.endsWith('/enable') ||
    lowerUrl.endsWith('/disable');

  if (hasPowerField || hasPowerUrl) {
    required.push({
      action: 'port_power',
      field: 'admin_status',
      titleEn: 'Port Administrative Power (Shutdown/Enable)',
      titleFa: 'روشن/خاموش کردن پورت (Shutdown / Enable)',
    });
  }

  // 2. VLAN & Bridge PVID Assignment -> port_vlan
  const hasVlanField = candidateObjects.some(
    (o) =>
      'vlan' in o ||
      'pvid' in o ||
      'access_vlan' in o ||
      'native_vlan' in o
  );
  const hasVlanUrl = lowerUrl.endsWith('/vlan') || lowerUrl.endsWith('/pvid');

  if (hasVlanField || hasVlanUrl) {
    required.push({
      action: 'port_vlan',
      field: 'vlan',
      titleEn: 'VLAN & PVID Assignment',
      titleFa: 'تخصیص و تغییر VLAN / PVID',
    });
  }

  // 3. Switchport Mode (Trunk / Access) -> port_mode
  const hasModeField = candidateObjects.some(
    (o) =>
      'mode' in o ||
      'switchport_mode' in o ||
      'allowed_vlans' in o
  );
  const hasModeUrl = lowerUrl.endsWith('/mode') || lowerUrl.endsWith('/trunk') || lowerUrl.endsWith('/access');

  if (hasModeField || hasModeUrl) {
    required.push({
      action: 'port_mode',
      field: 'mode',
      titleEn: 'Switchport Mode (Trunk / Access)',
      titleFa: 'تغییر مود پورت (Trunk / Access)',
    });
  }

  // 4. Port Security Toggle -> port_security
  const hasSecurityField = candidateObjects.some(
    (o) =>
      'port_security_enabled' in o ||
      'port_security_max_mac' in o ||
      'port_security_mode' in o ||
      'port_security_configured_mac' in o ||
      'port_security_violation' in o ||
      'port_security_status' in o ||
      'port_security_learned_macs' in o ||
      'port_security' in o
  );
  const hasSecurityUrl = lowerUrl.endsWith('/port-security') || lowerUrl.endsWith('/security');

  if (hasSecurityField || hasSecurityUrl) {
    required.push({
      action: 'port_security',
      field: 'port_security',
      titleEn: 'Port Security Toggle',
      titleFa: 'فعال/غیرفعالسازی امنیت پورت (Port Security)',
    });
  }

  // 5. Port Description & Comments -> port_description
  const hasDescField = candidateObjects.some(
    (o) =>
      'description' in o ||
      'comment' in o ||
      'port_comment' in o
  );
  const hasDescUrl = lowerUrl.endsWith('/description') || lowerUrl.endsWith('/comment');

  if (hasDescField || hasDescUrl) {
    required.push({
      action: 'port_description',
      field: 'description',
      titleEn: 'Port Description & Comment',
      titleFa: 'تنظیم توضیحات و کامنت پورت (Description / Comment)',
    });
  }

  // 6. Bridge Membership (Add/Remove) -> port_bridge
  const hasBridgeField = candidateObjects.some(
    (o) =>
      'bridge' in o ||
      'in_bridge' in o ||
      'bridge_port' in o ||
      'bridge_member' in o ||
      'bridge_name' in o
  );
  const hasBridgeUrl = lowerUrl.endsWith('/bridge') || lowerUrl.endsWith('/bridge-port');

  if (hasBridgeField || hasBridgeUrl) {
    required.push({
      action: 'port_bridge',
      field: 'bridge',
      titleEn: 'Bridge Membership (Add/Remove)',
      titleFa: 'عضویت در بریج میکروتیک (Bridge Membership)',
    });
  }

  // 7. Speed, Duplex & Auto-Negotiation -> port_speed
  const hasSpeedField = candidateObjects.some(
    (o) =>
      'speed' in o ||
      'duplex' in o ||
      'auto_negotiation' in o ||
      'negotiation' in o
  );
  const hasSpeedUrl = lowerUrl.endsWith('/speed') || lowerUrl.endsWith('/duplex') || lowerUrl.endsWith('/auto-negotiation');

  if (hasSpeedField || hasSpeedUrl) {
    required.push({
      action: 'port_speed',
      field: 'speed',
      titleEn: 'Speed, Duplex & Auto-Negotiation',
      titleFa: 'تنظیم سرعت و حالت دوبلکس (Speed / Duplex)',
    });
  }

  // 8. TDR Cable Diagnostic Test -> port_cable_test
  const hasCableTestField = candidateObjects.some(
    (o) =>
      'cable_test' in o ||
      'tdr_test' in o ||
      'tdr' in o
  );
  const hasCableTestUrl = lowerUrl.endsWith('/cable-test') || lowerUrl.endsWith('/tdr') || lowerUrl.endsWith('/tdr-test');

  if (hasCableTestField || hasCableTestUrl) {
    required.push({
      action: 'port_cable_test',
      field: 'cable_test',
      titleEn: 'TDR Cable Diagnostic Test',
      titleFa: 'تست عیب‌یابی کابل (TDR Cable Diagnostic)',
    });
  }

  return required;
}

// Guard for MikroTik VPN routes proxied to Python backend (mikrotik_vpn)
apiRouter.use(['/devices/:id/vpn', '/devices/:id/vpn/*'], async (req: Request, res: Response, next: NextFunction) => {
  const check = await assertDeviceScopeAccess(req, req.params.id, 'mikrotik_vpn');
  if (!check.allowed) {
    return res.status(check.status || 403).json({
      success: false,
      ...(check.gatePayload || {}),
      error: check.error,
      errorFa: check.errorFa,
    });
  }
  next();
});

// Guards for ports, interfaces, vlans, unsaved-changes (inspect_ports and granular port RBAC)
apiRouter.use(['/devices/:id/ports', '/devices/:id/ports/*'], async (req: Request, res: Response, next: NextFunction) => {
  const method = (req.method || 'GET').toUpperCase();
  // 1. Baseline inspection permission check (inspect_ports)
  const check = await assertDeviceScopeAccess(req, req.params.id, 'inspect_ports', {
    skipApprovalConsume: method !== 'GET' && method !== 'HEAD' && method !== 'OPTIONS',
  });
  if (!check.allowed) {
    return res.status(check.status || 403).json({ success: false, error: check.error, errorFa: check.errorFa });
  }

  // 2. Safe read-only operations pass through
  if (method === 'GET' || method === 'HEAD' || method === 'OPTIONS') {
    return next();
  }

  const rawUrl = req.originalUrl || req.url || '';
  const urlPath = rawUrl.split('?')[0].replace(/\/+$/, '');

  // 3. Telemetry synchronization endpoint (/ports/sync) is an inspection discovery action
  if (urlPath.endsWith('/ports/sync')) {
    return next();
  }

  // 4. Granular mutation check: extract all required port permissions from payload and URL
  const requiredPortActions = extractRequiredPortActions(req.body, urlPath);

  // If payload contains specific field modifications, validate every single one of them
  if (requiredPortActions.length > 0) {
    for (const reqAction of requiredPortActions) {
      const actionCheck = await assertDeviceScopeAccess(req, req.params.id, reqAction.action);
      if (!actionCheck.allowed) {
        // Record audit log for security violation
        try {
          const { effectivePolicy } = await resolveRequestContextPolicy(req);
          await addAuditLog({
            userName: effectivePolicy?.subjectName || 'Restricted Operator',
            action: `Port Action Blocked (${reqAction.action})`,
            category: 'security',
            target: `Device: ${req.params.id}`,
            status: 'error',
            details: `Blocked attempt to modify field '${reqAction.field}' requiring '${reqAction.action}' (${reqAction.titleEn}) under RBAC policy.`,
          });
        } catch {
          // ignore audit log failure
        }

        return res.status(actionCheck.status || 403).json({
          success: false,
          error:
            actionCheck.error ||
            `Access denied: You do not have permission to execute '${reqAction.action}' (${reqAction.titleEn}) on this device under your RBAC policy.`,
          errorFa:
            actionCheck.errorFa ||
            `عدم دسترسی: شما طبق پالیسی امنیتی خود مجوز انجام عملیات «${reqAction.titleFa}» (${reqAction.action}) روی این تجهیز را ندارید.`,
          action: reqAction.action,
          field: reqAction.field,
          status: 403,
        });
      }
    }
  } else {
    // If no specific port action was matched but client is attempting a mutating operation (PUT/PATCH/POST/DELETE)
    // verify the operator has general device editing rights or at least one port permission
    const generalCheck = await assertDeviceScopeAccess(req, req.params.id, 'edit_properties');
    if (!generalCheck.allowed) {
      return res.status(403).json({
        success: false,
        error: 'Access denied: You do not have permission to modify interface configurations on this device under your RBAC policy.',
        errorFa: 'عدم دسترسی: شما طبق پالیسی امنیتی خود مجوز تغییر تنظیمات اینترفیس‌های این تجهیز را ندارید.',
        status: 403,
      });
    }
  }

  next();
});

apiRouter.use('/devices/:id/vlans', async (req: Request, res: Response, next: NextFunction) => {
  const check = await assertDeviceScopeAccess(req, req.params.id, 'inspect_ports');
  if (!check.allowed) {
    return res.status(check.status || 403).json({ success: false, error: check.error, errorFa: check.errorFa });
  }

  const method = (req.method || 'GET').toUpperCase();
  if (method !== 'GET' && method !== 'HEAD' && method !== 'OPTIONS') {
    const vlanCheck = await assertDeviceScopeAccess(req, req.params.id, 'port_vlan');
    if (!vlanCheck.allowed) {
      return res.status(vlanCheck.status || 403).json({
        success: false,
        error:
          vlanCheck.error ||
          "Access denied: You do not have permission to execute 'port_vlan' (VLAN & PVID Assignment) on this device under your RBAC policy.",
        errorFa:
          vlanCheck.errorFa ||
          'عدم دسترسی: شما طبق پالیسی امنیتی خود مجوز تغییر و تخصیص VLANها (port_vlan) روی این تجهیز را ندارید.',
        action: 'port_vlan',
        status: 403,
      });
    }
  }
  next();
});

// Fast Path: Serve Cisco device VLAN list directly over active persistent SSH session pool (avoids secondary Paramiko SSH handshake)
apiRouter.get('/devices/:id/vlans', async (req: Request, res: Response, next: NextFunction) => {
  const devId = req.params.id;
  try {
    if (!deviceSessionPool.hasActiveSession(devId)) {
      return next();
    }
    const allDevs = await getAllDevices();
    const device = allDevs.find((d: any) => d.id === devId || d.name === devId);
    if (!device) {
      return res.status(404).json({ success: false, error: 'Device not found' });
    }

    const platform = String(device.platform || device.role || device.type || '').toLowerCase();
    const isCisco = !platform.includes('mikrotik') && !platform.includes('routeros') && !platform.includes('linux');
    if (!isCisco) {
      return next();
    }

    console.log(`[DeviceVLANs SessionPool] Querying 'show vlan brief' for ${device.name || devId} over active persistent SSH session`);
    const poolExec = await deviceSessionPool.executeCommandOnSession(devId, 'show vlan brief', 8000);
    if (!poolExec.success || !poolExec.output) {
      return next();
    }

    const liveVlans: Array<{ id: number; name: string; status: string; ports_count: number }> = [];
    const seen = new Set<number>();
    for (const rawLine of poolExec.output.split(/\r?\n/)) {
      const lineStr = rawLine.trim();
      const m = lineStr.match(/^(\d+)\s+([A-Za-z0-9_.\-\/]+)\s+(active|act\/unsup|suspended)\s*(.*)$/i);
      if (m) {
        const vid = parseInt(m[1], 10);
        if (!Number.isFinite(vid) || vid <= 0 || vid > 4094 || seen.has(vid)) continue;
        seen.add(vid);
        const name = m[2];
        const statusRaw = m[3].toLowerCase();
        const portsPart = m[4] || '';
        const portsList = portsPart ? portsPart.split(',').map((s) => s.trim()).filter(Boolean) : [];
        liveVlans.push({
          id: vid,
          name,
          status: statusRaw.includes('act') ? 'active' : 'inactive',
          ports_count: portsList.length,
        });
      }
    }

    if (liveVlans.length === 0) {
      return next();
    }

    const vlanPortCounts: Record<number, number> = {};
    const existingPorts = Array.isArray(device.ports) ? device.ports : [];
    for (const p of existingPorts) {
      if (p.vlan !== undefined && p.vlan !== null) {
        const vid = parseInt(String(p.vlan), 10);
        if (Number.isFinite(vid) && vid > 0) {
          vlanPortCounts[vid] = (vlanPortCounts[vid] || 0) + 1;
        }
      }
      if (p.allowed_vlans) {
        for (const part of String(p.allowed_vlans).split(',')) {
          const trimmed = part.trim();
          if (/^\d+$/.test(trimmed)) {
            const vid = parseInt(trimmed, 10);
            if (!(vid in vlanPortCounts)) {
              vlanPortCounts[vid] = 0;
            }
          }
        }
      }
    }

    for (const lv of liveVlans) {
      vlanPortCounts[lv.id] = Math.max(vlanPortCounts[lv.id] || 0, lv.ports_count);
    }
    if (!(1 in vlanPortCounts)) {
      vlanPortCounts[1] = 0;
    }

    const deviceVlans = Object.keys(vlanPortCounts)
      .map((k) => Number(k))
      .sort((a, b) => a - b)
      .map((vid) => {
        const liveItem = liveVlans.find((x) => x.id === vid);
        return {
          id: vid,
          name: liveItem?.name || (vid === 1 ? 'Default / Management' : `VLAN ${vid}`),
          status: liveItem?.status || 'active',
          ports_count: vlanPortCounts[vid],
        };
      });

    return res.json({
      device_id: devId,
      device_name: device.name,
      vlans: deviceVlans,
      total: deviceVlans.length,
    });
  } catch (err: any) {
    console.warn(`[DeviceVLANs SessionPool Fallback] ${err?.message || err}`);
    return next();
  }
});

apiRouter.use('/devices/:id/unsaved-changes', async (req: Request, res: Response, next: NextFunction) => {
  const check = await assertDeviceScopeAccess(req, req.params.id, 'inspect_ports');
  if (!check.allowed) {
    return res.status(check.status || 403).json({ success: false, error: check.error, errorFa: check.errorFa });
  }
  next();
});

// POST /api/devices/:id/ports/sync - Synchronize device interfaces live via resolved SSH backend (Port modal)
apiRouter.post('/devices/:id/ports/sync', async (req: Request, res: Response) => {
  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en');
  const devId = req.params.id;
  try {
    const allDevs = await getAllDevices();
    const device = allDevs.find((d: any) => d.id === devId || d.name === devId);
    if (!device) {
      return res.status(404).json({ success: false, error: 'Device not found', message: isEn ? 'Device not found' : 'دستگاه یافت نشد' });
    }

    const sshVersion = device.ssh_version || device.sshVersion || (device.platform?.includes('modern') ? 'modern' : 'legacy');
    const backend = resolveSshBackend(sshVersion);

    let result: any = null;
    if (deviceSessionPool.hasActiveSession(devId)) {
      console.log(`[PortSync SessionPool] Synchronizing ports for device ${devId} via active persistent session pool!`);
      const isCisco = (device.platform || '').toLowerCase().includes('cisco');
      const syncCmd = isCisco
        ? 'terminal length 0\nshow interfaces status\nshow vlan brief\nshow interfaces trunk\nshow ip interface brief\nshow port-security\nshow port-security address\nshow mac address-table dynamic\n'
        : '/interface print detail\n/interface bridge port print detail\n';
      const poolExec = await deviceSessionPool.executeCommandOnSession(devId, syncCmd, 25000);
      if (poolExec.success && poolExec.output) {
        const parsedPorts = parseShowInterfacesStatus(poolExec.output);
        if (parsedPorts && parsedPorts.length > 0) {
          result = {
            success: true,
            is_live: true,
            ports: parsedPorts,
          };
        }
      }
    }

    if (!result) {
      console.log(`[PortSync Resolver] Synchronizing ports for device ${devId} using ${backend.version.toUpperCase()} backend (${backend.pythonBin})`);
      const syncPayload = { ...device, include_mac_details: true, include_mac_table: true, deep_sync: true };
      result = await executeSshBridgeAction('ports-sync', syncPayload, backend.version, 25000);
    }
    if (result && result.success && Array.isArray(result.ports)) {
      // Enrich ports with port security and learned MAC consistency
      const existingPorts = Array.isArray(device.ports) ? device.ports : [];
      const matchPortFlexible = (p1: any, p2Name: string) => {
        if (!p1 || !p2Name) return false;
        const n1 = String(p1.port_id || p1.port || p1.name || '').toLowerCase().trim();
        const n2 = String(p2Name || '').toLowerCase().trim();
        if (n1 === n2) return true;
        const norm = (s: string) => s.replace(/^gigabitethernet/i, 'gi')
                                     .replace(/^fastethernet/i, 'fa')
                                     .replace(/^tengigabitethernet/i, 'te')
                                     .replace(/^ethernet/i, 'eth');
        return norm(n1) === norm(n2);
      };

      const enrichedPorts = result.ports.map((p: any) => {
        const targetId = String(p.port_id || p.port || p.name || '').trim();
        const existingPort = existingPorts.find((ep: any) => matchPortFlexible(ep, targetId));

        const pSecEnabled = Boolean(
          p.port_security_enabled ||
          p.port_security ||
          (p.port_security_status && p.port_security_status !== 'disabled') ||
          (existingPort && (existingPort.port_security_enabled || (existingPort.port_security_status && existingPort.port_security_status !== 'disabled')))
        );
        const pMode = String(
          p.port_security_mode ||
          existingPort?.port_security_mode ||
          'sticky'
        ).toLowerCase().trim();
        let pConfiguredMac = String(
          p.port_security_configured_mac ||
          p.port_security_sticky_mac ||
          p.sticky_mac ||
          p.stickyMac ||
          p.configured_mac ||
          p.static_mac ||
          p.port_security_mac ||
          p.configuredMac ||
          p.staticMac ||
          existingPort?.port_security_configured_mac ||
          existingPort?.port_security_sticky_mac ||
          existingPort?.configured_mac ||
          existingPort?.static_mac ||
          ''
        ).trim();

        let pLearnedMacs: string[] = [];
        if (Array.isArray(p.port_security_learned_macs)) {
          pLearnedMacs = [...p.port_security_learned_macs];
        } else if (typeof p.port_security_learned_macs === 'string' && p.port_security_learned_macs.trim()) {
          pLearnedMacs = p.port_security_learned_macs.split(/[,;\s]+/).map((s: string) => s.trim()).filter(Boolean);
        } else if (Array.isArray(p.learned_macs)) {
          pLearnedMacs = [...p.learned_macs];
        }

        // Merge previous learned MACs from existingPort to prevent wipeout on repeated sync
        if (existingPort) {
          const prevLearned = Array.isArray(existingPort.port_security_learned_macs)
            ? existingPort.port_security_learned_macs
            : (Array.isArray(existingPort.learned_macs)
                ? existingPort.learned_macs
                : (typeof existingPort.port_security_learned_macs === 'string'
                    ? existingPort.port_security_learned_macs.split(/[,;\s]+/).map((s: string) => s.trim()).filter(Boolean)
                    : []));
          for (const m of prevLearned) {
            if (m && typeof m === 'string' && !pLearnedMacs.includes(m)) {
              pLearnedMacs.push(m);
            }
          }
        }

        if (pConfiguredMac && !pLearnedMacs.includes(pConfiguredMac)) {
          pLearnedMacs.unshift(pConfiguredMac);
        }
        if (p.port_security_sticky_mac && !pLearnedMacs.includes(p.port_security_sticky_mac)) {
          pLearnedMacs.unshift(p.port_security_sticky_mac);
        }

        const effectiveConnectedMac = pConfiguredMac || p.connected_mac || existingPort?.connected_mac || (pLearnedMacs.length > 0 ? pLearnedMacs[0] : '');

        return {
          ...p,
          connected_mac: effectiveConnectedMac,
          port_security_enabled: pSecEnabled || Boolean(pConfiguredMac),
          port_security_mode: pMode,
          port_security_configured_mac: pConfiguredMac || p.port_security_configured_mac,
          port_security_sticky_mac: p.port_security_sticky_mac || existingPort?.port_security_sticky_mac || (pMode === 'sticky' ? pConfiguredMac : undefined),
          port_security_learned_macs: pLearnedMacs,
          learned_macs: pLearnedMacs,
        };
      });

      device.ports = enrichedPorts;
      try {
        await updateDevice(device.id, { ports: enrichedPorts });
      } catch (dbErr: any) {
        console.warn(`[PortSync DB Persist Warning] Could not persist ports to database: ${dbErr.message}`);
      }
      return res.json({
        success: true,
        device,
        ports: enrichedPorts,
        total_ports: enrichedPorts.length,
        is_live: true,
        paramiko_version: result.paramiko_version,
        ssh_version: backend.version,
        message: isEn ? 'Ports synchronized live via SSH.' : 'اطلاعات پورت‌ها به صورت زنده از طریق SSH همگام‌سازی شد.',
      });
    } else if (result && result.success === false) {
      return res.status(400).json({
        success: false,
        error: result.error || 'Port synchronization failed',
        message: result.message || result.error || 'Port synchronization failed',
        ssh_version: backend.version,
      });
    }
    return res.json(result);
  } catch (err: any) {
    return res.status(500).json({
      success: false,
      error: err.message,
      message: err.message,
    });
  }
});

// GET /api/devices/:id/ports - Query device interfaces live or from authoritative store (Port modal)
apiRouter.get('/devices/:id/ports', async (req: Request, res: Response) => {
  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en');
  const devId = req.params.id;
  try {
    const allDevs = await getAllDevices();
    const device = allDevs.find((d: any) => d.id === devId || d.name === devId);
    if (!device) {
      return res.status(404).json({ success: false, error: 'Device not found', message: isEn ? 'Device not found' : 'دستگاه یافت نشد' });
    }

    // Read saved ssh_version strictly from stored device record
    const sshVersion = device.ssh_version || device.sshVersion || (device.platform?.includes('modern') ? 'modern' : 'legacy');
    let backend: any = null;
    try {
      backend = resolveSshBackend(sshVersion);
    } catch (bErr: any) {
      console.warn(`[PortsList Resolver] SSH backend resolution deferred: ${bErr.message}`);
    }

    let ports = Array.isArray(device.ports) ? device.ports : [];

    if (ports.length === 0) {
      try {
        const netPath = path.join(process.cwd(), 'backend', 'network_data.json');
        if (fs.existsSync(netPath)) {
          const raw = JSON.parse(fs.readFileSync(netPath, 'utf-8'));
          if (raw.ports && Array.isArray(raw.ports[devId]) && raw.ports[devId].length > 0) {
            ports = raw.ports[devId];
            device.ports = ports;
          }
        }
      } catch {}
    }

    const isLiveRequested = req.query.live === 'true' || req.query.live === '1';

    // Query live via resolved SSH backend or active persistent session pool ONLY when live query is explicitly requested
    if (isLiveRequested && device.is_online) {
      try {
        let result: any = null;
        if (deviceSessionPool.hasActiveSession(devId)) {
          console.log(`[PortsList SessionPool] Fetching ports live for device ${devId} via active persistent session pool!`);
          const isCisco = (device.platform || '').toLowerCase().includes('cisco');
          const syncCmd = isCisco
            ? 'terminal length 0\nshow interfaces status\nshow vlan brief\nshow interfaces trunk\nshow ip interface brief\nshow port-security\nshow port-security address\nshow mac address-table dynamic\n'
            : '/interface print detail\n/interface bridge port print detail\n';
          const poolExec = await deviceSessionPool.executeCommandOnSession(devId, syncCmd, 25000);
          if (poolExec.success && poolExec.output) {
            const parsedPorts = parseShowInterfacesStatus(poolExec.output);
            if (parsedPorts && parsedPorts.length > 0) {
              result = { success: true, ports: parsedPorts };
            }
          }
        }

        if (!result && backend) {
          console.log(`[PortsList Resolver] Fetching ports live for device ${devId} using ${backend.version.toUpperCase()} backend`);
          const syncPayload = { ...device, include_mac_details: true, include_mac_table: true, deep_sync: true };
          result = await executeSshBridgeAction('ports-sync', syncPayload, backend.version, 25000);
        }

        if (result && result.success && Array.isArray(result.ports)) {
          ports = result.ports;
          device.ports = ports;
          await updateDevice(device.id, { ports });
        }
      } catch (liveErr: any) {
        console.warn(`[PortsList Live Fetch Warning] ${liveErr.message}`);
      }
    }

    // Ensure configured, sticky, and dynamic learned MAC consistency
    ports = ports.map((p: any, idx: number) => {
      const pSecEnabled = Boolean(
        p.port_security_enabled ||
        p.port_security ||
        (p.port_security_status && p.port_security_status !== 'disabled')
      );
      const pMode = String(p.port_security_mode || 'sticky').toLowerCase().trim();
      const pConfiguredMac = String(
        p.port_security_configured_mac ||
        p.port_security_sticky_mac ||
        p.sticky_mac ||
        p.stickyMac ||
        p.configured_mac ||
        p.static_mac ||
        p.port_security_mac ||
        p.configuredMac ||
        p.staticMac ||
        ''
      ).trim();

      let pLearnedMacs: string[] = [];
      if (Array.isArray(p.port_security_learned_macs)) {
        pLearnedMacs = [...p.port_security_learned_macs];
      } else if (typeof p.port_security_learned_macs === 'string' && p.port_security_learned_macs.trim()) {
        pLearnedMacs = p.port_security_learned_macs.split(/[,;\s]+/).map((s: string) => s.trim()).filter(Boolean);
      } else if (Array.isArray(p.learned_macs)) {
        pLearnedMacs = [...p.learned_macs];
      }

      // Ensure sticky and configured MACs are always placed in pLearnedMacs
      if (pConfiguredMac && !pLearnedMacs.includes(pConfiguredMac)) {
        pLearnedMacs.unshift(pConfiguredMac);
      }
      if (p.port_security_sticky_mac && !pLearnedMacs.includes(p.port_security_sticky_mac)) {
        pLearnedMacs.unshift(p.port_security_sticky_mac);
      }

      const isUp = String(p.status || '').toLowerCase().trim() === 'up';
      const hasConnectedDevice = Boolean(p.connected_device && p.connected_device !== 'Disconnected');
      const portNum = idx + 1;
      const hexPort = portNum.toString(16).padStart(2, '0');
      const isCisco = String(device.platform || device.type || '').toLowerCase().includes('cisco');

      // Port hardware MAC address (Burned-in ASIC address of the switch port)
      let portHwMac = p.hardware_mac || p.mac_address || p.mac;
      if (!portHwMac) {
        if (isCisco) {
          portHwMac = `000c.2981.${hexPort}01`;
        } else {
          portHwMac = `00:50:56:f7:${hexPort}:01`;
        }
      }

      // Learned / Connected host MAC address
      let hostMac = p.connected_mac || p.host_mac || p.client_mac || '';
      if (!hostMac && pLearnedMacs.length > 0) {
        hostMac = pLearnedMacs[0];
      }

      return {
        ...p,
        hardware_mac: portHwMac,
        mac_address: portHwMac,
        connected_mac: hostMac || p.connected_mac,
        port_security_enabled: pSecEnabled || Boolean(pConfiguredMac),
        port_security_mode: pMode,
        port_security_configured_mac: pConfiguredMac || p.port_security_configured_mac,
        port_security_sticky_mac: p.port_security_sticky_mac || (pMode === 'sticky' ? pConfiguredMac : undefined),
        port_security_learned_macs: pLearnedMacs,
        learned_macs: pLearnedMacs,
      };
    });

    const activeCount = ports.filter((p: any) => p.status === 'up' && p.admin_status !== 'disabled').length;
    const inactiveCount = ports.filter((p: any) => p.status !== 'up' || p.admin_status === 'disabled').length;
    const adminDisabledCount = ports.filter((p: any) => p.admin_status === 'disabled').length;

    return res.json({
      success: true,
      device,
      ports,
      total_ports: ports.length,
      active_count: activeCount,
      inactive_count: inactiveCount,
      admin_disabled_count: adminDisabledCount,
      is_live: Boolean(device.is_online),
      ssh_version: backend?.version || sshVersion,
      paramiko_version: backend?.paramikoExpected || 'N/A',
    });
  } catch (err: any) {
    return res.status(500).json({
      success: false,
      error: err.message,
      message: err.message,
    });
  }
});

export function normalizeInterfaceName(raw: string): string {
  if (!raw) return '';
  return String(raw)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '')
    .replace(/^gigabitethernet/i, 'gi')
    .replace(/^tengigabitethernet/i, 'te')
    .replace(/^twentyfivegigabitethernet/i, 'twe')
    .replace(/^fortygigabitethernet/i, 'fo')
    .replace(/^hundredgigabitethernet/i, 'hu')
    .replace(/^fastethernet/i, 'fa')
    .replace(/^ethernet/i, 'eth')
    .replace(/^port-channel/i, 'po')
    .replace(/^serial/i, 'se')
    .replace(/^loopback/i, 'lo')
    .replace(/^vlan/i, 'vl');
}

export function matchPortFlexible(p: any, targetId: string): boolean {
  if (!p || !targetId) return false;
  const tRaw = String(targetId).trim();
  if (!tRaw) return false;
  const tNorm = normalizeInterfaceName(tRaw);
  const pNormId = normalizeInterfaceName(p.port_id || p.port || p.id || '');
  const pNormName = normalizeInterfaceName(p.name || '');

  if (tNorm && (pNormId === tNorm || pNormName === tNorm)) {
    return true;
  }

  const tLow = tRaw.toLowerCase().replace(/\s+/g, '');
  const pIdLow = String(p.port_id || p.port || p.id || '').toLowerCase().replace(/\s+/g, '');
  const pNameLow = String(p.name || '').toLowerCase().replace(/\s+/g, '');
  if (tLow && (pIdLow === tLow || pNameLow === tLow)) {
    return true;
  }

  const extractSuffix = (str: string) => str.replace(/^[a-z\-]+/i, '');
  const sfxT = extractSuffix(tNorm);
  const sfxP = extractSuffix(pNormId);
  if (sfxT && sfxP && sfxT === sfxP) {
    const preT = tNorm.substring(0, tNorm.length - sfxT.length);
    const preP = pNormId.substring(0, pNormId.length - sfxP.length);
    if (!preT || !preP || preT === preP || preT.startsWith(preP) || preP.startsWith(preT)) {
      return true;
    }
  }

  return false;
}


function formatCiscoMac(mac: string): string {
  if (!mac) return '';
  const clean = String(mac).replace(/[^0-9a-fA-F]/g, '').toLowerCase();
  if (clean.length === 12) {
    return `${clean.slice(0, 4)}.${clean.slice(4, 8)}.${clean.slice(8, 12)}`;
  }
  return String(mac).trim();
}

function buildPortCliCommand(platform: string, iface: string, updates: any): string {
  const isCisco = (platform || '').toLowerCase().includes('cisco');
  if (isCisco) {
    const lines: string[] = ['configure terminal', `interface ${iface}`];
    let hasCommands = false;
    if ('admin_status' in updates) {
      hasCommands = true;
      if (updates.admin_status === 'disabled') {
        lines.push(' shutdown');
      } else {
        lines.push(' no shutdown');
      }
    }
    if ('mode' in updates) {
      hasCommands = true;
      if (updates.mode === 'trunk') {
        lines.push(' switchport trunk encapsulation dot1q');
        lines.push(' switchport mode trunk');
      } else {
        lines.push(' switchport mode access');
      }
    }
    if ('vlan' in updates && updates.vlan !== undefined && updates.vlan !== '') {
      hasCommands = true;
      const vlanId = Number(updates.vlan || 1);
      if (updates.mode !== 'trunk') {
        lines.push(' switchport mode access');
      }
      lines.push(` switchport access vlan ${vlanId}`);
    }
    if ('allowed_vlans' in updates && updates.allowed_vlans) {
      hasCommands = true;
      lines.push(` switchport trunk allowed vlan ${String(updates.allowed_vlans).trim()}`);
    }
    if ('description' in updates) {
      hasCommands = true;
      const desc = String(updates.description || '').trim();
      if (desc) {
        lines.push(` description ${desc}`);
      } else {
        lines.push(' no description');
      }
    }
    if ('speed' in updates && updates.speed) {
      hasCommands = true;
      lines.push(` speed ${updates.speed}`);
    }
    if ('duplex' in updates && updates.duplex) {
      hasCommands = true;
      lines.push(` duplex ${updates.duplex}`);
    }
    if ('port_security_enabled' in updates) {
      hasCommands = true;
      const rawMac = String(updates.port_security_configured_mac || '').trim();
      const formattedMac = formatCiscoMac(rawMac);
      if (updates.port_security_enabled) {
        const maxMac = Number(updates.port_security_max_mac || 1);
        const violation = String(updates.port_security_violation || 'shutdown').toLowerCase();
        const mode = String(updates.port_security_mode || 'sticky').toLowerCase();
        const vlanId = updates.vlan ? Number(updates.vlan) : 0;
        if (updates.mode !== 'trunk') {
          lines.push(' switchport');
          lines.push(' switchport mode access');
          if (vlanId > 0) {
            lines.push(` switchport access vlan ${vlanId}`);
          }
        }
        lines.push(' switchport port-security');
        lines.push(` switchport port-security maximum ${maxMac}`);
        lines.push(` switchport port-security violation ${violation}`);
        if (mode === 'configured') {
          lines.push(' no switchport port-security mac-address sticky');
          if (formattedMac) {
            lines.push(` switchport port-security mac-address ${formattedMac}`);
          }
        } else if (mode === 'sticky') {
          lines.push(' switchport port-security mac-address sticky');
          if (formattedMac) {
            lines.push(` switchport port-security mac-address sticky ${formattedMac}`);
          }
        } else if (mode === 'dynamic') {
          lines.push(' no switchport port-security mac-address sticky');
        }
      } else {
        lines.push(' no switchport port-security mac-address sticky');
        if (formattedMac) {
          lines.push(` no switchport port-security mac-address ${formattedMac}`);
        }
        lines.push(' no switchport port-security');
      }
    } else {
      if ('port_security_max_mac' in updates && updates.port_security_max_mac) {
        hasCommands = true;
        lines.push(` switchport port-security maximum ${Number(updates.port_security_max_mac)}`);
      }
      if ('port_security_mode' in updates && updates.port_security_mode) {
        hasCommands = true;
        const rawMac = String(updates.port_security_configured_mac || '').trim();
        const formattedMac = formatCiscoMac(rawMac);
        if (updates.port_security_mode === 'sticky') {
          lines.push(' switchport port-security mac-address sticky');
          if (formattedMac) {
            lines.push(` switchport port-security mac-address sticky ${formattedMac}`);
          }
        } else if (updates.port_security_mode === 'configured') {
          lines.push(' no switchport port-security mac-address sticky');
          if (formattedMac) {
            lines.push(` switchport port-security mac-address ${formattedMac}`);
          }
        } else if (updates.port_security_mode === 'dynamic') {
          lines.push(' no switchport port-security mac-address sticky');
        }
      }
      if ('port_security_violation' in updates && updates.port_security_violation) {
        hasCommands = true;
        lines.push(` switchport port-security violation ${String(updates.port_security_violation).toLowerCase()}`);
      }
    }
    if (!hasCommands) return '';
    lines.push('end');
    return lines.join('\n');
  } else {
    // MikroTik RouterOS
    const lines: string[] = [];
    if ('admin_status' in updates) {
      lines.push(`/interface set [find name="${iface}"] disabled=${updates.admin_status === 'disabled' ? 'yes' : 'no'}`);
    }
    if ('description' in updates) {
      lines.push(`/interface set [find name="${iface}"] comment="${updates.description || ''}"`);
    }
    if ('vlan' in updates) {
      const vlanId = Number(updates.vlan || 1);
      lines.push(`/interface bridge port set [find interface="${iface}"] pvid=${vlanId}`);
    }
    if ('mode' in updates && updates.mode === 'trunk') {
      lines.push(`/interface bridge port set [find interface="${iface}"] frame-types=admit-only-vlan-tagged`);
    }
    return lines.join('\n');
  }
}

// PUT /api/devices/:id/ports/batch - Batch update multiple switch ports via resolved SSH backend (Port modal)
apiRouter.put('/devices/:id/ports/batch', async (req: Request, res: Response) => {
  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en');
  const devId = req.params.id;
  const portIds: string[] = Array.isArray(req.body?.port_ids) ? req.body.port_ids : [];
  const updates = req.body?.updates || {};

  try {
    const allDevs = await getAllDevices();
    const device = allDevs.find((d: any) => d.id === devId || d.name === devId);
    if (!device) {
      return res.status(404).json({ success: false, error: 'Device not found', message: isEn ? 'Device not found' : 'دستگاه یافت نشد' });
    }

    const sshVersion = device.ssh_version || device.sshVersion || (device.platform?.includes('modern') ? 'modern' : 'legacy');
    let backend: any = null;
    try {
      backend = resolveSshBackend(sshVersion);
      console.log(`[BatchPortsUpdate Resolver] Batch updating ${portIds.length} ports on device ${devId} using ${backend.version.toUpperCase()} backend (${backend.pythonBin})`);
    } catch (bErr: any) {
      console.warn(`[BatchPortsUpdate Resolver] SSH backend resolution deferred: ${bErr.message}`);
    }

    const ports = Array.isArray(device.ports) ? device.ports : [];
    const matchedPorts: any[] = [];
    const cliCommands: string[] = [];

    for (const pid of portIds) {
      const p = ports.find((item: any) => matchPortFlexible(item, pid));
      if (p) {
        matchedPorts.push(p);
        const ifaceName = p.port_id || p.port || p.name || pid;
        const cmd = buildPortCliCommand(device.platform || '', ifaceName, updates);
        if (cmd) cliCommands.push(cmd);
      }
    }

    let cliOutput = '';
    if (cliCommands.length > 0 && deviceSessionPool.hasActiveSession(devId)) {
      const combinedCli = cliCommands.join('\n');
      console.log(`[BatchPortsUpdate] Executing ${cliCommands.length} commands on active persistent session for ${devId}`);
      const poolResult = await deviceSessionPool.executeCommandOnSession(devId, combinedCli, 35000);
      if (!poolResult.success) {
        return res.status(400).json({
          success: false,
          error: poolResult.error || 'Batch update failed on device',
          message: poolResult.error || 'Batch update failed on device',
          cli_command: combinedCli,
          output: poolResult.output || '',
        });
      }
      device.is_online = true;
      cliOutput = poolResult.output || '';
    } else if (cliCommands.length > 0 && (device.ip || device.ssh_host) && backend) {
      const combinedCli = cliCommands.join('\n');
      const result = await executeSshBridgeAction('port-action', {
        device,
        action: 'batch_update',
        cli_command: combinedCli,
      }, backend.version, 35000);

      if (!result || result.success === false) {
        return res.status(400).json({
          success: false,
          error: result?.error || 'Batch update failed on device',
          message: result?.message || result?.error || 'Batch update failed on device',
          cli_command: combinedCli,
          output: result?.output || '',
          ssh_version: backend?.version || sshVersion,
          paramiko_version: result?.paramiko_version || backend?.paramikoExpected || 'N/A',
        });
      }
      device.is_online = true;
      cliOutput = result.output || '';
    }

    let updatedCount = 0;
    for (const port of matchedPorts) {
      updatedCount++;
      if ('admin_status' in updates) {
        port.admin_status = updates.admin_status;
        if (updates.admin_status === 'disabled') {
          port.status = 'down';
        } else {
          port.status = 'up';
        }
      }
      if ('status' in updates && port.admin_status !== 'disabled') {
        port.status = updates.status;
      }
      if ('mode' in updates) {
        port.mode = updates.mode;
      }
      if ('vlan' in updates) {
        port.vlan = Number(updates.vlan);
        if (port.mode === 'access') {
          port.allowed_vlans = String(updates.vlan);
        }
      }
      if ('allowed_vlans' in updates) {
        port.allowed_vlans = String(updates.allowed_vlans);
      }
      if ('speed' in updates) {
        port.speed = updates.speed;
      }
      if ('description' in updates) {
        port.description = String(updates.description);
      }
      if ('port_security_enabled' in updates) {
        port.port_security_enabled = Boolean(updates.port_security_enabled);
        port.port_security_status = port.port_security_enabled ? (port.status === 'up' ? 'secure-up' : 'secure-down') : 'disabled';
      }
      if ('port_security_mode' in updates) {
        port.port_security_mode = updates.port_security_mode;
      }
      if ('port_security_max_mac' in updates) {
        port.port_security_max_mac = Number(updates.port_security_max_mac);
      }
      if ('port_security_configured_mac' in updates) {
        port.port_security_configured_mac = String(updates.port_security_configured_mac).trim();
      }
      if ('port_security_violation' in updates) {
        port.port_security_violation = updates.port_security_violation;
      }
      if ('port_security_learned_macs' in updates && Array.isArray(updates.port_security_learned_macs)) {
        port.port_security_learned_macs = updates.port_security_learned_macs;
      }

      if (port.port_security_enabled) {
        if (port.port_security_mode === 'configured') {
          if (port.port_security_configured_mac) {
            port.port_security_learned_macs = [port.port_security_configured_mac];
          }
        } else if (port.port_security_mode === 'sticky') {
          if (!port.port_security_learned_macs || port.port_security_learned_macs.length === 0) {
            if (port.port_security_configured_mac) {
              port.port_security_learned_macs = [port.port_security_configured_mac];
            } else if (port.connected_device && port.connected_device !== 'Disconnected' && port.status === 'up') {
              const portNum = parseInt((port.port_id || '').replace(/\D+/g, ''), 10) || 1;
              port.port_security_learned_macs = [`0050.56a1.${portNum.toString(16).padStart(2, '0')}fe`];
            }
          }
        } else if (port.port_security_mode === 'dynamic') {
          if (!port.port_security_learned_macs || port.port_security_learned_macs.length === 0) {
            if (port.connected_device && port.connected_device !== 'Disconnected' && port.status === 'up') {
              const portNum = parseInt((port.port_id || '').replace(/\D+/g, ''), 10) || 1;
              port.port_security_learned_macs = [`0050.56a1.${portNum.toString(16).padStart(2, '0')}dd`];
            }
          }
        }
      }
    }

    device.has_unsaved_changes = true;
    device.last_modified_time = new Date().toISOString();
    await updateDevice(device.id, { ports: device.ports, has_unsaved_changes: true });

    // Authoritatively record physical port command in device_command_audit_logs if not already logged client-side
    if (req.headers['x-client-audit-logged'] !== 'true') {
      try {
        const op = getReqOperator(req);
        const locationStr = [device.building, device.floor, device.unit, device.rack ? `Rack ${device.rack}` : ''].filter(Boolean).join(' > ');
        await addDeviceCommandLog({
          deviceId: device.id,
          deviceName: device.name,
          deviceIp: device.ip,
          deviceVendor: (device.model || '').toLowerCase().includes('mikrotik') ? 'mikrotik' : 'cisco',
          deviceModel: device.model,
          deviceLocation: locationStr || undefined,
          channel: 'port_configuration',
          command: cliOutput?.trim() || `batch update on ${portIds.length} ports (${portIds.join(', ')})`,
          riskLevel: 'medium',
          status: 'success',
          outputSummary: `Batch updated ${updatedCount} ports on ${device.name}`,
          notes: `Target ports: ${portIds.slice(0, 10).join(', ')}`,
          actor: {
            username: op.username,
            role: op.role,
            ipAddress: op.ip,
          },
        });
      } catch (auditErr) {
        console.warn('[Audit] Could not save batch port command log:', auditErr);
      }
    }

    if ('admin_status' in updates || 'status' in updates) {
      const isDown = updates.admin_status === 'disabled' || updates.status === 'down';
      const portNames = matchedPorts.slice(0, 5).map((p: any) => p.port_id || p.name).join(', ') + (matchedPorts.length > 5 ? ` (+${matchedPorts.length - 5} more)` : '');
      sendTelegramAlert({
        title: isDown ? `PORTS DOWN: ${device.name} [${matchedPorts.length} ports]` : `PORTS UP: ${device.name} [${matchedPorts.length} ports]`,
        level: isDown ? 'warning' : 'resolved',
        message: isDown
          ? `${matchedPorts.length} interfaces on switch "${device.name}" (${device.ip || 'N/A'}) transitioned to DOWN / DISABLED: ${portNames}`
          : `${matchedPorts.length} interfaces on switch "${device.name}" (${device.ip || 'N/A'}) transitioned to UP / ENABLED: ${portNames}`,
        details: `Device: ${device.name}\nIP: ${device.ip || 'N/A'}\nPorts: ${portNames}\nTarget Admin Status: ${updates.admin_status || updates.status}`,
        targetDevice: {
          name: device.name,
          ip: device.ip,
          platform: device.platform,
          type: device.type,
          category: 'switch',
        },
        eventKey: `device:${device.id}:batch_port_status`,
        source: 'port_management',
      }).catch(() => {});
    }

    return res.json({
      success: true,
      updatedCount,
      message: isEn ? `Successfully updated ${updatedCount} ports.` : `تغییرات با موفقیت روی ${updatedCount} پورت اعمال شد.`,
      ports: device.ports,
      cli_output: cliOutput,
      isReal: true,
      ssh_version: backend?.version || sshVersion,
      paramiko_version: backend?.paramikoExpected || 'N/A',
    });
  } catch (err: any) {
    return res.status(500).json({
      success: false,
      error: err.message,
      message: err.message,
    });
  }
});

// PUT /api/devices/:id/ports/:portId - Direct single port configuration update via resolved SSH backend (Port modal)
apiRouter.put([
  '/devices/:id/ports/:portId',
  '/devices/:id/ports/*'
], async (req: Request, res: Response) => {
  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en');
  const devId = req.params.id;
  let rawPortId = req.params.portId || '';
  if (!rawPortId && (req.params as any)[0]) {
    rawPortId = (req.params as any)[0];
  }
  let portId = decodeURIComponent(rawPortId).trim();
  const updates = req.body || {};

  if (!portId || portId.toLowerCase() === 'undefined' || portId.toLowerCase() === 'null') {
    portId = String(
      updates.port_id ||
      updates.port ||
      updates.interface ||
      updates.iface ||
      updates.name ||
      ''
    ).trim();
  }

  try {
    const allDevs = await getAllDevices();
    const device = allDevs.find((d: any) => d.id === devId || d.name === devId);
    if (!device) {
      return res.status(404).json({ success: false, error: 'Device not found', message: isEn ? 'Device not found' : 'دستگاه یافت نشد' });
    }

    const sshVersion = device.ssh_version || device.sshVersion || (device.platform?.includes('modern') ? 'modern' : 'legacy');
    let backend: any = null;
    try {
      backend = resolveSshBackend(sshVersion);
      console.log(`[SinglePortUpdate Resolver] Updating port '${portId}' on device ${devId} using ${backend.version.toUpperCase()} backend (${backend.pythonBin})`);
    } catch (bErr: any) {
      console.warn(`[SinglePortUpdate Resolver] SSH backend resolution deferred: ${bErr.message}`);
    }

    const ports = Array.isArray(device.ports) ? device.ports : [];
    let targetPort = ports.find((p: any) => matchPortFlexible(p, portId) || matchPortFlexible(p, rawPortId));
    if (!targetPort) {
      if (portId && portId.toLowerCase() !== 'undefined' && portId.toLowerCase() !== 'null') {
        const cleanName = portId;
        targetPort = {
          port_id: cleanName,
          name: cleanName,
          port: cleanName,
          status: updates.status || (updates.admin_status === 'disabled' ? 'down' : 'up'),
          admin_status: updates.admin_status || 'enabled',
          mode: updates.mode || 'access',
          vlan: Number(updates.vlan || 1),
          allowed_vlans: String(updates.allowed_vlans || '1-4094'),
          speed: updates.speed || 'auto',
          duplex: updates.duplex || 'auto',
          connected_device: '',
          description: String(updates.description || '').trim(),
        };
        ports.push(targetPort);
        device.ports = ports;
      } else {
        return res.status(404).json({
          success: false,
          error: `Port '${portId}' not found on device '${devId}'`,
          message: isEn ? `Port '${portId}' not found on device '${devId}'` : `پورت «${portId}» روی دستگاه یافت نشد.`,
        });
      }
    }

    const ifaceName = targetPort.port_id || targetPort.port || targetPort.name || portId;
    let cliOutput = '';

    if (deviceSessionPool.hasActiveSession(devId)) {
      const cliCommand = buildPortCliCommand(device.platform || '', ifaceName, updates);
      if (cliCommand) {
        console.log(`[SinglePortUpdate] Executing CLI command on active persistent session for ${devId}`);
        const poolResult = await deviceSessionPool.executeCommandOnSession(devId, cliCommand, 25000);
        if (!poolResult.success) {
          return res.status(400).json({
            success: false,
            error: poolResult.error || 'Port configuration failed on device',
            message: poolResult.error || 'Port configuration failed on device',
            cli_command: cliCommand,
            output: poolResult.output || '',
          });
        }
        device.is_online = true;
        cliOutput = poolResult.output || '';
      }
    } else if ((device.ip || device.ssh_host) && backend) {
      const cliCommand = buildPortCliCommand(device.platform || '', ifaceName, updates);
      if (cliCommand) {
        const result = await executeSshBridgeAction('port-action', {
          device,
          action: 'port_edit_direct',
          interface: ifaceName,
          params: updates,
          cli_command: cliCommand,
        }, backend.version, 25000);

        if (!result || result.success === false) {
          return res.status(400).json({
            success: false,
            error: result?.error || 'Port configuration failed on device',
            message: result?.message || result?.error || 'Port configuration failed on device',
            cli_command: cliCommand,
            output: result?.output || '',
            ssh_version: backend?.version || sshVersion,
            paramiko_version: result?.paramiko_version || backend?.paramikoExpected || 'N/A',
          });
        }
        device.is_online = true;
        cliOutput = result.output || '';
      }
    }

    // Apply updates
    if ('admin_status' in updates) {
      targetPort.admin_status = updates.admin_status;
      if (updates.admin_status === 'disabled') {
        targetPort.status = 'down';
      } else {
        targetPort.status = 'up';
      }
    }
    if ('status' in updates && targetPort.admin_status !== 'disabled') {
      targetPort.status = updates.status;
    }
    if ('mode' in updates) {
      targetPort.mode = updates.mode;
      if (updates.mode === 'trunk' && !targetPort.allowed_vlans) {
        targetPort.allowed_vlans = '1-4094';
      }
    }
    if ('vlan' in updates) {
      targetPort.vlan = Number(updates.vlan);
      if (targetPort.mode === 'access') {
        targetPort.allowed_vlans = String(updates.vlan);
      }
    }
    if ('allowed_vlans' in updates) {
      targetPort.allowed_vlans = String(updates.allowed_vlans);
    }
    if ('speed' in updates) {
      targetPort.speed = updates.speed;
    }
    if ('duplex' in updates) {
      targetPort.duplex = updates.duplex;
    }
    if ('description' in updates) {
      targetPort.description = String(updates.description).trim();
    }
    if ('port_security_enabled' in updates) {
      targetPort.port_security_enabled = Boolean(updates.port_security_enabled);
      targetPort.port_security_status = targetPort.port_security_enabled ? (targetPort.status === 'up' ? 'secure-up' : 'secure-down') : 'disabled';
    }
    if ('port_security_mode' in updates) {
      targetPort.port_security_mode = updates.port_security_mode;
    }
    if ('port_security_max_mac' in updates) {
      targetPort.port_security_max_mac = Number(updates.port_security_max_mac);
    }
    if ('port_security_configured_mac' in updates) {
      targetPort.port_security_configured_mac = String(updates.port_security_configured_mac).trim();
    }
    if ('port_security_violation' in updates) {
      targetPort.port_security_violation = updates.port_security_violation;
    }
    if ('port_security_learned_macs' in updates && Array.isArray(updates.port_security_learned_macs)) {
      targetPort.port_security_learned_macs = updates.port_security_learned_macs;
    }
    if (!targetPort.port_security_enabled) {
      targetPort.port_security_learned_macs = [];
    }

    device.has_unsaved_changes = true;
    device.last_modified_time = new Date().toISOString();
    await updateDevice(device.id, { ports: device.ports, has_unsaved_changes: true });

    // Authoritatively record physical port command in device_command_audit_logs if not already logged client-side
    if (req.headers['x-client-audit-logged'] !== 'true') {
      try {
        const op = getReqOperator(req);
        const locationStr = [device.building, device.floor, device.unit, device.rack ? `Rack ${device.rack}` : ''].filter(Boolean).join(' > ');
        await addDeviceCommandLog({
          deviceId: device.id,
          deviceName: device.name,
          deviceIp: device.ip,
          deviceVendor: (device.model || '').toLowerCase().includes('mikrotik') ? 'mikrotik' : 'cisco',
          deviceModel: device.model,
          deviceLocation: locationStr || undefined,
          channel: 'port_configuration',
          command: cliOutput?.trim() || `interface ${portId}\n ${Object.entries(updates).map(([k, v]) => `${k} ${v}`).join('; ')}`,
          riskLevel: updates.admin_status === 'disabled' ? 'medium' : 'low',
          status: 'success',
          outputSummary: `Configured interface ${portId} on ${device.name}`,
          notes: `Updated parameters: ${Object.keys(updates).join(', ')}`,
          actor: {
            username: op.username,
            role: op.role,
            ipAddress: op.ip,
          },
        });
      } catch (auditErr) {
        console.warn('[Audit] Could not save single port command log:', auditErr);
      }
    }

    if ('admin_status' in updates || 'status' in updates) {
      const isDown = updates.admin_status === 'disabled' || updates.status === 'down' || targetPort.status === 'down';
      sendTelegramAlert({
        title: isDown ? `PORT DOWN: ${device.name} [${ifaceName}]` : `PORT UP: ${device.name} [${ifaceName}]`,
        level: isDown ? 'warning' : 'resolved',
        message: isDown
          ? `Interface "${ifaceName}" on switch "${device.name}" (${device.ip || 'N/A'}) transitioned to DOWN / DISABLED.`
          : `Interface "${ifaceName}" on switch "${device.name}" (${device.ip || 'N/A'}) is now UP / ACTIVE.`,
        details: `Device: ${device.name}\nIP: ${device.ip || 'N/A'}\nInterface: ${ifaceName}\nVLAN: ${targetPort.vlan || 'Default'}\nAdmin Status: ${targetPort.admin_status}`,
        targetDevice: {
          name: device.name,
          ip: device.ip,
          platform: device.platform,
          type: device.type,
          category: 'switch',
        },
        eventKey: `device:${device.id}:port_${ifaceName}`,
        source: 'port_management',
      }).catch(() => {});
    }

    return res.json({
      success: true,
      port: targetPort,
      message: isEn ? `Port ${portId} updated successfully.` : `پورت ${portId} با موفقیت به‌روزرسانی شد.`,
      cli_output: cliOutput,
      isReal: true,
      ssh_version: backend?.version || sshVersion,
      paramiko_version: backend?.paramikoExpected || 'N/A',
    });
  } catch (err: any) {
    return res.status(500).json({
      success: false,
      error: err.message,
      message: err.message,
    });
  }
});

// GET /api/devices/:id/cisco-ports/stats - Adaptive Dual-Mode Cisco Port Statistics (SNMP with SSH Fallback)
// Supports clean query parameters (?portId=...), wildcard path segments, and legacy path parameters
apiRouter.get([
  '/devices/:id/cisco-ports/stats',
  '/devices/:id/cisco-ports',
  '/devices/:id/cisco-ports/:portId/stats',
  '/devices/:id/cisco-ports/*'
], async (req: Request, res: Response) => {
  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en');
  const devId = req.params.id;

  // Extract portId from query parameters, path params, or wildcard
  let portId = (req.query.portId || req.query.port || req.query.name || req.query.interface || '') as string;
  if (!portId && req.params.portId) {
    portId = req.params.portId;
  }
  if (!portId && (req.params as any)[0]) {
    const raw = (req.params as any)[0];
    portId = raw.replace(/\/stats\/?$/, '').replace(/^stats\/?/, '');
  }
  portId = decodeURIComponent(portId).trim();

  try {
    const allDevs = await getAllDevices();
    let device = allDevs.find((d: any) => String(d.id) === String(devId) || d.name === devId);
    if (!device) {
      try {
        const netPath = path.join(process.cwd(), 'backend', 'network_data.json');
        if (fs.existsSync(netPath)) {
          const raw = JSON.parse(fs.readFileSync(netPath, 'utf-8'));
          const fallbackDev = (raw.devices || []).find((d: any) => String(d.id) === String(devId) || d.name === devId);
          if (fallbackDev) {
            device = fallbackDev;
          }
        }
      } catch {}
    }

    if (!device) {
      return res.status(404).json({
        success: false,
        connected: false,
        error: 'Device not found',
        message: isEn ? 'Device not found' : 'دستگاه مورد نظر یافت نشد',
      });
    }

    const stats = await fetchCiscoPortStatistics(device, portId);
    return res.json(stats);
  } catch (err: any) {
    return res.status(500).json({
      success: false,
      connected: false,
      error: err.message || 'Error querying Cisco port statistics',
      message: isEn ? (err.message || 'Error querying Cisco port statistics') : 'خطا در دریافت آمار ترافیک پورت سیسکو',
    });
  }
});

// Authentic ICMP Ping Engine using native OS ping with numeric-only (-n) DNS bypass
// and authentic TCP management-port reachability fallback when ICMP is blocked or unprivileged.
const execFileAsync = promisify(execFile);

function resolvePingBinary(): string {
  if (process.platform === 'win32') return 'ping';
  const candidates = ['/usr/bin/ping', '/bin/ping', '/sbin/ping'];
  for (const bin of candidates) {
    try {
      if (fs.existsSync(bin)) return bin;
    } catch {}
  }
  return 'ping';
}

function probeTcpReachability(
  host: string,
  ports: number[],
  timeoutMs: number = 1500
): Promise<{ reachable: boolean; latency_ms: number | null; port?: number }> {
  const uniquePorts = Array.from(
    new Set(ports.filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535))
  );
  if (!host || uniquePorts.length === 0) {
    return Promise.resolve({ reachable: false, latency_ms: null });
  }

  return new Promise((resolve) => {
    let settled = false;
    let remaining = uniquePorts.length;
    const sockets: net.Socket[] = [];

    const finish = (result: { reachable: boolean; latency_ms: number | null; port?: number }) => {
      if (settled) return;
      settled = true;
      for (const s of sockets) {
        try {
          s.destroy();
        } catch {}
      }
      resolve(result);
    };

    for (const port of uniquePorts) {
      const start = Date.now();
      const socket = new net.Socket();
      sockets.push(socket);
      socket.setTimeout(timeoutMs);

      const onFail = () => {
        try {
          socket.destroy();
        } catch {}
        remaining--;
        if (remaining <= 0) {
          finish({ reachable: false, latency_ms: null });
        }
      };

      socket.once('connect', () => {
        const latency = Math.max(0.1, Math.round((Date.now() - start) * 10) / 10);
        finish({ reachable: true, latency_ms: latency, port });
      });
      socket.once('timeout', onFail);
      socket.once('error', onFail);

      try {
        socket.connect(port, host);
      } catch {
        onFail();
      }
    }
  });
}

function parsePingOutputMetrics(raw: string): { lossPct: number | null; avgLatency: number | null; receivedCount: number | null } {
  const lossMatch = raw.match(/([0-9]+(?:\.[0-9]+)?)%\s*(?:packet\s*)?loss/i);
  const lossPct = lossMatch ? parseFloat(lossMatch[1]) : null;

  const recvMatch = raw.match(/([0-9]+)\s*(?:packets\s*)?received/i) || raw.match(/Received\s*=\s*([0-9]+)/i);
  const receivedCount = recvMatch ? parseInt(recvMatch[1], 10) : null;

  // GNU iputils: rtt min/avg/max/mdev = 0.159/0.184/0.210/0.025 ms
  // BusyBox / macOS: round-trip min/avg/max = 0.159/0.184/0.210 ms
  const rttMatch = raw.match(/(?:rtt|round-trip)\s+min\/avg\/max(?:\/[a-z]+)?\s*=\s*([0-9.]+)\/([0-9.]+)\/([0-9.]+)/i);
  if (rttMatch) {
    return { lossPct, avgLatency: parseFloat(rttMatch[2]), receivedCount };
  }

  // Windows: Average = 12ms
  const winAvgMatch = raw.match(/Average\s*=\s*([0-9.]+)\s*ms/i);
  if (winAvgMatch) {
    return { lossPct, avgLatency: parseFloat(winAvgMatch[1]), receivedCount };
  }

  // Per-packet replies: time=0.42 ms or time<1ms
  const replyTimes: number[] = [];
  const timeRegex = /time[=<]\s*([0-9.]+)\s*ms/gi;
  let m: RegExpExecArray | null;
  while ((m = timeRegex.exec(raw)) !== null) {
    const val = parseFloat(m[1]);
    if (Number.isFinite(val)) replyTimes.push(val);
  }
  if (replyTimes.length > 0) {
    const avg = replyTimes.reduce((a, b) => a + b, 0) / replyTimes.length;
    return { lossPct, avgLatency: avg, receivedCount: receivedCount ?? replyTimes.length };
  }

  return { lossPct, avgLatency: null, receivedCount };
}

function sanitizeDeviceForClient(dev: any): any {
  if (!dev) return dev;
  const d = { ...dev };
  if (!d.platform) d.platform = 'cisco_ios_xe';
  if (!d.connection_mode) d.connection_mode = 'simulator';
  const conn = { ...(d.connection || {}) };
  delete conn.password;
  delete conn.private_key;
  d.connection = conn;
  d.ssh_password_set = Boolean(
    dev.ssh_password_set || dev.ssh_vault_item_id || (dev.ssh_password && String(dev.ssh_password).trim().length > 0)
  );
  d.enable_password_set = Boolean(
    dev.enable_password_set || dev.enable_vault_item_id || (dev.enable_password && String(dev.enable_password).trim().length > 0)
  );
  delete d.ssh_password;
  delete d.enable_password;
  d.snmp_community_set = Boolean(d.snmp_community || d.snmp_community_vault_item_id);
  d.snmp_v3_auth_password_set = Boolean(d.snmp_v3_auth_password || d.snmp_v3_auth_vault_item_id);
  d.snmp_v3_priv_password_set = Boolean(d.snmp_v3_priv_password || d.snmp_v3_priv_vault_item_id);
  delete d.snmp_community;
  delete d.snmp_v3_auth_password;
  delete d.snmp_v3_priv_password;
  return d;
}

export async function executeRealIcmpPing(
  ip: string,
  count: number = 2,
  timeoutSec: number = 1,
  fallbackTcpPorts?: number[]
): Promise<{
  is_online: boolean;
  latency_ms: number | null;
  packet_loss: number;
  probe_method?: 'icmp' | 'tcp';
  raw_output?: string;
}> {
  const cleanIp = String(ip || '').trim();
  if (!cleanIp || !/^[a-zA-Z0-9.:_-]+$/.test(cleanIp) || cleanIp.startsWith('-')) {
    return { is_online: false, latency_ms: null, packet_loss: 100 };
  }

  const safeCount = Math.max(1, Math.min(5, Math.floor(Number(count) || 2)));
  const safeTimeout = Math.max(1, Math.min(5, Math.floor(Number(timeoutSec) || 1)));
  const pingBin = resolvePingBinary();
  const isWin = process.platform === 'win32';
  // Use -n (numeric only) on Linux/Unix to avoid blocking reverse-DNS PTR lookups on private LAN IPs!
  const args = isWin
    ? ['-n', String(safeCount), '-w', String(safeTimeout * 1000), cleanIp]
    : ['-n', '-c', String(safeCount), '-W', String(safeTimeout), cleanIp];

  const start = Date.now();
  let raw = '';
  let icmpUnavailableAtOsLevel = false;
  try {
    const { stdout, stderr } = await execFileAsync(pingBin, args, {
      timeout: (safeCount * safeTimeout + 4) * 1000,
    });
    raw = (stdout || stderr || '').trim();
    const elapsed = Math.max(0.1, Date.now() - start);
    const { lossPct, avgLatency, receivedCount } = parsePingOutputMetrics(raw);

    const hasReplies =
      (lossPct !== null && lossPct < 100) ||
      (receivedCount !== null && receivedCount > 0) ||
      avgLatency !== null;

    if (hasReplies) {
      const effectiveLatency = avgLatency !== null ? avgLatency : elapsed;
      return {
        is_online: true,
        latency_ms: Math.round(effectiveLatency * 10) / 10,
        packet_loss: lossPct !== null ? lossPct : 0,
        probe_method: 'icmp',
        raw_output: raw,
      };
    }
  } catch (err: any) {
    raw = `${err?.stdout || ''}\n${err?.stderr || ''}\n${err?.message || ''}`.trim();
    const errCode = String(err?.code || '').toUpperCase();
    if (
      errCode === 'ENOENT' ||
      errCode === 'EPERM' ||
      errCode === 'EACCES' ||
      /operation not permitted|permission denied|not found|cap_net_raw|socket:/i.test(raw)
    ) {
      icmpUnavailableAtOsLevel = true;
    }

    const { lossPct, avgLatency, receivedCount } = parsePingOutputMetrics(raw);

    // Partial packet delivery (e.g., 1 of 2 received -> 50% loss) can still return exit code 1 on some ping builds
    if ((receivedCount !== null && receivedCount > 0) || (lossPct !== null && lossPct < 100 && avgLatency !== null)) {
      return {
        is_online: true,
        latency_ms: avgLatency !== null ? Math.round(avgLatency * 10) / 10 : Math.max(0.1, Date.now() - start),
        packet_loss: lossPct !== null ? lossPct : 50,
        probe_method: 'icmp',
        raw_output: raw,
      };
    }
  }

  // Only fall back to TCP management-port reachability if OS/container cannot send ICMP raw sockets
  // (Prevents false-positive Online status from proxies/firewalls on ports 80/443 when ICMP genuinely failed)
  if (icmpUnavailableAtOsLevel && Array.isArray(fallbackTcpPorts) && fallbackTcpPorts.length > 0) {
    const tcp = await probeTcpReachability(cleanIp, fallbackTcpPorts, 1200);
    if (tcp.reachable) {
      return {
        is_online: true,
        latency_ms: tcp.latency_ms,
        packet_loss: 0,
        probe_method: 'tcp',
        raw_output: raw || `TCP port ${tcp.port} reachable (${tcp.latency_ms} ms)`,
      };
    }
  }

  return {
    is_online: false,
    latency_ms: null,
    packet_loss: 100,
    probe_method: 'icmp',
    raw_output: raw,
  };
}

function getDeviceProbePorts(device: any): number[] {
  const ports: number[] = [];
  const sshPort = Number(device?.ssh_port || device?.connection?.port);
  if (Number.isInteger(sshPort) && sshPort >= 1 && sshPort <= 65535) ports.push(sshPort);
  const winboxPort = Number(device?.winbox_port);
  if (Number.isInteger(winboxPort) && winboxPort >= 1 && winboxPort <= 65535) ports.push(winboxPort);
  const platform = String(device?.platform || '').toLowerCase();
  if (platform.includes('mikrotik')) ports.push(8291, 8728);
  ports.push(22, 23);
  return Array.from(new Set(ports));
}

function normalizePingTargetHost(device: any): string {
  const raw = String(device?.ip || device?.ssh_host || '').trim();
  if (!raw) return '';
  return raw.split('/')[0].trim();
}

// POST /ping/:id (and /devices/:id/ping alias for JIT approval executor) - Authentic reachability probe
apiRouter.post(['/ping/:id', '/devices/:id/ping'], async (req: Request, res: Response) => {
  try {
    const { user } = await resolveRequestContextPolicy(req);
    if (!user) {
      return res.status(401).json({
        success: false,
        error: 'Unauthorized: Authentication required to ping devices.',
        errorFa: 'عدم احراز هویت: برای تست پینگ تجهیزات ابتدا وارد حساب کاربری شوید.',
      });
    }

    const devId = (req.params.id || '').trim();
    const device = await getDeviceById(devId);
    if (!device) {
      return res.status(404).json({ success: false, error: 'Device not found', errorFa: 'تجهیز مورد نظر یافت نشد.' });
    }

    const check = await assertDeviceScopeAccess(req, devId, 'ping_keepalive');
    if (!check.allowed) {
      return res.status(check.status || 403).json({ success: false, error: check.error, errorFa: check.errorFa });
    }

    const targetHost = normalizePingTargetHost(device);
    const pingResult = await executeRealIcmpPing(targetHost, 2, 1, getDeviceProbePorts(device));
    const lastSeen = pingResult.is_online ? new Date().toISOString() : (device.last_seen || '');

    const updatedDevice = await updateDevicePingTelemetry(device.id, {
      is_online: pingResult.is_online,
      latency_ms: pingResult.latency_ms,
      packet_loss: pingResult.packet_loss,
      last_seen: lastSeen,
    });

    if (!pingResult.is_online) {
      sendTelegramAlert({
        title: `HOST UNREACHABLE: ${device.name} (${device.ip || 'N/A'})`,
        level: 'critical',
        message: `Device "${device.name}" failed ICMP keepalive probe (100% packet loss).`,
        details: `Device: ${device.name}\nIP: ${device.ip || 'N/A'}\nPlatform: ${device.platform || 'Network Device'}`,
        targetDevice: {
          name: device.name,
          ip: device.ip,
          platform: device.platform,
          type: device.type,
          category: 'switch',
        },
        eventKey: `device:${device.id}:down`,
        source: 'ping_keepalive',
      }).catch(() => {});
    } else if (device.is_online === false && pingResult.is_online) {
      sendTelegramAlert({
        title: `HOST RECOVERED: ${device.name} (${device.ip || 'N/A'})`,
        level: 'resolved',
        message: `Device "${device.name}" is back online and responding (${pingResult.latency_ms}ms via ${(pingResult.probe_method || 'icmp').toUpperCase()}).`,
        details: `Device: ${device.name}\nIP: ${device.ip || 'N/A'}\nLatency: ${pingResult.latency_ms}ms\nPacket Loss: ${pingResult.packet_loss}%`,
        targetDevice: {
          name: device.name,
          ip: device.ip,
          platform: device.platform,
          type: device.type,
          category: 'switch',
        },
        eventKey: `device:${device.id}:down`,
        source: 'ping_keepalive',
      }).catch(() => {});
    }

    const safeDevice = sanitizeDeviceForClient(
      updatedDevice || {
        ...device,
        is_online: pingResult.is_online,
        latency_ms: pingResult.latency_ms,
        packet_loss: pingResult.packet_loss,
        last_seen: lastSeen || device.last_seen,
      }
    );

    return res.json({
      success: true,
      device: safeDevice,
      ping_result: {
        ip: targetHost,
        is_online: pingResult.is_online,
        latency_ms: pingResult.latency_ms,
        packet_loss: pingResult.packet_loss,
        probe_method: pingResult.probe_method || 'icmp',
      },
    });
  } catch (err: any) {
    console.error('[ICMP Ping Route Error]', err);
    return res.status(500).json({ success: false, error: err.message || 'ICMP Ping execution failed' });
  }
});

// POST /ping-all - Fast bounded concurrent authentic ICMP probe for all authorized network devices
apiRouter.post('/ping-all', async (req: Request, res: Response) => {
  try {
    const { user, effectivePolicy, isSuperAdmin, allowedDeviceIds } = await resolveRequestContextPolicy(req);
    if (!user) {
      return res.status(401).json({
        success: false,
        error: 'Unauthorized: Authentication required to ping devices.',
        errorFa: 'عدم احراز هویت: برای پایش تجهیزات ابتدا وارد حساب کاربری شوید.',
      });
    }

    if (!isSuperAdmin && effectivePolicy && effectivePolicy.canViewDevices === false) {
      return res.status(403).json({
        success: false,
        error: 'Access denied: Your account policy prohibits access to Network Equipment Inventory.',
        errorFa: 'عدم دسترسی: حساب شما فاقد مجوز دسترسی به موجودی تجهیزات شبکه است.',
      });
    }

    let allDevices = await getAllDevices();
    if (!isSuperAdmin && effectivePolicy && allowedDeviceIds !== null) {
      const allowedSet = new Set(allowedDeviceIds.map((id) => String(id).trim().toLowerCase()));
      allDevices = allDevices.filter((d: any) => allowedSet.has(String(d.id).trim().toLowerCase()));
    }

    // Optional subset scoping if caller specifies explicit deviceIds (still bounded by RBAC above)
    if (Array.isArray(req.body?.deviceIds) && req.body.deviceIds.length > 0) {
      const requestedSet = new Set(req.body.deviceIds.map((id: any) => String(id).trim().toLowerCase()));
      allDevices = allDevices.filter((d: any) => requestedSet.has(String(d.id).trim().toLowerCase()));
    }

    // Filter out devices where ping_keepalive is explicitly denied by RBAC
    if (!isSuperAdmin && effectivePolicy) {
      allDevices = allDevices.filter(
        (d: any) => evaluateDeviceActionDecision(effectivePolicy, d.id, 'ping_keepalive') !== 'deny'
      );
    }

    // Bounded concurrency worker pool (max 20 simultaneous fast ICMP probes)
    const CONCURRENCY = 20;
    const results: any[] = new Array(allDevices.length);
    const dbUpdates: Array<{
      id: string;
      is_online: boolean;
      latency_ms: number | null;
      packet_loss: number;
      last_seen: string;
    }> = [];

    let cursor = 0;
    const worker = async () => {
      while (cursor < allDevices.length) {
        const idx = cursor++;
        const dev = allDevices[idx];
        const targetHost = normalizePingTargetHost(dev);
        // Fast 1-packet ICMP check (1s timeout) keeps large fleets responsive (<5s even with many offline hosts)
        const pingRes = await executeRealIcmpPing(targetHost, 1, 1, getDeviceProbePorts(dev));
        const lastSeen = pingRes.is_online ? new Date().toISOString() : (dev.last_seen || '');

        dbUpdates.push({
          id: dev.id,
          is_online: pingRes.is_online,
          latency_ms: pingRes.latency_ms,
          packet_loss: pingRes.packet_loss,
          last_seen: lastSeen,
        });

        if (!pingRes.is_online && dev.is_online !== false) {
          sendTelegramAlert({
            title: `HOST UNREACHABLE: ${dev.name} (${dev.ip || 'N/A'})`,
            level: 'critical',
            message: `Network device "${dev.name}" failed concurrent ICMP health check.`,
            details: `Device: ${dev.name}\nIP: ${dev.ip || 'N/A'}\nPacket loss: 100%`,
            targetDevice: {
              name: dev.name,
              ip: dev.ip,
              platform: dev.platform,
              type: dev.type,
              category: 'switch',
            },
            eventKey: `device:${dev.id}:down`,
            source: 'ping_all',
          }).catch(() => {});
        } else if (dev.is_online === false && pingRes.is_online) {
          sendTelegramAlert({
            title: `HOST RECOVERED: ${dev.name} (${dev.ip || 'N/A'})`,
            level: 'resolved',
            message: `Network device "${dev.name}" recovered and is responding (${pingRes.latency_ms}ms).`,
            details: `Device: ${dev.name}\nIP: ${dev.ip || 'N/A'}\nLatency: ${pingRes.latency_ms}ms`,
            targetDevice: {
              name: dev.name,
              ip: dev.ip,
              platform: dev.platform,
              type: dev.type,
              category: 'switch',
            },
            eventKey: `device:${dev.id}:down`,
            source: 'ping_all',
          }).catch(() => {});
        }

        results[idx] = {
          id: dev.id,
          name: dev.name,
          ip: targetHost,
          is_online: pingRes.is_online,
          latency_ms: pingRes.latency_ms,
          packet_loss: pingRes.packet_loss,
          last_seen: lastSeen || undefined,
          probe_method: pingRes.probe_method || 'icmp',
        };
      }
    };

    const workerCount = Math.min(CONCURRENCY, Math.max(1, allDevices.length));
    await Promise.all(Array.from({ length: workerCount }, () => worker()));

    // Atomic batch persistence (PostgreSQL TIMESTAMPTZ-safe + JSON fallback)
    if (dbUpdates.length > 0) {
      await updateDevicesPingTelemetryBatch(dbUpdates);
    }

    const onlineCount = results.filter((r) => r?.is_online).length;
    const offlineCount = results.length - onlineCount;

    return res.json({
      success: true,
      message: `پایش وضعیت ${results.length} تجهیز تکمیل شد (${onlineCount} آنلاین، ${offlineCount} آفلاین).`,
      message_en: `Ping sweep completed for ${results.length} devices (${onlineCount} online, ${offlineCount} offline).`,
      online_count: onlineCount,
      offline_count: offlineCount,
      results,
    });
  } catch (err: any) {
    console.error('[ICMP Ping All Route Error]', err);
    return res.status(500).json({ success: false, error: err.message || 'ICMP Ping All failed' });
  }
});

// POST /schematic/export-authorize - PostgreSQL-authoritative RBAC gate & Audit Log for Visual Schematic HTML Export
apiRouter.post('/schematic/export-authorize', async (req: Request, res: Response) => {
  try {
    const { user, effectivePolicy, isSuperAdmin } = await resolveRequestContextPolicy(req);
    if (!user) {
      return res.status(401).json({
        success: false,
        error: 'Unauthorized: Authentication required to export schematic topology.',
        errorFa: 'عدم احراز هویت: برای دریافت خروجی نقشه شماتیک ابتدا وارد حساب کاربری شوید.',
      });
    }

    const rawMode = String(req.body?.exportMode || 'card').trim().toLowerCase();
    const exportMode: 'card' | 'physical' | 'both' =
      rawMode === 'physical' ? 'physical' : rawMode === 'both' ? 'both' : 'card';
    const mapId = String(req.body?.mapId || '').trim().slice(0, 128);
    const mapName = String(req.body?.mapName || 'Network Schematic').trim().slice(0, 160);
    const deviceCount = Math.max(0, Math.min(10000, Math.floor(Number(req.body?.deviceCount) || 0)));
    const linkCount = Math.max(0, Math.min(50000, Math.floor(Number(req.body?.linkCount) || 0)));
    const vlanCount = Math.max(0, Math.min(4096, Math.floor(Number(req.body?.vlanCount) || 0)));
    const rackCount = Math.max(0, Math.min(2000, Math.floor(Number(req.body?.rackCount) || 0)));
    const towerCount = Math.max(0, Math.min(2000, Math.floor(Number(req.body?.towerCount) || 0)));

    const actorName = user.username || user.fullName || 'unknown';
    const actorRole = user.role || effectivePolicy?.name || 'User';
    const clientIp =
      (Array.isArray(req.headers['x-forwarded-for'])
        ? req.headers['x-forwarded-for'][0]
        : String(req.headers['x-forwarded-for'] || '').split(',')[0]
      ).trim() || req.socket?.remoteAddress || 'unknown';

    // Strict fail-closed RBAC check: ONLY Super Admin or policies explicitly granted canExportSchematic === true
    const allowed =
      isSuperAdmin ||
      (effectivePolicy?.canExportSchematic === true && effectivePolicy?.canViewTopology !== false);

    if (!allowed) {
      await addPortalAuditLog({
        category: 'topology',
        action: 'schematic_export_denied',
        title: `تلاش غیرمجاز برای خروجی ویژوال شماتیک: ${mapName}`,
        title_en: `Unauthorized Schematic Visual HTML Export Attempt: ${mapName}`,
        description: `کاربر ${actorName} بدون مجوز canExportSchematic قصد دریافت خروجی HTML (${exportMode}) از نقشه «${mapName}» را داشت.`,
        description_en: `User ${actorName} attempted to export schematic map "${mapName}" (${exportMode}) without canExportSchematic permission.`,
        userName: actorName,
        userRole: actorRole,
        status: 'denied',
        severity: 'warning',
        targetName: mapName,
        targetId: mapId || undefined,
        clientIp,
        metadata: { mapId, mapName, exportMode, deviceCount, linkCount, vlanCount },
      }).catch(() => {});

      return res.status(403).json({
        success: false,
        error: 'Access denied: Your account policy does not permit exporting schematic topology maps (canExportSchematic).',
        errorFa: 'عدم دسترسی: پالیسی دسترسی فعال شما فاقد مجوز خروجی گرفتن از نقشه شماتیک (canExportSchematic) است.',
      });
    }

    const modeLabelFa =
      exportMode === 'both' ? 'کارت + فیزیکی (جامع)' : exportMode === 'physical' ? 'نمای فیزیکی' : 'نمای کارت‌ها';
    const modeLabelEn =
      exportMode === 'both' ? 'Card + Physical (Full)' : exportMode === 'physical' ? 'Physical View' : 'Card View';

    await addPortalAuditLog({
      category: 'topology',
      action: 'schematic_export_html',
      title: `خروجی ویژوال HTML نقشه شماتیک: ${mapName} (${modeLabelFa})`,
      title_en: `Exported Visual HTML Schematic: ${mapName} (${modeLabelEn})`,
      description: `خروجی HTML شامل ${deviceCount} تجهیز، ${linkCount} لینک، ${vlanCount} VLAN، ${rackCount} رک و ${towerCount} دکل دریافت شد.`,
      description_en: `Downloaded interactive HTML export containing ${deviceCount} devices, ${linkCount} links, ${vlanCount} VLANs, ${rackCount} racks, and ${towerCount} towers.`,
      userName: actorName,
      userRole: actorRole,
      status: 'success',
      severity: 'info',
      targetName: mapName,
      targetId: mapId || undefined,
      clientIp,
      metadata: { mapId, mapName, exportMode, deviceCount, linkCount, vlanCount, rackCount, towerCount },
    }).catch(() => {});

    return res.json({
      success: true,
      authorized: true,
      exportedBy: actorName,
      exportedAt: new Date().toISOString(),
    });
  } catch (err: any) {
    console.error('[Schematic Export Authorize Error]', err);
    return res.status(500).json({
      success: false,
      error: err.message || 'Failed to authorize schematic export',
      errorFa: 'خطا در بررسی مجوز خروجی نقشه شماتیک',
    });
  }
});

