// POST /helpdesk/health - Module 1: Read-Only Endpoint System Health & Live Processes
apiRouter.post('/helpdesk/health', async (req: Request, res: Response) => {
  const auth = await resolveHelpdeskAuth(req, 'diagnostics');
  if (!auth.ok) {
    return sendHelpdeskAuthFailure(res, auth);
  }
  const target = extractHelpdeskTargetFromBody(req.body);
  const skipHistory = req.body?.skipHistory === true;
  try {
    const data = await collectEndpointHealth(target);
    await addPortalAuditLog({
      category: 'system',
      action: 'helpdesk_health_inspect',
      title: `پایش سلامت و پروسس‌های سیستم کاربر: ${data.targetIp}`,
      title_en: `HelpDesk Read-Only Health & Process Inspection: ${data.targetIp}`,
      description: `اتصال (${data.protocolUsed}) به ${data.hostname} (${data.targetIp}) — CPU: ${data.cpu.usagePercent}%، RAM: ${data.memory.usedPercent}%، پروسس‌ها: ${data.totalProcessCount}`,
      description_en: `Connected via ${data.protocolUsed} to ${data.hostname} (${data.targetIp}) — CPU: ${data.cpu.usagePercent}%, RAM: ${data.memory.usedPercent}%, Processes: ${data.totalProcessCount}`,
      userName: auth.actorName,
      userRole: auth.actorRole,
      status: 'success',
      severity: 'info',
      targetName: data.hostname || data.targetIp,
      clientIp: auth.clientIp,
      metadata: { targetIp: data.targetIp, protocol: data.protocolUsed, osFamily: data.osFamily },
    }).catch(() => {});

    if (!skipHistory) {
      await addHelpdeskConnectionHistoryInDb({
        targetIp: data.targetIp || target.targetIp,
        hostname: data.hostname || '',
        osName: data.osName || '',
        osFamily: data.osFamily === 'windows' || data.osFamily === 'linux' ? data.osFamily : 'unknown',
        loggedInUser: data.loggedInUser || '',
        sessionUsername: target.username,
        protocolRequested: target.protocol,
        protocolUsed: data.protocolUsed || target.protocol,
        portUsed: Number(data.portUsed || target.port || 0),
        jeaConfigName: target.jeaConfigName || '',
        status: 'success',
        actorName: auth.actorName,
        actorRole: auth.actorRole,
      }).catch(() => {});
    }

    return res.json({
      success: true,
      data,
      rateLimit: getHelpdeskRateLimitStatus(auth.actorName),
    });
  } catch (err: any) {
    const msg = String(err?.message || 'Endpoint health inspection failed');
    const isInputErr = /invalid|blocked|required/i.test(msg);
    await addPortalAuditLog({
      category: 'system',
      action: 'helpdesk_health_failed',
      title: `خطا در اتصال هلپ‌دسک به ${target.targetIp || 'Unknown'}`,
      title_en: `HelpDesk Health Connection Failed: ${target.targetIp || 'Unknown'}`,
      description: msg.slice(0, 300),
      description_en: msg.slice(0, 300),
      userName: auth.actorName,
      userRole: auth.actorRole,
      status: 'failed',
      severity: 'warning',
      targetName: target.targetIp || 'unknown',
      clientIp: auth.clientIp,
      metadata: { targetIp: target.targetIp, protocol: target.protocol },
    }).catch(() => {});
    if (!skipHistory && target.targetIp) {
      await addHelpdeskConnectionHistoryInDb({
        targetIp: target.targetIp,
        hostname: '',
        osName: '',
        osFamily: 'unknown',
        loggedInUser: '',
        sessionUsername: target.username,
        protocolRequested: target.protocol,
        protocolUsed: target.protocol,
        portUsed: Number(target.port || 0),
        jeaConfigName: target.jeaConfigName || '',
        status: 'failed',
        errorMessage: msg.slice(0, 300),
        actorName: auth.actorName,
        actorRole: auth.actorRole,
      }).catch(() => {});
    }
    return res.status(isInputErr ? 400 : 502).json({
      success: false,
      error: msg,
      errorFa: msg,
    });
  }
});

// POST /helpdesk/computer/rename - Rename Endpoint Hostname (Windows Rename-Computer / Linux hostnamectl)
apiRouter.post('/helpdesk/computer/rename', async (req: Request, res: Response) => {
  const auth = await resolveHelpdeskAuth(req, 'actions');
  if (!auth.ok) {
    return sendHelpdeskAuthFailure(res, auth);
  }
  const target = extractHelpdeskTargetFromBody(req.body);
  const newHostname = String(req.body?.newHostname || '').trim();
  const restartAfter = Boolean(req.body?.restartAfter);
  if (!newHostname) {
    return res.status(400).json({
      success: false,
      error: 'New computer name is required.',
      errorFa: 'نام جدید کامپیوتر الزامی است.',
    });
  }

  const rl = checkAndRecordHelpdeskWriteRateLimit(auth.actorName, target.targetIp, 'computer_rename');
  if (!rl.allowed) {
    await logHelpdeskRateLimitAudit({
      actorName: auth.actorName,
      actorRole: auth.actorRole,
      clientIp: auth.clientIp,
      targetIp: target.targetIp,
      actionName: 'computer_rename',
      rl,
    });
    return res.status(429).json({
      success: false,
      error: rl.reason,
      errorFa: rl.reasonFa,
      rateLimit: rl.status,
    });
  }

  try {
    const data = await renameEndpointComputer(target, { newHostname, restartAfter });
    await addPortalAuditLog({
      category: 'helpdesk',
      action: 'helpdesk_computer_rename',
      title: `تغییر نام کامپیوتر ${data.targetIp} به «${newHostname}»`,
      title_en: `HelpDesk Computer Renamed on ${data.targetIp} -> ${newHostname}`,
      description: data.messageFa,
      description_en: data.message,
      userName: auth.actorName,
      userRole: auth.actorRole,
      status: data.success ? 'success' : 'failed',
      severity: 'warning',
      targetName: data.targetIp,
      clientIp: auth.clientIp,
      metadata: { targetIp: data.targetIp, newHostname, restartAfter, ...data.details },
    }).catch(() => {});
    return res.json({ success: true, data, rateLimit: getHelpdeskRateLimitStatus(auth.actorName) });
  } catch (err: any) {
    const msg = String(err?.message || 'Failed to rename computer');
    await logHelpdeskErrorAudit({
      actorName: auth.actorName,
      actorRole: auth.actorRole,
      clientIp: auth.clientIp,
      action: 'helpdesk_computer_rename_failed',
      title: `خطا در تغییر نام کامپیوتر ${target.targetIp || 'Unknown'}`,
      title_en: `HelpDesk Computer Rename Failed: ${target.targetIp || 'Unknown'}`,
      targetIp: target.targetIp,
      errorMsg: msg,
      metadata: { newHostname },
    });
    return res.status(/invalid|required|exceed|already/i.test(msg) ? 400 : 502).json({
      success: false,
      error: msg,
      errorFa: msg,
      rateLimit: getHelpdeskRateLimitStatus(auth.actorName),
    });
  }
});

