// Guard for ping & keepalive telemetry
apiRouter.post('/devices/:id/operations', async (req: Request, res: Response, next: NextFunction) => {
  const op = (req.body?.operation || req.body?.action || '').toLowerCase();
  const requiredAction = op.includes('ping') || !op ? 'ping_keepalive' : undefined;
  if (requiredAction) {
    const check = await assertDeviceScopeAccess(req, req.params.id, requiredAction);
    if (!check.allowed) {
      return res.status(check.status || 403).json({ success: false, error: check.error, errorFa: check.errorFa });
    }
  }
  next();
});

// POST /devices/:id/operations - Execute migrated port operations (power, mode, vlan) via resolved SSH backend
apiRouter.post('/devices/:id/operations', async (req: Request, res: Response, next: NextFunction) => {
  const op = String(req.body?.operation || req.body?.action || '').trim().toLowerCase();
  const iface = String(req.body?.interface || req.body?.iface || req.body?.port_id || req.body?.port || req.body?.name || '').trim();
  const params = req.body?.params || {};
  const devId = req.params.id;

  // Actions of Port Modal migrated in Phase 5.2.1 and 5.2.2:
  // Action 3: port-power ('shutdown', 'no_shutdown', 'disable_interface', 'enable_interface')
  // Action 4: port-mode ('mode_trunk', 'mode_access')
  // Action 5: port-vlan ('set_vlan', 'change_vlan', 'assign_vlan')
  // Action 6: port-description ('set_description', 'description')
  // Action 7: port-security ('port_sec_enable', 'port_sec_disable', 'enable_port_security', 'disable_port_security')
  const isPortPower = ['shutdown', 'no_shutdown', 'disable_interface', 'enable_interface'].includes(op);
  const isPortMode = ['mode_trunk', 'mode_access'].includes(op);
  const isPortVlan = ['set_vlan', 'change_vlan', 'assign_vlan'].includes(op);
  const isPortDesc = ['set_description', 'description'].includes(op);
  const isPortSecurity = [
    'port_sec_enable',
    'port_sec_disable',
    'enable_port_security',
    'disable_port_security',
    'port_sec_clear_mac',
    'port_sec_clear_all_macs',
    'port_sec_recover_errdisable',
    'port_sec_update',
    'port_sec_query',
  ].includes(op);

  if (!isPortPower && !isPortMode && !isPortVlan && !isPortDesc && !isPortSecurity) {
    // Other operations (e.g. ping) pass through to next middleware
    return next();
  }

  const isEn = (req.headers['accept-language'] || '').toLowerCase().includes('en');
  try {
    const allDevs = await getAllDevices();
    const device = allDevs.find((d: any) => d.id === devId || d.name === devId);
    if (!device) {
      return res.status(404).json({ success: false, error: 'Device not found', message: isEn ? 'Device not found' : 'دستگاه یافت نشد' });
    }

    // Granular RBAC validation
    const requiredPermission = isPortPower
      ? 'port_power'
      : isPortMode
      ? 'port_mode'
      : isPortVlan
      ? 'port_vlan'
      : isPortDesc
      ? 'port_description'
      : 'port_security';
    const rbacCheck = await assertDeviceScopeAccess(req, devId, requiredPermission);
    if (!rbacCheck.allowed) {
      return res.status(rbacCheck.status || 403).json({
        success: false,
        error: rbacCheck.error || `Access denied for '${requiredPermission}'`,
        errorFa: rbacCheck.errorFa || 'عدم دسترسی به این عملیات طبق پالیسی امنیتی',
      });
    }

    // Read saved ssh_version strictly from stored device record (by device id), NOT from request body or default
    const sshVersion = device.ssh_version || device.sshVersion || (device.platform?.includes('modern') ? 'modern' : 'legacy');
    const backend = resolveSshBackend(sshVersion);

    let result: any = null;
    let durationMs = 0;
    const startT = Date.now();

    // Check if an active interactive persistent SSH session already exists in the pool (e.g. from Port Inspector modal)
    if (deviceSessionPool.hasActiveSession(devId)) {
      console.log(`[PortOperation SessionPool] Executing '${op}' on interface '${iface}' for device ${devId} via persistent active session pool!`);
      const cliCommand = generatePortOperationCli(device.platform || '', op, iface, params);
      const poolExec = await deviceSessionPool.executeCommandOnSession(devId, cliCommand, 25000);
      durationMs = Date.now() - startT;

      if (!poolExec.success) {
        return res.status(400).json({
          success: false,
          error: poolExec.error || 'Operation failed on persistent session',
          message: poolExec.error || 'Operation failed on persistent session',
          cli_command: cliCommand,
          output: poolExec.output || '',
          durationMs,
          isReal: true,
          ssh_version: 'session_pool',
        });
      }

      let parsedPort = null;
      if (op === 'port_sec_query') {
        parsedPort = parseCiscoPortSecurityOutput(iface, poolExec.output || '');
      }

      result = {
        success: true,
        connected: true,
        action: op,
        interface: iface,
        cli_command: cliCommand,
        output: poolExec.output || '',
        port: parsedPort,
        durationMs,
        isReal: true,
        is_live: true,
        ssh_version: 'session_pool',
      };
    } else {
      console.log(`[PortOperation Resolver] Executing '${op}' on interface '${iface}' for device ${devId} using ${backend.version.toUpperCase()} backend (${backend.pythonBin})`);
      result = await executeSshBridgeAction('port-action', {
        device,
        action: op,
        interface: iface,
        params,
      }, backend.version, 25000);
      durationMs = Date.now() - startT;
    }

    if (!result || result.success === false) {
      return res.status(400).json({
        success: false,
        error: result?.error || 'Operation failed on device',
        message: result?.message || result?.error || 'Operation failed on device',
        cli_command: result?.cli_command || '',
        output: result?.output || '',
        durationMs,
        isReal: true,
        ssh_version: result?.ssh_version || backend.version,
        paramiko_version: result?.paramiko_version || backend.paramikoExpected,
      });
    }

    // State reflection in stored device record
    let updatedPort: any = null;
    const ports = Array.isArray(device.ports) ? device.ports : [];
    device.ports = ports;

    let pIdx = ports.findIndex((p: any) => matchPortFlexible(p, iface));
    if (pIdx < 0 && iface) {
      // Auto-provision unseeded port on device
      const cleanName = iface;
      const newPort = {
        port_id: cleanName,
        name: cleanName,
        port: cleanName,
        status: op === 'shutdown' || op === 'disable_interface' ? 'down' : 'up',
        admin_status: op === 'shutdown' || op === 'disable_interface' ? 'disabled' : 'enabled',
        mode: op === 'mode_trunk' ? 'trunk' : 'access',
        vlan: Number(params.vlan || 1),
        allowed_vlans: '1-4094',
        speed: 'auto',
        duplex: 'auto',
        connected_device: '',
        description: String(params.description || '').trim(),
      };
      ports.push(newPort);
      pIdx = ports.length - 1;
    }

    if (pIdx >= 0) {
      const p = { ...device.ports[pIdx] };
      if (isPortPower) {
        if (op === 'shutdown' || op === 'disable_interface') {
          p.admin_status = 'disabled';
          p.status = 'down';
        } else {
          p.admin_status = 'enabled';
          p.status = 'up';
        }
      } else if (isPortMode) {
        p.mode = op === 'mode_trunk' ? 'trunk' : 'access';
      } else if (isPortVlan) {
        p.vlan = Number(params.vlan || 1);
        p.mode = 'access';
      } else if (isPortDesc) {
        p.description = String(params.description || '').trim();
      } else if (isPortSecurity) {
        if (op === 'port_sec_clear_mac') {
          const targetMac = String(params.mac || '').toLowerCase().trim();
          if (targetMac) {
            const filterMac = (val: any) => {
              if (Array.isArray(val)) {
                return val.filter((m: any) => String(typeof m === 'object' ? (m.mac || m.address) : m).toLowerCase().trim() !== targetMac);
              }
              if (typeof val === 'string' && val.toLowerCase().trim() === targetMac) {
                return '';
              }
              return val;
            };
            p.port_security_learned_macs = filterMac(p.port_security_learned_macs || []);
            p.learned_macs = filterMac(p.learned_macs || []);
            p.sticky_macs = filterMac(p.sticky_macs || []);
            p.dynamic_macs = filterMac(p.dynamic_macs || []);
            if (String(p.port_security_configured_mac || '').toLowerCase().trim() === targetMac) {
              p.port_security_configured_mac = '';
            }
          }
        } else if (op === 'port_sec_clear_all_macs') {
          p.port_security_learned_macs = [];
          p.learned_macs = [];
          p.sticky_macs = [];
          p.dynamic_macs = [];
          if (p.port_security_mode === 'sticky') {
            p.port_security_configured_mac = '';
          }
        } else if (op === 'port_sec_recover_errdisable') {
          p.status = 'up';
          p.admin_status = 'enabled';
          p.port_security_status = 'secure-up';
        } else if (op === 'port_sec_query') {
          console.log(`[PortSecurity Sync] Device ${devId} ${iface} Raw Output:\n`, result?.output || '(empty)');
          if (result?.port) {
            const freshSec = result.port;
            p.port_security_enabled = freshSec.port_security_enabled ?? p.port_security_enabled;
            p.port_security_mode = freshSec.port_security_mode ?? p.port_security_mode;
            p.port_security_max_mac = freshSec.port_security_max_mac ?? p.port_security_max_mac;
            p.port_security_violation = freshSec.port_security_violation ?? p.port_security_violation;
            p.port_security_configured_mac = freshSec.port_security_configured_mac ?? p.port_security_configured_mac;
            p.port_security_sticky_mac = freshSec.port_security_sticky_mac ?? p.port_security_sticky_mac;
            p.port_security_learned_macs = Array.isArray(freshSec.port_security_learned_macs)
              ? freshSec.port_security_learned_macs
              : p.port_security_learned_macs;
            p.learned_macs = Array.isArray(freshSec.learned_macs) ? freshSec.learned_macs : p.learned_macs;
            p.connected_mac = freshSec.connected_mac ?? p.connected_mac;
            p.status = freshSec.status ?? p.status;
            if (freshSec.vlan) p.vlan = freshSec.vlan;
            console.log(`[PortSecurity Sync] Parsed MACs:`, p.port_security_learned_macs || []);
          }
        } else if (op === 'port_sec_update') {
          p.port_security_enabled = Boolean(params.enabled);
          p.port_security_status = p.port_security_enabled ? (p.status === 'up' ? 'secure-up' : 'secure-down') : 'disabled';
          if (params.mode) p.port_security_mode = params.mode;
          if (params.max_mac) p.port_security_max_mac = Number(params.max_mac);
          if (params.violation) p.port_security_violation = String(params.violation);
          if (params.configured_mac !== undefined) p.port_security_configured_mac = String(params.configured_mac).trim();
          if (params.vlan !== undefined && Number(params.vlan) > 0) {
            p.vlan = Number(params.vlan);
          }
          p.mode = 'access';
        } else if (op.includes('enable')) {
          p.port_security_enabled = true;
          p.port_security_status = p.status === 'up' ? 'secure-up' : 'secure-down';
          if (params.max_mac) p.port_security_max_mac = Number(params.max_mac);
          if (params.violation) p.port_security_violation = String(params.violation);
          if (params.mode) p.port_security_mode = params.mode;
          p.mode = 'access';
        } else {
          p.port_security_enabled = false;
          p.port_security_status = 'disabled';
        }
      }
      device.ports[pIdx] = p;
      device.has_unsaved_changes = true;
      updatedPort = p;
      await updateDevice(device.id, { ports: device.ports, has_unsaved_changes: true });
    }

    if (req.headers['x-client-audit-logged'] !== 'true' && op !== 'port_sec_query' && op !== 'query') {
      try {
        const opUser = getReqOperator(req);
        const locationStr = [device.building, device.floor, device.unit, device.rack ? `Rack ${device.rack}` : ''].filter(Boolean).join(' > ');
        await addDeviceCommandLog({
          deviceId: device.id,
          deviceName: device.name,
          deviceIp: device.ip,
          deviceVendor: (device.model || '').toLowerCase().includes('mikrotik') ? 'mikrotik' : 'cisco',
          deviceModel: device.model,
          deviceLocation: locationStr || undefined,
          channel: 'port_context_menu',
          command: result.cli_command || `operation: ${op} on ${iface || 'device'}`,
          riskLevel: op.includes('shutdown') ? 'medium' : 'low',
          status: 'success',
          outputSummary: `Executed ${op} on ${iface || device.name}`,
          notes: `Hardware operation applied`,
          actor: {
            username: opUser.username,
            role: opUser.role,
            ipAddress: opUser.ip,
          },
        });
      } catch (auditErr) {
        console.warn('[Audit] Could not save operation command log:', auditErr);
      }
    }

    return res.json({
      success: true,
      cli_command: result.cli_command || '',
      output: result.output || '',
      durationMs,
      port: updatedPort,
      isReal: true,
      ssh_version: backend.version,
      paramiko_version: result.paramiko_version || backend.paramikoExpected,
    });
  } catch (err: any) {
    return res.status(500).json({
      success: false,
      error: err.message,
      message: err.message,
    });
  }
});

// Guard for terminal CLI execution
