// Remote Servers Fleet & Automation Tags Endpoints
// -------------------------------------------------------------

/**
 * Infers the granular server action key from the incoming Express Request.
 */
function inferServerActionKey(req: Request, serverId: string): string | null {
  const method = (req.method || 'GET').toUpperCase();
  const rawUrl = req.originalUrl || req.url || '';
  const urlPath = rawUrl.split('?')[0].replace(/\/+$/, '');

  // 1. File Explorer & SFTP Browser (/fs/*)
  if (urlPath.includes('/fs/') || urlPath.endsWith('/fs')) {
    return 'file_explorer';
  }

  // 2. Power Control (Restart, Shutdown, Poweroff, Reboot)
  if (
    urlPath.endsWith('/restart') ||
    urlPath.endsWith('/poweroff') ||
    urlPath.endsWith('/shutdown') ||
    urlPath.endsWith('/reboot')
  ) {
    return 'power_control';
  }

  // 3. Web Servers (Nginx & Apache)
  if (urlPath.includes('/nginx') || urlPath.includes('/apache')) {
    return 'web_management';
  }

  // 4. Databases (PostgreSQL, MySQL, MariaDB)
  if (urlPath.includes('/postgres') || urlPath.includes('/mysql') || urlPath.includes('/mariadb')) {
    return 'database_management';
  }

  // 5. Delete Server from Fleet (DELETE /api/remote-servers/:id)
  if (method === 'DELETE' && (urlPath.endsWith(`/remote-servers/${serverId}`) || urlPath.endsWith(`/${serverId}`))) {
    return 'delete_server';
  }

  // 6. Edit Server Properties (PUT or PATCH /api/remote-servers/:id)
  if ((method === 'PUT' || method === 'PATCH') && (urlPath.endsWith(`/remote-servers/${serverId}`) || urlPath.endsWith(`/${serverId}`))) {
    return 'edit_properties';
  }

  // 7. System telemetry, services, cron jobs, processes, storage/LVM, logs, network inspection
  if (
    urlPath.includes('/cron-jobs') ||
    urlPath.includes('/services') ||
    urlPath.includes('/service-action') ||
    urlPath.includes('/service-watchdogs') ||
    urlPath.includes('/processes') ||
    urlPath.includes('/process-action') ||
    urlPath.includes('/metrics') ||
    urlPath.includes('/monitor') ||
    urlPath.includes('/storage') ||
    urlPath.includes('/lvm') ||
    urlPath.includes('/mount-action') ||
    urlPath.includes('/unmount-action') ||
    urlPath.includes('/disk-format-mount') ||
    urlPath.includes('/block-devices') ||
    urlPath.includes('/network') ||
    urlPath.includes('/interface-state') ||
    urlPath.includes('/restart-network') ||
    urlPath.includes('/logs') ||
    urlPath.includes('/syslog') ||
    urlPath.includes('/live-overview') ||
    urlPath.includes('/sysconfig') ||
    urlPath.includes('/tcp-wrappers') ||
    urlPath.includes('/dns') ||
    urlPath.includes('/fail2ban') ||
    urlPath.includes('/firewall') ||
    urlPath.includes('/proxy-action') ||
    urlPath.includes('/packages') ||
    urlPath.includes('/users') ||
    urlPath.includes('/groups') ||
    urlPath.includes('/send-message') ||
    urlPath.includes('/logout-user') ||
    urlPath.includes('/time') ||
    urlPath.includes('/hosts') ||
    urlPath.includes('/hostname') ||
    urlPath.includes('/ssh-config') ||
    urlPath.includes('/ssh-port')
  ) {
    return 'server_management';
  }

  // 8. Server Export & Import
  if (urlPath.includes('/export') || urlPath.endsWith('/export')) {
    return 'export_servers';
  }
  if (urlPath.includes('/import') || urlPath.endsWith('/import')) {
    return 'import_servers';
  }

  return null;
}

/**
 * Authoritative security guard for remote server endpoints.
 * Resolves token-authenticated user policy, verifies if the server is in user's PostgreSQL scope,
 * and validates whether the requested server action (ServerActionKey) evaluates to allow / require_approval / deny.
 */
async function assertServerScopeAccess(
  req: Request,
  serverId: string,
  requiredAction?: string
): Promise<{
  allowed: boolean;
  server: any | null;
  error?: string;
  errorFa?: string;
  status?: number;
  code?: string;
  gatePayload?: any;
  approvedTicketId?: string;
}> {
  const cleanId = (serverId || '').trim();
  if (!cleanId) {
    return { allowed: false, server: null, error: 'Server ID is required', status: 400 };
  }

  const server = await getRemoteServerById(cleanId);
  if (!server) {
    return { allowed: false, server: null, error: 'Server not found', status: 404 };
  }

  const context = await resolveRequestContextPolicy(req);
  const { effectivePolicy, isSuperAdmin, allowedServerIds } = context;

  // If user is super admin, full unconstrained access is granted
  if (isSuperAdmin) {
    return { allowed: true, server };
  }

  // If no effective policy is resolved (unauthenticated / standalone mode)
  if (!effectivePolicy) {
    return { allowed: true, server };
  }

  // 1. Check explicit policy permission to view servers
  if (effectivePolicy.canViewServers === false) {
    return {
      allowed: false,
      server,
      error: 'Access denied: Your account policy prohibits access to Remote Servers & Automation Fleet.',
      status: 403,
    };
  }

  // 2. Check server ID in allowedServerIds calculated from PostgreSQL device groups
  if (allowedServerIds !== null) {
    const allowedSet = new Set(allowedServerIds.map((id) => (id || '').trim().toLowerCase()));
    const sid = (server.id || '').trim().toLowerCase();
    const sname = (server.name || '').trim().toLowerCase();
    const shost = (server.hostname || '').trim().toLowerCase();

    if (!allowedSet.has(sid) && !allowedSet.has(sname) && !allowedSet.has(shost)) {
      return {
        allowed: false,
        server,
        error: 'Access denied: You do not have permission to view or manage this server based on your assigned Device Groups in PostgreSQL.',
        status: 403,
      };
    }
  }

  // 3. Granular Server Action Check (Tri-State: allow / require_approval / deny)
  const action = requiredAction || inferServerActionKey(req, cleanId);
  if (action) {
    const decision = evaluateServerActionDecision(effectivePolicy, server.id, action);
    if (decision === 'deny') {
      return {
        allowed: false,
        server,
        code: 'RBAC_DENIED',
        error: `Access denied: You do not have permission to execute '${action}' on this server under your RBAC policy.`,
        errorFa: `عدم دسترسی: شما طبق پالیسی امنیتی خود مجوز انجام عملیات «${action}» روی این سرور را ندارید.`,
        status: 403,
      };
    }

    if (decision === 'require_approval' && isMutatingServerRequest(req, action)) {
      const actor = buildApprovalActor(req, context);
      const meta = resolveActionMeta(action);
      const rawActionParams: Record<string, any> | null =
        req.body && typeof req.body === 'object' ? { ...req.body } : {};
      const signedExec = buildSignedHttpExecutionPayload({
        method: req.method || 'POST',
        originalUrl: req.originalUrl || req.url || '',
        body: req.body,
        entityType: 'server',
        entityId: server.id,
        actionKey: action,
        requesterUsername: actor.username,
      });
      if (signedExec && rawActionParams) {
        rawActionParams._httpExecution = signedExec;
      }
      const gateRes = await evaluateApprovalGateForRequest({
        actor,
        effectivePolicy,
        entityType: 'server',
        entityId: server.id,
        entityName: server.name || server.ip || server.id,
        actionKey: action,
        requestedAction: `${meta.labelEn} (${server.name || server.ip || server.id})`,
        commandPreview: buildSafeCommandPreview(req, { server, action }),
        actionParams:
          rawActionParams && Object.keys(rawActionParams).length > 0 ? rawActionParams : null,
        providedApprovalId: extractProvidedApprovalId(req),
      });

      if (!gateRes.allowed) {
        (req as any).__pendingApprovalGatePayload = gateRes.gatePayload;
        return {
          allowed: false,
          server,
          code: 'APPROVAL_REQUIRED',
          gatePayload: gateRes.gatePayload,
          error: gateRes.gatePayload.error,
          errorFa: gateRes.gatePayload.errorFa,
          status: 403,
        };
      }

      delete (req as any).__pendingApprovalGatePayload;
      (req as any).__approvedTicketCtx = {
        actor,
        ticketId: gateRes.approvedTicket.id,
        grantId: gateRes.activeGrant?.id || null,
        actionKey: action,
        executionNote: `Executed server action '${action}' on ${server.name || server.id} via JIT approval ${gateRes.approvedTicket.id}`,
      };
      return {
        allowed: true,
        server,
        approvedTicketId: gateRes.approvedTicket.id,
      };
    }
  }

  delete (req as any).__pendingApprovalGatePayload;
  return { allowed: true, server };
}

// Intercept all routes under /remote-servers/:id with authoritative PostgreSQL device-group RBAC check
apiRouter.param('id', async (req: Request, res: Response, next: NextFunction, id: string) => {
  const originalUrl = req.originalUrl || req.url || '';
  if (originalUrl.includes('/remote-servers/') && id !== 'tags' && id !== 'bulk-power') {
    try {
      const check = await assertServerScopeAccess(req, id);
      if (!check.allowed) {
        return res.status(check.status || 403).json({ success: false, error: check.error });
      }
      (req as any).scopedServer = check.server;
    } catch (err: any) {
      return res.status(500).json({ success: false, error: err.message });
    }
  }
  next();
});

// GET /api/remote-servers - List all servers with optional query filters (PostgreSQL Scope Protected)
apiRouter.get('/remote-servers', async (req: Request, res: Response) => {
  try {
    const { effectivePolicy, isSuperAdmin, allowedServerIds } = await resolveRequestContextPolicy(req);

    // If explicit policy denies viewing servers
    if (!isSuperAdmin && effectivePolicy && effectivePolicy.canViewServers === false) {
      return res.json({
        success: true,
        count: 0,
        servers: [],
        allowedServerIds: [],
        targetScope: effectivePolicy?.targetScope || 'groups',
      });
    }

    let servers = await getAllRemoteServers();

    if (!isSuperAdmin && effectivePolicy && allowedServerIds !== null) {
      const allowedSet = new Set(allowedServerIds.map((id) => (id || '').trim().toLowerCase()));
      servers = servers.filter((s) => {
        const sid = (s.id || '').trim().toLowerCase();
        const sname = (s.name || '').trim().toLowerCase();
        const shost = (s.hostname || '').trim().toLowerCase();
        return allowedSet.has(sid) || allowedSet.has(sname) || allowedSet.has(shost);
      });
    }

    const { os, env, category, tag, search } = req.query;

    if (typeof os === 'string' && os) {
      servers = servers.filter((s) => s.os_type.toLowerCase() === os.toLowerCase());
    }
    if (typeof env === 'string' && env && env !== 'all') {
      servers = servers.filter((s) => s.environment.toLowerCase() === env.toLowerCase());
    }
    if (typeof category === 'string' && category && category !== 'all') {
      servers = servers.filter((s) => s.category.toLowerCase() === category.toLowerCase());
    }
    if (typeof tag === 'string' && tag) {
      servers = servers.filter((s) => Array.isArray(s.tags) && s.tags.includes(tag));
    }
    if (typeof search === 'string' && search.trim()) {
      const q = search.trim().toLowerCase();
      servers = servers.filter(
        (s) =>
          s.name.toLowerCase().includes(q) ||
          (s.hostname && s.hostname.toLowerCase().includes(q)) ||
          s.ip.includes(q) ||
          (s.os_distro && s.os_distro.toLowerCase().includes(q)) ||
          (s.role && s.role.toLowerCase().includes(q)) ||
          (Array.isArray(s.tags) && s.tags.some((t) => t.toLowerCase().includes(q)))
      );
    }

    const sanitizedServers = servers.map(sanitizeRemoteServerForClient);
    res.json({
      success: true,
      count: sanitizedServers.length,
      servers: sanitizedServers,
      allowedServerIds: isSuperAdmin ? null : allowedServerIds,
      targetScope: isSuperAdmin ? 'all' : (effectivePolicy?.targetScope || 'groups'),
    });
  } catch (err: any) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/remote-servers/tags - Distinct tags with count (Scoped to user permitted servers)
apiRouter.get('/remote-servers/tags', async (req: Request, res: Response) => {
  try {
    const { effectivePolicy, isSuperAdmin, allowedServerIds } = await resolveRequestContextPolicy(req);
    let servers = await getAllRemoteServers();

    if (!isSuperAdmin && effectivePolicy && allowedServerIds !== null) {
      const allowedSet = new Set(allowedServerIds.map((id) => (id || '').trim().toLowerCase()));
      servers = servers.filter((s) => {
        const sid = (s.id || '').trim().toLowerCase();
        const sname = (s.name || '').trim().toLowerCase();
        const shost = (s.hostname || '').trim().toLowerCase();
        return allowedSet.has(sid) || allowedSet.has(sname) || allowedSet.has(shost);
      });
    }

    const tagCounts: Record<string, number> = {};
    servers.forEach((s) => {
      (s.tags || []).forEach((t) => {
        tagCounts[t] = (tagCounts[t] || 0) + 1;
      });
    });

    const summary = Object.entries(tagCounts).map(([tag, count]) => ({ tag, count }));
    res.json({ success: true, tags: summary });
  } catch (err: any) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// POST /api/remote-servers/export - Export single or batch remote servers with strict Granular Multi-Vendor RBAC enforcement
apiRouter.post('/remote-servers/export', async (req: Request, res: Response) => {
  try {
    const { effectivePolicy, isSuperAdmin, allowedServerIds, user } = await resolveRequestContextPolicy(req);
    const {
      serverIds,
      format = 'json',
      includeHardware = true,
      includeServices = true,
      includeTags = true,
      includeUptime = true,
    } = req.body;

    if (!isSuperAdmin && effectivePolicy && effectivePolicy.canViewServers === false) {
      return res.status(403).json({
        success: false,
        error: 'Access denied: Your account policy prohibits access to Remote Servers & Automation Fleet.',
        errorFa: 'عدم دسترسی: پالیسی حساب کاربری شما اجازه دسترسی به سرورهای ریموت را نمی‌دهد.',
      });
    }

    let allServers = await getAllRemoteServers();
    if (!isSuperAdmin && effectivePolicy && allowedServerIds !== null) {
      const allowedSet = new Set(allowedServerIds.map((id: string) => (id || '').trim().toLowerCase()));
      allServers = allServers.filter((s: any) => {
        const sid = (s.id || '').trim().toLowerCase();
        const sname = (s.name || '').trim().toLowerCase();
        const shost = (s.hostname || '').trim().toLowerCase();
        return allowedSet.has(sid) || allowedSet.has(sname) || allowedSet.has(shost);
      });
    }

    let targetServers = allServers;
    if (Array.isArray(serverIds) && serverIds.length > 0) {
      const requestedSet = new Set(serverIds.map((id: string) => (id || '').trim().toLowerCase()));
      targetServers = allServers.filter((s: any) => requestedSet.has((s.id || '').trim().toLowerCase()));
    }

    if (targetServers.length === 0) {
      return res.status(404).json({
        success: false,
        error: 'No matching servers found to export.',
        errorFa: 'هیچ سروری برای استخراج یافت نشد.',
      });
    }

    // Granular Tri-State RBAC Check: Ensure user is authorized to export each server
    const context = await resolveRequestContextPolicy(req);
    const unauthorized = targetServers.filter(
      (s: any) => !isSuperAdmin && evaluateServerActionDecision(effectivePolicy, s.id, 'export_servers') === 'deny'
    );

    if (unauthorized.length > 0) {
      return res.status(403).json({
        success: false,
        error: `Access denied: You do not have RBAC permission to export ${unauthorized.length} of the requested servers.`,
        errorFa: `عدم دسترسی: شما طبق پالیسی امنیتی خود مجوز استخراج (Export) تعداد ${unauthorized.length} از سرورهای درخواستی را ندارید.`,
        unauthorizedIds: unauthorized.map((s: any) => s.id),
      });
    }

    const approvalGatedServers = isSuperAdmin
      ? []
      : targetServers.filter(
          (s: any) => evaluateServerActionDecision(effectivePolicy, s.id, 'export_servers') === 'require_approval'
        );

    let exportApprovedTicket: { actor: ApprovalActor; ticketId: string } | null = null;
    if (approvalGatedServers.length > 0 && effectivePolicy) {
      const actor = buildApprovalActor(req, context);
      const primarySrv = approvalGatedServers[0];
      const gateRes = await evaluateApprovalGateForRequest({
        actor,
        effectivePolicy,
        entityType: 'server',
        entityId: approvalGatedServers.length === 1 ? primarySrv.id : 'bulk',
        entityName:
          approvalGatedServers.length === 1
            ? primarySrv.name || primarySrv.ip || primarySrv.id
            : `${approvalGatedServers.length} Remote Servers`,
        actionKey: 'export_servers',
        requestedAction: `Export ${targetServers.length} Remote Server(s)`,
        commandPreview: buildSafeCommandPreview(req, { action: 'export_servers', extraSummary: `format=${format}, count=${targetServers.length}` }),
        actionParams: { serverIds: targetServers.map((s: any) => s.id), format },
        providedApprovalId: extractProvidedApprovalId(req),
      });
      if (!gateRes.allowed) {
        res.setHeader('X-Approval-Required', 'true');
        return res.status(403).json({ success: false, ...gateRes.gatePayload });
      }
      exportApprovedTicket = { actor, ticketId: gateRes.approvedTicket.id };
      (req as any).__approvedTicketCtx = {
        actor,
        ticketId: gateRes.approvedTicket.id,
        executionNote: `Executed export_servers for ${targetServers.length} server(s) via ${gateRes.approvedTicket.id}`,
      };
    }

    // Sanitize credentials: Zero plaintext secrets leak (Rule 14)
    const exportData = targetServers.map((srv: any) => {
      const s = { ...srv };
      delete s.win_password;
      delete s.ssh_password;
      delete s.postgres_password;
      delete s.mysql_password;
      delete s.ssh_key;
      delete s.private_key;
      delete s.sudo_password;
      delete s.root_password;

      if (!includeHardware) {
        delete s.cpu_cores;
        delete s.ram_gb;
        delete s.disk_gb;
      }
      if (!includeServices) {
        delete s.has_nginx;
        delete s.has_apache;
        delete s.has_postgresql;
        delete s.has_mysql;
        delete s.installed_web_servers;
        delete s.installed_databases;
        delete s.active_services_count;
      }
      if (!includeTags) {
        delete s.tags;
        delete s.category;
      }
      if (!includeUptime) {
        delete s.uptime_seconds;
        delete s.uptime_formatted;
      }
      return s;
    });

    if (format === 'csv') {
      const csvHeader = [
        'ID',
        'Name',
        'Hostname',
        'OS Type',
        'OS Distro',
        'Environment',
        'Category',
        'IP Address',
        'SSH Port',
        'SSH User',
        'Status',
        'vCPU Cores',
        'RAM (GB)',
        'Disk (GB)',
        'Web Servers',
        'Databases',
        'Automation Tags',
        'Uptime',
        'Created At',
      ].join(',');

      const csvRows = exportData.map((s: any) => {
        const webSvcs = [s.has_nginx ? 'Nginx' : '', s.has_apache ? 'Apache' : ''].filter(Boolean).join('; ');
        const dbSvcs = [s.has_postgresql ? 'PostgreSQL' : '', s.has_mysql ? 'MySQL' : ''].filter(Boolean).join('; ');
        const tagsStr = Array.isArray(s.tags) ? s.tags.join('; ') : '';

        return [
          `"${s.id || ''}"`,
          `"${(s.name || '').replace(/"/g, '""')}"`,
          `"${(s.hostname || '').replace(/"/g, '""')}"`,
          `"${s.os_type || ''}"`,
          `"${(s.os_distro || '').replace(/"/g, '""')}"`,
          `"${s.environment || ''}"`,
          `"${s.category || ''}"`,
          `"${s.ip || ''}"`,
          `"${s.port || 22}"`,
          `"${s.username || ''}"`,
          `"${s.is_online ? 'Online' : 'Offline'}"`,
          `"${s.cpu_cores ?? ''}"`,
          `"${s.ram_gb ?? ''}"`,
          `"${s.disk_gb ?? ''}"`,
          `"${webSvcs}"`,
          `"${dbSvcs}"`,
          `"${tagsStr.replace(/"/g, '""')}"`,
          `"${(s.uptime_formatted || '').replace(/"/g, '""')}"`,
          `"${s.created_at || ''}"`,
        ].join(',');
      });

      const csvContent = '\uFEFF' + [csvHeader, ...csvRows].join('\r\n');
      res.setHeader('Content-Type', 'text/csv; charset=utf-8');
      res.setHeader('Content-Disposition', `attachment; filename="remote_servers_export_${Date.now()}.csv"`);
      return res.status(200).send(csvContent);
    }

    res.json({
      success: true,
      timestamp: new Date().toISOString(),
      count: exportData.length,
      servers: exportData,
    });
  } catch (err: any) {
    res.status(500).json({ success: false, error: err.message, errorFa: 'خطا در استخراج اطلاعات سرورها' });
  }
});

// Helper function to parse CSV string into objects
function parseServersFromCsv(csvText: string): any[] {
  const clean = csvText.replace(/^\uFEFF/, '').trim();
  if (!clean) return [];
  const lines = clean.split(/\r?\n/).filter((l) => l.trim().length > 0);
  if (lines.length < 2) return [];

  const parseLine = (line: string): string[] => {
    const result: string[] = [];
    let cur = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        if (inQuotes && line[i + 1] === '"') {
          cur += '"';
          i++;
        } else {
          inQuotes = !inQuotes;
        }
      } else if (char === ',' && !inQuotes) {
        result.push(cur.trim());
        cur = '';
      } else {
        cur += char;
      }
    }
    result.push(cur.trim());
    return result;
  };

  const headers = parseLine(lines[0]).map((h) => h.toLowerCase().replace(/[^a-z0-9]/g, ''));
  const rows: any[] = [];

  for (let i = 1; i < lines.length; i++) {
    const values = parseLine(lines[i]);
    const obj: Record<string, any> = {};
    headers.forEach((header, idx) => {
      obj[header] = values[idx] ?? '';
    });

    const name = obj.name || obj.servername || obj.hostname || obj.id || `Imported Server ${i}`;
    const ip = obj.ip || obj.ipaddress || obj.host || obj.sshhost || '';
    if (!ip) continue; // Skip lines without valid IP

    const osRaw = (obj.ostype || obj.os || '').toLowerCase();
    const osType = osRaw.includes('win') ? 'windows' : 'linux';

    const tagsRaw = obj.automationtags || obj.tags || '';
    const tags = tagsRaw ? tagsRaw.split(/[;,]/).map((t: string) => t.trim()).filter(Boolean) : [];

    const webSvcs = (obj.webservers || '').toLowerCase();
    const dbSvcs = (obj.databases || '').toLowerCase();

    rows.push({
      id: obj.id || undefined,
      name,
      hostname: obj.hostname || '',
      ip,
      os_type: osType,
      os_distro: obj.osdistro || obj.distro || (osType === 'windows' ? 'Windows Server 2022' : 'Ubuntu 24.04 LTS'),
      environment: obj.environment || 'Production',
      category: obj.category || 'Application Server',
      role: obj.role || 'General Server',
      tags,
      ssh_port: Number(obj.sshport || obj.port) || 22,
      ssh_username: obj.sshuser || obj.username || (osType === 'windows' ? 'Administrator' : 'root'),
      cpu_cores: obj.vcpus || obj.vcpuscores || obj.cpucores ? Number(obj.vcpus || obj.vcpuscores || obj.cpucores) : undefined,
      ram_gb: obj.ram || obj.ramgb ? Number(obj.ram || obj.ramgb) : undefined,
      disk_gb: obj.disk || obj.diskgb ? Number(obj.disk || obj.diskgb) : undefined,
      has_nginx: webSvcs.includes('nginx'),
      has_apache: webSvcs.includes('apache'),
      has_postgresql: dbSvcs.includes('postgres'),
      has_mysql: dbSvcs.includes('mysql'),
      notes: obj.notes || '',
    });
  }

  return rows;
}

// POST /api/remote-servers/import - Import single or batch remote servers with strict Granular Multi-Vendor RBAC enforcement
apiRouter.post('/remote-servers/import', async (req: Request, res: Response) => {
  try {
    const { effectivePolicy, isSuperAdmin, user } = await resolveRequestContextPolicy(req);

    // Strict Tri-State RBAC Enforcement: check if user is authorized to import servers
    if (!isSuperAdmin && effectivePolicy) {
      if (effectivePolicy.canViewServers === false) {
        return res.status(403).json({
          success: false,
          error: 'Access denied: Your account policy prohibits access to Remote Servers & Automation Fleet.',
          errorFa: 'عدم دسترسی: پالیسی حساب کاربری شما اجازه دسترسی به سرورهای ریموت را نمی‌دهد.',
        });
      }

      const importDecision =
        effectivePolicy.canImportServers === false
          ? 'deny'
          : evaluateServerActionDecision(effectivePolicy, '__global_import__', 'import_servers');

      if (importDecision === 'deny' && effectivePolicy.canImportServers !== true) {
        return res.status(403).json({
          success: false,
          error: 'Access denied: You do not have RBAC permission to import servers into the fleet.',
          errorFa: 'عدم دسترسی: شما طبق پالیسی امنیتی خود مجوز ورود و بارگذاری (Import) سرورها را ندارید.',
        });
      }

      if (importDecision === 'require_approval') {
        const actor = buildApprovalActor(req, { user, effectivePolicy, isSuperAdmin });
        const gateRes = await evaluateApprovalGateForRequest({
          actor,
          effectivePolicy,
          entityType: 'server',
          entityId: 'bulk',
          entityName: 'Remote Servers Import Package',
          actionKey: 'import_servers',
          requestedAction: 'Import Remote Servers into Fleet',
          commandPreview: buildSafeCommandPreview(req, { action: 'import_servers' }),
          providedApprovalId: extractProvidedApprovalId(req),
        });
        if (!gateRes.allowed) {
          res.setHeader('X-Approval-Required', 'true');
          return res.status(403).json({ success: false, ...gateRes.gatePayload });
        }
        (req as any).__approvedTicketCtx = {
          actor,
          ticketId: gateRes.approvedTicket.id,
          executionNote: `Executed import_servers via JIT approval ${gateRes.approvedTicket.id}`,
        };
      }
    }

    const { conflictMode = 'skip', servers: rawServers, csvData } = req.body;

    let candidateServers: any[] = [];

    if (typeof csvData === 'string' && csvData.trim()) {
      candidateServers = parseServersFromCsv(csvData);
    } else if (Array.isArray(rawServers)) {
      candidateServers = rawServers;
    } else if (Array.isArray(req.body)) {
      candidateServers = req.body;
    } else if (req.body && typeof req.body === 'object' && req.body.ip) {
      candidateServers = [req.body];
    }

    if (candidateServers.length === 0) {
      return res.status(400).json({
        success: false,
        error: 'No valid server records found in payload to import.',
        errorFa: 'هیچ رکورد سرور معتبری برای ورود در داده‌های ارسالی یافت نشد.',
      });
    }

    // Load existing servers to detect conflicts
    const allExisting = await getAllRemoteServers();
    const existingById = new Map<string, any>();
    const existingByIp = new Map<string, any>();
    const existingByHost = new Map<string, any>();

    allExisting.forEach((s) => {
      if (s.id) existingById.set(s.id.toLowerCase(), s);
      if (s.ip) existingByIp.set(s.ip.toLowerCase(), s);
      if (s.hostname) existingByHost.set(s.hostname.toLowerCase(), s);
    });

    const createdList: any[] = [];
    const updatedList: any[] = [];
    const skippedList: any[] = [];

    for (const item of candidateServers) {
      const ip = (item.ip || item.ip_address || item['IP Address'] || '').trim();
      const name = (item.name || item.hostname || item['Name'] || item['Server Name'] || 'Imported Server').trim();

      if (!ip) {
        skippedList.push({ name, ip: 'N/A', reason: 'Missing IP address' });
        continue;
      }

      const hostname = (item.hostname || item['Hostname'] || '').trim();
      const existing =
        (item.id && existingById.get(item.id.toLowerCase())) ||
        existingByIp.get(ip.toLowerCase()) ||
        (hostname ? existingByHost.get(hostname.toLowerCase()) : null);

      if (existing) {
        if (conflictMode === 'skip') {
          skippedList.push({
            id: existing.id,
            name: existing.name || name,
            ip,
            reason: 'Server already exists in inventory (Skipped due to duplicate IP/hostname)',
          });
          continue;
        } else if (conflictMode === 'overwrite') {
          const merged: Partial<RemoteServer> = {
            name: name || existing.name,
            hostname: hostname || existing.hostname,
            ip,
            os_type: item.os_type || existing.os_type || 'linux',
            os_distro: item.os_distro || existing.os_distro,
            environment: item.environment || existing.environment || 'Production',
            category: item.category || existing.category || 'Application Server',
            role: item.role || existing.role || 'General Server',
            tags: Array.isArray(item.tags) && item.tags.length > 0 ? item.tags : existing.tags,
            ssh_port: Number(item.ssh_port) || existing.ssh_port || 22,
            ssh_username: item.ssh_username || existing.ssh_username,
            cpu_cores: Number(item.cpu_cores) || existing.cpu_cores,
            ram_gb: Number(item.ram_gb) || existing.ram_gb,
            disk_gb: Number(item.disk_gb) || existing.disk_gb,
            has_nginx: item.has_nginx !== undefined ? Boolean(item.has_nginx) : existing.has_nginx,
            has_apache: item.has_apache !== undefined ? Boolean(item.has_apache) : existing.has_apache,
            has_postgresql: item.has_postgresql !== undefined ? Boolean(item.has_postgresql) : existing.has_postgresql,
            has_mysql: item.has_mysql !== undefined ? Boolean(item.has_mysql) : existing.has_mysql,
            notes: item.notes || existing.notes,
          };
          const updated = await updateRemoteServer(existing.id, merged);
          if (updated) {
            updatedList.push(sanitizeRemoteServerForClient(updated));
          } else {
            updatedList.push(sanitizeRemoteServerForClient({ ...existing, ...merged }));
          }
          continue;
        }
      }

      // Create new server
      const osType = (item.os_type || '').toLowerCase().includes('win') ? 'windows' : 'linux';
      const newPayload: Partial<RemoteServer> = {
        name,
        hostname,
        ip,
        os_type: osType,
        os_distro: item.os_distro || (osType === 'windows' ? 'Windows Server 2022' : 'Ubuntu 24.04 LTS'),
        environment: item.environment || 'Production',
        category: item.category || 'Application Server',
        role: item.role || 'General Server',
        tags: Array.isArray(item.tags) ? item.tags : [],
        ssh_port: Number(item.ssh_port) || 22,
        ssh_username: item.ssh_username || (osType === 'windows' ? 'Administrator' : 'root'),
        win_protocol: item.win_protocol || 'rdp',
        win_port: Number(item.win_port) || 3389,
        win_username: item.win_username || 'Administrator',
        cpu_cores: Number(item.cpu_cores) > 0 ? Number(item.cpu_cores) : undefined,
        ram_gb: Number(item.ram_gb) > 0 ? Number(item.ram_gb) : undefined,
        disk_gb: Number(item.disk_gb) > 0 ? Number(item.disk_gb) : undefined,
        has_nginx: Boolean(item.has_nginx),
        has_apache: Boolean(item.has_apache),
        has_postgresql: Boolean(item.has_postgresql),
        has_mysql: Boolean(item.has_mysql),
        notes: item.notes || '',
      };

      const created = await createRemoteServer(newPayload);
      createdList.push(sanitizeRemoteServerForClient(created));
      // Add to local lookups to avoid duplicate within same batch
      if (created.id) existingById.set(created.id.toLowerCase(), created);
      existingByIp.set(ip.toLowerCase(), created);
      if (hostname) existingByHost.set(hostname.toLowerCase(), created);
    }

    // Audit Log for the batch operation
    await addAuditLog({
      userName: (req.headers['x-user-name'] as string) || user?.username || 'Admin',
      action: 'Import Remote Servers',
      category: 'device',
      target: `Fleet Import (${createdList.length} new, ${updatedList.length} updated, ${skippedList.length} skipped)`,
      status: 'success',
      details: `Processed import of ${candidateServers.length} candidate servers (Conflict Mode: ${conflictMode}).`,
      ipAddress: getClientIp(req),
      userAgent: req.headers['user-agent'] || 'WebUI',
    });

    res.json({
      success: true,
      message: `Import completed: ${createdList.length} created, ${updatedList.length} updated, ${skippedList.length} skipped.`,
      messageFa: `عملیات ورود با موفقیت انجام شد: ${createdList.length} سرور جدید افزوده شد، ${updatedList.length} سرور به‌روزرسانی شد و ${skippedList.length} مورد نادیده گرفته شد.`,
      totalProcessed: candidateServers.length,
      importedCount: createdList.length,
      updatedCount: updatedList.length,
      skippedCount: skippedList.length,
      skipped: skippedList,
      servers: [...createdList, ...updatedList],
    });
  } catch (err: any) {
    res.status(500).json({
      success: false,
      error: err.message,
      errorFa: 'خطا در پردازش و ورود اطلاعات سرورها.',
    });
  }
});

