// POST /api/remote-servers/discover/bulk-add - Bulk enroll discovered servers
apiRouter.post('/remote-servers/discover/bulk-add', async (req: Request, res: Response) => {
  try {
    const { effectivePolicy, isSuperAdmin } = await resolveRequestContextPolicy(req);
    let isPermitted = false;
    if (isSuperAdmin) {
      isPermitted = true;
    } else if (effectivePolicy) {
      if (effectivePolicy.defaultServerPermissions?.add_server !== undefined) {
        isPermitted = Boolean(effectivePolicy.defaultServerPermissions.add_server);
      } else if (effectivePolicy.canAddServer !== undefined) {
        isPermitted = Boolean(effectivePolicy.canAddServer);
      } else {
        isPermitted = effectivePolicy.canManageDevices !== false;
      }
    } else {
      isPermitted = true;
    }

    if (!isPermitted) {
      return res.status(403).json({
        success: false,
        error: 'Access denied: Your account policy prohibits creating new remote servers.',
        errorFa: 'عدم دسترسی: پالیسی امنیتی حساب شما اجازه ثبت و افزودن سرور جدید به ناوگان را نمی‌دهد.',
      });
    }

    const { servers } = req.body;
    if (!Array.isArray(servers) || servers.length === 0) {
      return res.status(400).json({ success: false, error: 'Servers array is required.' });
    }

    const addedServers = [];
    for (const serverData of servers) {
      if (!serverData.ip) continue;
      const isWin = serverData.os_type === 'windows';
      const cleanUser = (serverData.win_username || serverData.win_user || serverData.ssh_username || serverData.ssh_user || '').trim();
      const payload: any = {
        name: serverData.name || (serverData.hostname ? serverData.hostname.split('.')[0] : `Server-${serverData.ip.replace(/\./g, '-')}`),
        ip: serverData.ip,
        os_type: isWin ? 'windows' : 'linux',
        server_type: isWin ? 'windows' : 'linux',
        ssh_port: serverData.ssh_port || 22,
        ssh_username: isWin ? '' : (serverData.ssh_username || serverData.ssh_user || cleanUser || 'root'),
        ssh_user: isWin ? '' : (serverData.ssh_username || serverData.ssh_user || cleanUser || 'root'),
        ssh_password: serverData.ssh_password || '',
        ssh_key: serverData.ssh_key || '',
        win_protocol: serverData.win_protocol || 'rdp',
        win_port: serverData.win_port || 3389,
        win_username: isWin ? (serverData.win_username || serverData.win_user || cleanUser || 'Administrator') : 'Administrator',
        win_user: isWin ? (serverData.win_username || serverData.win_user || cleanUser || 'Administrator') : 'Administrator',
        win_password: serverData.win_password || '',
        win_domain: serverData.win_domain || '',
        rdp_security: serverData.rdp_security || 'any',
        category: serverData.category || 'Infrastructure',
        tags: Array.isArray(serverData.tags) && serverData.tags.length > 0 ? serverData.tags : ['discovered'],
        prompt_password_on_connect: !!serverData.prompt_password_on_connect,
      };

      const created = await createRemoteServer(payload);
      addedServers.push(sanitizeRemoteServerForClient(created));
    }

    // If creator has a restricted server scope, auto-append newly enrolled server IDs to their policy
    if (
      addedServers.length > 0 &&
      effectivePolicy &&
      (effectivePolicy.targetServerScope === 'specific' ||
        (effectivePolicy.targetScope === 'specific' && effectivePolicy.targetServerScope !== 'all'))
    ) {
      try {
        const policies = await getAccessPolicies();
        const polIndex = policies.findIndex((p: any) => p.id === effectivePolicy.id);
        if (polIndex !== -1) {
          const currentTgt = Array.isArray(policies[polIndex].targetServerIds)
            ? policies[polIndex].targetServerIds
            : [];
          const newIds = addedServers.map((s: any) => s.id).filter((id: string) => Boolean(id) && !currentTgt.includes(id));
          if (newIds.length > 0) {
            policies[polIndex].targetServerIds = [...currentTgt, ...newIds];
            await saveAccessPolicies(policies);
          }
        }
      } catch (scopeUpdateErr) {
        console.warn('[Warning auto-adding servers to creator policy in bulk-add]', scopeUpdateErr);
      }
    }

    await addAuditLog({
      userName: (req.headers['x-user-name'] as string) || 'Admin',
      action: 'Bulk Add Discovered Servers',
      category: 'device',
      target: `${addedServers.length} servers`,
      status: 'success',
      details: `Enrolled ${addedServers.length} servers from discovery scan into fleet`,
      ipAddress: getClientIp(req),
      userAgent: req.headers['user-agent'] || 'WebUI',
    });

    res.json({ success: true, count: addedServers.length, servers: addedServers });
  } catch (err: any) {
    console.error('[Bulk Add Discovered Servers Error]:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

