// POST /api/remote-servers/:id/send-message - Send message to logged-in user or broadcast (strict RBAC: canSendHelpdeskMessage or Super Admin)
apiRouter.post('/remote-servers/:id/send-message', async (req: Request, res: Response) => {
  try {
    const { user: authUser, effectivePolicy, isSuperAdmin } = await resolveRequestContextPolicy(req);
    const canSendUserMessage = Boolean(isSuperAdmin || effectivePolicy?.canSendHelpdeskMessage === true);
    if (!canSendUserMessage) {
      const actor = authUser?.username || getReqOperator(req).username || 'unknown';
      await addPortalAuditLog({
        category: 'system',
        action: 'linux_send_message_denied',
        title: 'تلاش غیرمجاز برای ارسال پیام روی سیستم لینوکس',
        title_en: 'Unauthorized Terminal Message Attempt',
        description: `کاربر ${actor} فاقد مجوز صریح RBAC برای ارسال پیام روی سیستم کاربران (canSendHelpdeskMessage) است.`,
        description_en: `User ${actor} lacks RBAC permission canSendHelpdeskMessage (or Super Admin role) to send terminal/desktop messages.`,
        userName: actor,
        userRole: authUser?.role || effectivePolicy?.name || 'User',
        status: 'denied',
        severity: 'warning',
        targetName: String(req.params.id || 'remote-server'),
        clientIp: getClientIp(req),
      }).catch(() => {});
      return res.status(403).json({
        success: false,
        error: 'Access denied: Sending interactive screen/terminal messages requires explicit RBAC permission (canSendHelpdeskMessage) or Super Admin role.',
        errorFa: 'عدم دسترسی: ارسال پیام روی سیستم کاربران نیازمند مجوز صریح RBAC (canSendHelpdeskMessage) یا نقش سوپرادمین است.',
      });
    }

    const { id } = req.params;
    const { target, message, password } = req.body;

    if (!message || typeof message !== 'string') {
      return res.status(400).json({ success: false, error: 'Message is required.' });
    }

    const server = await getRemoteServerById(id);
    if (!server) {
      return res.status(404).json({ success: false, error: 'Server not found' });
    }

    const result = await sendLinuxUserMessageSSH(server, target || 'all', message, password);

    // Audit log
    await addAuditLog({
      userName: getReqOperator(req).username,
      action: `Send Terminal Message (${target || 'all'})`,
      category: 'operation',
      target: `${server.name || server.ip}`,
      status: result.success ? 'success' : 'error',
      details: result.message,
      ipAddress: getClientIp(req),
    }).catch(() => {});

    return res.json(result);
  } catch (err: any) {
    console.error(`[LinuxSendMessage API Error for server ${req.params.id}]:`, err?.message || err);
    return res.status(500).json({
      success: false,
      error: err.message || 'Failed to send message to user',
    });
  }
});

// POST /api/remote-servers/:id/logout-user - Terminate an active user session or all sessions with optional pre-logout alert
apiRouter.post('/remote-servers/:id/logout-user', async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { username, tty, delaySeconds, message, force, allSessions, password } = req.body;

    const server = await getRemoteServerById(id);
    if (!server) {
      return res.status(404).json({ success: false, error: 'Server not found' });
    }

    if (server.os_type !== 'linux') {
      return res.status(400).json({ success: false, error: 'User logout is designed for Linux servers.' });
    }

    const ephemeralPassword = password;
    if (server.prompt_password_on_connect && !ephemeralPassword && !server.ssh_password) {
      return res.status(401).json({
        success: false,
        requires_password: true,
        error: 'Password prompt required for this server (Zero-storage policy enabled).'
      });
    }

    const result = await logoutLinuxUserSessionSSH(
      server,
      {
        username,
        tty,
        delaySeconds: Number(delaySeconds) || 0,
        message,
        force: Boolean(force),
        allSessions: Boolean(allSessions),
      },
      ephemeralPassword
    );

    // Audit log
    await addAuditLog({
      userName: getReqOperator(req).username,
      action: `Logout User Session (${username || tty || 'active'})`,
      category: 'operation',
      target: `${server.name || server.ip}`,
      status: result.success ? 'success' : 'error',
      details: `${result.message} (TTY: ${tty || 'all'}, Delay: ${delaySeconds || 0}s, Force: ${Boolean(force)})`,
      ipAddress: getClientIp(req),
    }).catch(() => {});

    return res.json(result);
  } catch (err: any) {
    console.error(`[LinuxLogoutUser API Error for server ${req.params.id}]:`, err?.message || err);
    return res.status(500).json({
      success: false,
      error: err.message || 'Failed to logout user session',
    });
  }
});

// POST /api/remote-servers/:id/restart - Execute immediate or scheduled reboot or shutdown for Linux/Windows servers
apiRouter.post('/remote-servers/:id/restart', async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { delayMinutes, notifyUsers, message, force, cancelPending, password, actionType } = req.body;

    const server = await getRemoteServerById(id);
    if (!server) {
      return res.status(404).json({ success: false, error: 'Server not found' });
    }

    const ephemeralPassword = password;
    if (server.prompt_password_on_connect && !ephemeralPassword && !server.ssh_password && !server.win_password) {
      return res.status(401).json({
        success: false,
        requires_password: true,
        error: 'Password prompt required for this server (Zero-storage policy enabled).'
      });
    }

    const isWindows = server.os_type === 'windows';
    const isPowerOff = actionType === 'poweroff';
    const result = await executeServerRestartSSH(
      server,
      {
        actionType: isPowerOff ? 'poweroff' : 'restart',
        delayMinutes: Number(delayMinutes) || 0,
        notifyUsers: Boolean(notifyUsers),
        message: typeof message === 'string' ? message : undefined,
        force: force !== undefined ? Boolean(force) : true,
        cancelPending: Boolean(cancelPending),
      },
      ephemeralPassword
    );

    // Audit log
    await addAuditLog({
      userName: getReqOperator(req).username,
      action: cancelPending
        ? `Cancel Scheduled ${isPowerOff ? 'Shutdown' : 'Restart'} (${isWindows ? 'Windows' : 'Linux'})`
        : `Server ${isPowerOff ? 'Shutdown' : 'Restart'} (${isWindows ? 'Windows' : 'Linux'}, Delay: ${delayMinutes || 0}m)`,
      category: 'operation',
      target: `${server.name || server.ip}`,
      status: result.success ? 'success' : 'error',
      details: `${result.message} [Command: ${result.command}]`,
      ipAddress: getClientIp(req),
    }).catch(() => {});

    return res.json(result);
  } catch (err: any) {
    console.error(`[ServerRestart API Error for ${req.params.id}]:`, err?.message || err);
    return res.status(500).json({
      success: false,
      error: err.message || 'Failed to execute restart on remote server',
    });
  }
});

// POST /api/remote-servers/bulk-power - Execute batch restart or shutdown across selected servers
apiRouter.post('/remote-servers/bulk-power', async (req: Request, res: Response) => {
  try {
    const { serverIds, actionType, delayMinutes, notifyUsers, message, force, cancelPending, password } = req.body;

    if (!Array.isArray(serverIds) || serverIds.length === 0) {
      return res.status(400).json({ success: false, error: 'serverIds array is required' });
    }

    const context = await resolveRequestContextPolicy(req);
    const { effectivePolicy, isSuperAdmin, allowedServerIds } = context;
    let targetIds: string[] = serverIds;
    if (!isSuperAdmin && effectivePolicy) {
      if (allowedServerIds !== null) {
        const allowedSet = new Set(allowedServerIds.map((id) => (id || '').trim().toLowerCase()));
        targetIds = serverIds.filter((id: string) => allowedSet.has((id || '').trim().toLowerCase()));
      }
      targetIds = targetIds.filter(
        (id: string) => evaluateServerActionDecision(effectivePolicy, id, 'power_control') !== 'deny'
      );
      if (targetIds.length === 0) {
        return res.status(403).json({
          success: false,
          error: 'Access denied: You do not have permission to execute power operations on the requested servers under your assigned RBAC policy in PostgreSQL.',
        });
      }

      const approvalRequiredIds = targetIds.filter(
        (id: string) => evaluateServerActionDecision(effectivePolicy, id, 'power_control') === 'require_approval'
      );
      if (approvalRequiredIds.length > 0) {
        const actor = buildApprovalActor(req, context);
        const isSingle = approvalRequiredIds.length === 1;
        const primarySrv = isSingle ? await getRemoteServerById(approvalRequiredIds[0]) : null;
        const bulkParams: Record<string, any> = {
          serverIds: targetIds,
          actionType,
          delayMinutes,
          force,
        };
        const signedExec = buildSignedHttpExecutionPayload({
          method: req.method || 'POST',
          originalUrl: req.originalUrl || req.url || '',
          body: req.body,
          entityType: 'server',
          entityId: isSingle ? approvalRequiredIds[0] : 'bulk',
          actionKey: 'power_control',
          requesterUsername: actor.username,
        });
        if (signedExec) bulkParams._httpExecution = signedExec;
        const gateRes = await evaluateApprovalGateForRequest({
          actor,
          effectivePolicy,
          entityType: 'server',
          entityId: isSingle ? approvalRequiredIds[0] : 'bulk',
          entityName: isSingle
            ? primarySrv?.name || primarySrv?.ip || approvalRequiredIds[0]
            : `${approvalRequiredIds.length} Selected Servers`,
          actionKey: 'power_control',
          requestedAction: `Bulk Power Control (${actionType || 'restart'} on ${targetIds.length} server(s))`,
          commandPreview: buildSafeCommandPreview(req, { action: 'power_control' }),
          actionParams: bulkParams,
          providedApprovalId: extractProvidedApprovalId(req),
        });
        if (!gateRes.allowed) {
          res.setHeader('X-Approval-Required', 'true');
          return res.status(403).json({ success: false, ...gateRes.gatePayload });
        }
        (req as any).__approvedTicketCtx = {
          actor,
          ticketId: gateRes.approvedTicket.id,
          grantId: gateRes.activeGrant?.id || null,
          actionKey: 'power_control',
          executionNote: `Executed bulk-power (${actionType || 'restart'}) on ${targetIds.length} server(s) via ${gateRes.approvedTicket.id}`,
        };
      }
    }

    const isPowerOff = actionType === 'poweroff';
    const clientIp = getClientIp(req);

    const results = await Promise.allSettled(
      targetIds.map(async (id: string) => {
        const server = await getRemoteServerById(id);
        if (!server) {
          throw new Error('Server not found');
        }

        const ephemeralPassword = password;
        if (server.prompt_password_on_connect && !ephemeralPassword && !server.ssh_password && !server.win_password) {
          throw new Error('Password prompt required (Zero-storage policy)');
        }

        const res = await executeServerRestartSSH(
          server,
          {
            actionType: isPowerOff ? 'poweroff' : 'restart',
            delayMinutes: Number(delayMinutes) || 0,
            notifyUsers: Boolean(notifyUsers),
            message: typeof message === 'string' ? message : undefined,
            force: force !== undefined ? Boolean(force) : true,
            cancelPending: Boolean(cancelPending),
          },
          ephemeralPassword
        );

        // Audit log per server
        await addAuditLog({
          userName: getReqOperator(req).username,
          action: cancelPending
            ? `Bulk Cancel Scheduled ${isPowerOff ? 'Shutdown' : 'Restart'} (${server.os_type})`
            : `Bulk Server ${isPowerOff ? 'Shutdown' : 'Restart'} (${server.os_type}, Delay: ${delayMinutes || 0}m)`,
          category: 'operation',
          target: `${server.name || server.ip}`,
          status: res.success ? 'success' : 'error',
          details: `${res.message} [Command: ${res.command}]`,
          ipAddress: clientIp,
        }).catch(() => {});

        return {
          serverId: server.id,
          serverName: server.name,
          ip: server.ip,
          osType: server.os_type,
          success: res.success,
          message: res.message,
          command: res.command,
          output: res.output,
        };
      })
    );

    const formattedResults = results.map((r, idx) => {
      if (r.status === 'fulfilled') {
        return r.value;
      } else {
        return {
          serverId: serverIds[idx],
          serverName: `Server #${idx + 1}`,
          ip: '',
          osType: 'unknown',
          success: false,
          message: r.reason?.message || 'Execution failed',
          command: '',
          error: r.reason?.message || 'Execution failed',
        };
      }
    });

    const anySuccess = formattedResults.some((r) => r.success);
    return res.json({
      success: anySuccess,
      results: formattedResults,
    });
  } catch (err: any) {
    console.error('[BulkServerPower API Error]:', err?.message || err);
    return res.status(500).json({
      success: false,
      error: err.message || 'Failed to execute bulk power action',
    });
  }
});

